const books = [
    { title: "The History of the Standard Oil Company", author: "Ida Tarbell", category: "Historia / Economía", coverId: 313809, description: "Pioneering 1904 muckraking investigation that exposes the predatory tactics by which Standard Oil was built into an industrial monopoly: railroad rebates, predatory pricing, espionage and the systematic destruction of competitors. The exposé helped trigger the antitrust laws that broke up the trust seven years later and set the template for investigative business journalism for the rest of the twentieth century.", descriptionAi: true },
    { title: "La isla misteriosa", author: "Julio Verne", category: "Aventura", coverId: 419656, description: "Cinco prisioneros de guerra huyen en globo durante la guerra de Secesión estadounidense y caen en una isla desierta del Pacífico Sur. Allí, con la pura razón, fabrican herramientas, cultivos, hogares y una pequeña civilización autosuficiente —siempre vigilados, en la sombra, por un misterioso protector cuya identidad la novela revela en el final.", descriptionAi: true },
    { title: "De la Tierra a la Luna", author: "Julio Verne", category: "Ciencia Ficción", coverId: 13478412, description: "Tras el fin de la Guerra Civil estadounidense, los miembros del Gun Club de Baltimore se aburren sin nuevas armas que diseñar y proyectan un cañón gigantesco capaz de enviar un proyectil tripulado hasta la Luna. La novela combina cálculos balísticos plausibles, humor gentil sobre la cultura técnica norteamericana y la apertura de un imaginario espacial al alcance de la imaginación decimonónica.", descriptionAi: true },
    { title: "Antifrágil", author: "Nassim Nicholas Taleb", category: "Filosofía / Economía", coverId: 9180157, status: "read", rating: 5, description: "Más allá de la resistencia y la resiliencia existen sistemas que se benefician del estrés, el caos y la volatilidad: se vuelven más fuertes cuanto más son sacudidos. Tercera entrega del Incerto, propone estrategias concretas para diseñar instituciones, decisiones financieras y proyectos personales que prosperen en la incertidumbre en lugar de ser destruidos por ella. Mezcla anécdotas históricas, mitología y matemáticas para defender una ética opuesta al optimizar y al planificar a toda costa.", descriptionAi: true },
    { title: "El cisne negro", author: "Nassim Nicholas Taleb", category: "Filosofía / Economía", coverId: 12344090, status: "read", rating: 5, description: "Los hechos de gran impacto y probabilidad mínima dominan la historia, la economía y la vida personal mucho más de lo que sospechamos. La tesis recorre los mercados financieros, la ciencia y la guerra para mostrar cómo construimos relatos retrospectivos que disfrazan la aleatoriedad de causalidad. Un libro fundamental sobre los límites del conocimiento y sobre lo que las distribuciones de cola larga implican para tomar decisiones.", descriptionAi: true },
    { title: "Superfreakonomics", author: "Stephen J. Dubner y Steven D. Levitt", category: "Economía", coverId: 6304875, status: "read", rating: 3, description: "Sequel to the original microeconomic experiment, now applied to prostitutes, drunk walking, climate engineering, hospital data and altruism. Brings the same trademark mix of clever empirical research and contrarian punch line, with chapters that work as self-contained essays. The argument is that incentives, properly identified, explain more behaviour than morality.", descriptionAi: true },
    { title: "Las aventuras de Sherlock Holmes", author: "Arthur Conan Doyle", category: "Misterio", coverId: 10547050, description: "Doce relatos publicados en 1892 que reúnen los casos más célebres del detective de Baker Street y de su amigo el doctor Watson. Cada cuento es una pieza autónoma —desde «Escándalo en Bohemia» hasta «La banda de lunares»— que combina deducción, atmósfera victoriana y un humor seco a partes iguales. La colección fija el molde del relato policial moderno y consolida la figura del detective consultor.", descriptionAi: true },
    { title: "La loca de Gandoca", author: "Anacristina Rossi", category: "Novela", coverId: 5085541, description: "Daniela, joven funcionaria del Ministerio de Recursos Naturales, denuncia la complicidad del Estado con el desarrollo turístico depredador en el Refugio Gandoca-Manzanillo, en el Caribe sur de Costa Rica. La novela mezcla los apuntes del diario, los oficios administrativos y las cartas para retratar la lucha por un trozo de costa contra la connivencia de empresarios e instituciones.", descriptionAi: true },
    { title: "Gestión del desarrollo sostenible en territorios rurales: Métodos para la planificación", author: "Varios autores", category: "Desarrollo rural", coverUrl: "https://repositorio.iica.int/server/api/core/bitstreams/c3daae59-a3c9-4f76-8507-0637edd408ef/content", description: "Manual técnico publicado por el IICA: ofrece métodos participativos y herramientas analíticas para diseñar planes de desarrollo rural sostenible a escala territorial. Cubre el diagnóstico socioeconómico, el ordenamiento de cuencas, la priorización de inversiones y los mecanismos de gobernanza local. Útil para extensionistas, alcaldes y técnicos que necesitan articular comunidades, ambiente y economía agraria.", descriptionAi: true },
    { title: "Lo rural es diverso: Evidencia para el caso de Costa Rica", author: "Varios autores", category: "Desarrollo rural", coverUrl: "https://repositorio.iica.int/server/api/core/bitstreams/5346654a-741f-41c4-a21d-9d0ae37feb3f/content", description: "Investigación que cuestiona la imagen monolítica del campo costarricense y documenta su pluralidad de territorios, actividades económicas, formas de tenencia, perfiles demográficos y modos de vida. Aporta evidencia empírica para diseñar políticas rurales que no traten a «el campo» como un solo cliente.", descriptionAi: true },
    { title: "Cultivando mejor para alimentar a todos", author: "Varios autores", category: "Agricultura", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1685972894i/173724991.jpg", description: "Compilación de prácticas y políticas para fortalecer la agricultura familiar en América Latina, con casos de extensión técnica, asociatividad campesina, encadenamientos productivos y mercados locales. Pensado para personas decisoras y técnicos del IICA y de los ministerios agropecuarios de la región.", descriptionAi: true },
    { title: "The 99% Invisible City: A Field Guide to the Hidden World of Everyday Design", author: "Roman Mars y Kurt Kohlstedt", category: "Diseño / Urbanismo", coverId: 10391260, description: "Companion volume to the long-running podcast on the unseen design choices behind cities: fire hydrants, manhole covers, sidewalk markings, traffic lights, building setbacks and even paint on curbs. Each short chapter takes a small object and explains how it shapes daily life, who decided it should look that way and what it would mean to design it differently. Reads like a stroll through urban history with a hand lens.", descriptionAi: true },
    { title: "The Name of the Wind", author: "Patrick Rothfuss", category: "Fantasía", coverId: 11480483, status: "read", rating: 5, description: "First volume of the Kingkiller Chronicle. Kvothe, now a quiet innkeeper at the Waystone Inn, agrees to tell a Chronicler his life story over three days: childhood in a troupe of itinerant performers, the massacre of his family by the legendary Chandrian, years of beggary in the streets of Tarbean, and his admission to the secretive University. A coming-of-age in a richly imagined world, with prose as musical as the lute its protagonist plays.", descriptionAi: true },
    { title: "Creativity, Inc.", author: "Ed Catmull con Amy Wallace", category: "Negocios / Creatividad", coverId: 13124793, status: "read", rating: 5, description: "Behind-the-scenes account of how Pixar Animation Studios was built and kept innovative across two decades. Rather than a how-to manual, the book offers principles about candor, fear, mistakes, and the rituals —the Braintrust, the postmortem— that allow a creative team to keep producing breakthrough work. Filled with anecdotes from the making of Toy Story, Up, Wall-E and others.", descriptionAi: true },
    { title: "Alchemy: The Dark Art and Curious Science of Creating Magic in Brands, Business, and Life", author: "Rory Sutherland", category: "Marketing", coverId: 10184444, description: "Argues that the most powerful business and policy ideas are usually irrational, counter-intuitive and untestable. Drawing on behavioral economics, design and decades inside an ad agency, it urges decision-makers to embrace psychology over spreadsheets and to value «psycho-logic» that produces real-world results, even when nobody can prove why it worked. Equal parts manifesto and entertainment.", descriptionAi: true },
    { title: "El fin de Mr. Y", author: "Scarlett Thomas", category: "Novela", coverId: 115878, description: "Una estudiante de doctorado tropieza con la única copia conocida de un libro maldito del siglo XIX que abre la puerta a la troposfera: un plano interior donde es posible saltar de mente en mente. Lo que empieza como curiosidad académica se convierte en una persecución internacional entre físicos teóricos, agentes secretos y filósofos del lenguaje. La novela mezcla metafísica, mecánica cuántica y suspense con una protagonista insomne y memorable.", descriptionAi: true },
    { title: "Una breve historia de casi todo", author: "Bill Bryson", category: "Divulgación científica", coverId: 14058009, status: "read", rating: 4, description: "Recorrido sin ínfulas por la historia de la ciencia: del Big Bang a la tabla periódica, de la deriva continental al ADN, pasando por las extinciones masivas y la lluvia de polvo cósmico. La voz narradora —curiosa, autoirónica, profundamente legible— acompaña al lector hasta los confines del conocimiento contemporáneo y muestra el quién y el cómo detrás de cada descubrimiento. Una de las introducciones más cariñosas a la curiosidad científica.", descriptionAi: true },
    { title: "Pensar rápido, pensar despacio", author: "Daniel Kahneman", category: "Psicología", coverId: 13290711, status: "read", rating: 5, description: "El cerebro funciona con dos sistemas: uno rápido, intuitivo y emocional; otro lento, deliberativo y exigente. Décadas de investigación experimental en economía conductual y psicología cognitiva sirven para mapear los sesgos sistemáticos que distorsionan nuestras decisiones cotidianas y las más importantes. Un libro denso pero accesible que ha reescrito la manera en que ahora pensamos sobre el juicio humano, la racionalidad y el bienestar.", descriptionAi: true },
    { title: "The End of Alchemy", author: "Mervyn King", category: "Economía", coverId: 8875505, description: "Diagnoses the deep flaws of modern money, banking and the global economy that produced the 2008 crisis. Written by a former Bank of England governor, it argues that the alchemy of turning illiquid loans into supposedly safe demand deposits is structurally unstable and proposes a redesign in which the central bank explicitly becomes a «pawnbroker for all seasons».", descriptionAi: true },
    { title: "Never Split the Difference", author: "Chris Voss con Tahl Raz", category: "Negociación", coverId: 8365942, status: "read", rating: 5, description: "A former FBI lead hostage negotiator distills techniques used in life-or-death situations into a practical guide for everyday negotiation: salary talks, business deals, family disputes. Key tools include mirroring, labeling, calibrated questions and the strategic use of «no». The premise: negotiation is emotional intelligence on overdrive, not a battle of logic.", descriptionAi: true },
    { title: "El teorema Katherine", author: "John Green", category: "Novela juvenil", coverId: 14559681, status: "read", rating: 4, description: "Colin Singleton, un niño prodigio obsesionado con anagramas, sale de gira en un road trip por el sur de Estados Unidos con su mejor amigo después de que su décimo-novena novia llamada Katherine lo dejara. Su misión: convertir las relaciones rotas en una fórmula matemática que prediga toda historia de amor. Una novela juvenil que cruza humor, matemática informal y una reflexión sutil sobre la identidad y la diferencia entre ser único y ser interesante.", descriptionAi: true },
    { title: "The Wasp That Brainwashed the Caterpillar", author: "Matt Simon", category: "Divulgación científica", coverId: 12818938, description: "Tour of evolution's strangest experiments: the wasp that turns a caterpillar into a zombie bodyguard, the snail with eye-stalks taken over by a parasite, the flatworm with a death-spiral life cycle. Each chapter is a short, vivid portrait of an organism whose existence rewrites assumptions about how life can be lived. Curiosity-driven natural history at its most contagious.", descriptionAi: true },
    { title: "La broma infinita", author: "David Foster Wallace", category: "Novela", coverId: 8083760, status: "to-read", description: "Novela monumental ambientada en una academia de tenis y en un centro de rehabilitación a las afueras de Boston, en un futuro cercano donde los años llevan nombre de patrocinador. Una película llamada «La broma infinita» es tan adictiva que quien la ve no puede volver a hacer otra cosa. El libro se ramifica en cientos de notas al pie para retratar la adicción, la dependencia, el entretenimiento como castigo y la pregunta de qué nos hace seguir buscando placer cuando ya nada nos sostiene.", descriptionAi: true },
    { title: "Piénsalo otra vez", author: "Adam Grant", category: "Psicología", coverId: 13484415, status: "read", rating: 5, description: "Un argumento a favor de la duda como herramienta intelectual: cuestionar las propias certezas es un hábito que se entrena. Distingue entre los modos de razonamiento de predicador, fiscal, político y científico, y propone prácticas concretas para repensar ideas con humildad, curiosidad y rigor. Lleno de estudios y casos —de bomberos a magnates— sobre cuándo cambiar de opinión es señal de sabiduría y no de debilidad.", descriptionAi: true },
    { title: "Integrating Food into Urban Planning", author: "Yves Cabannes y Cecilia Marocchino", category: "Urbanismo", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1550976346i/43257461.jpg", description: "Edited volume that maps how cities around the world are bringing food security and urban agriculture into mainstream planning. Includes case studies on community gardens, peri-urban farming, public markets, food councils and land-use policies designed to keep food production close to consumers. A planning manual for the food-system turn in twenty-first-century urbanism.", descriptionAi: true },
    { title: "Deshaciendo errores", author: "Michael Lewis", category: "Psicología / Economía", coverId: 9595637, status: "read", rating: 5, description: "La amistad y la obra conjunta de Daniel Kahneman y Amos Tversky, los psicólogos que pusieron en evidencia los sesgos cognitivos del juicio humano y fundaron la economía conductual. La narrativa retrata a dos mentes complementarias —uno introvertido y rumiante, otro extrovertido y brillante— y sigue la trayectoria de su colaboración desde Jerusalén hasta el Nobel de Economía. Biografía intelectual y libro de divulgación al mismo tiempo.", descriptionAi: true },
    { title: "Yo contengo multitudes", author: "Ed Yong", category: "Divulgación científica", coverId: 8085300, status: "read", rating: 4, description: "Viaje al mundo microbiano que vive dentro y fuera de nuestros cuerpos: bacterias, virus y hongos cooperan, compiten y nos hacen, en buena medida, lo que somos. La narración pasa de las hidrotermales submarinas a las heces fecales experimentales para mostrar cómo el microbioma redefine las fronteras del individuo. Una de las mejores piezas recientes de divulgación científica.", descriptionAi: true },
    { title: "Mi novia se cayó en un pozo ciego", author: "Diego Delfino", category: "Crónica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1383667250i/18631743.jpg", status: "read", rating: 4, description: "Antología de columnas y relatos breves escritos en clave de humor sobre el absurdo cotidiano, las relaciones contemporáneas, el periodismo argentino y la vida después de internet. La prosa pasa con facilidad del chiste a la melancolía y del paseo por Buenos Aires a la reflexión sobre la amistad. Un libro de mesita de noche, perfecto para leer una pieza por noche.", descriptionAi: true },
    { title: "Cien años de soledad", author: "Gabriel García Márquez", category: "Novela", coverId: 12627383, status: "read", rating: 4, description: "Saga novelística de la familia Buendía a lo largo de seis generaciones en el pueblo imaginario de Macondo, fundado en mitad de la selva colombiana por José Arcadio. El relato cuenta guerras civiles, plagas de hormigas, mariposas amarillas, dictaduras bananeras y un final cíclico donde toda la historia familiar se revela como una sola lectura. Cumbre del realismo mágico y una de las novelas más leídas en lengua española.", descriptionAi: true },
    { title: "¿Existe la suerte?", author: "Nassim Nicholas Taleb", category: "Filosofía", coverId: 12344622, status: "read", rating: 5, description: "Primera entrega del Incerto: una arremetida contra la confusión entre habilidad y casualidad en los mercados, los deportes, la política y la ciencia. Recurre a la historia de la probabilidad, a los antiguos griegos y a anécdotas de operadores de bolsa para mostrar cómo las falacias narrativas hacen que veamos talento donde solo hubo ruido. Un manifiesto epistemológico para escépticos del éxito.", descriptionAi: true },
    { title: "El infinito en un junco", author: "Irene Vallejo", category: "Ensayo", coverId: 9689877, status: "read", rating: 5, description: "Recorrido por la vida del libro como objeto: del papiro de Alejandría a los códices medievales y los pergaminos monásticos. La narración entrelaza historia material, biografías de bibliotecarias, lectoras y censores, y momentos personales para contar cómo la humanidad inventó —y reinventó— el dispositivo que sostiene la civilización letrada. Ensayo narrativo escrito como una larga carta a quien todavía lee.", descriptionAi: true },
    { title: "Sustainable Food Systems for All", author: "Varios autores", category: "Sostenibilidad", coverId: 14421251, description: "Compendium of policies, technologies and social arrangements required to transition food systems toward sustainability while keeping them inclusive for smallholders and the global poor. Covers agroecology, nutrition transitions, public procurement, fisheries and policy coherence across ministries. Aimed at decision-makers, researchers and civil-society networks working on the food crisis.", descriptionAi: true },
    { title: "La democracia en América", author: "Alexis de Tocqueville", category: "Política", coverId: 13556872, description: "Resultado de un viaje de nueve meses por Estados Unidos en 1831: una observación atenta y desencantada de la igualdad de condiciones, la cultura política, las asociaciones civiles y los hábitos religiosos de la joven república. Analiza con visión profética las fortalezas del sistema y sus riesgos —entre ellos la «tiranía de la mayoría» y el conformismo social— y se convierte en una obra fundacional de la ciencia política moderna.", descriptionAi: true },
    { title: "El movimiento cooperativo en Costa Rica", author: "Óscar Aguilar Bulgarelli y Carlos Luis Fallas Monge", category: "Historia económica", description: "Estudio histórico sobre el origen y desarrollo del cooperativismo costarricense desde fines del siglo XIX hasta el segundo tercio del XX. Recorre los marcos legales que lo posibilitaron, las cooperativas pioneras —café, vivienda, ahorro y crédito— y su papel como pilar de la economía nacional y de la integración social del campesinado. Un documento de referencia para entender un componente fundamental del modelo costarricense.", descriptionAi: true },
    { title: "Momentos estelares de la humanidad", author: "Stefan Zweig", category: "Historia", coverId: 13226425, status: "read", rating: 4, description: "Catorce instantes históricos en los que el destino del mundo se decidió en cuestión de horas o de minutos: la caída de Constantinopla, el descubrimiento del Pacífico, la huida de Napoleón de Elba, la rendición de Lenin tras volver a Rusia en tren. Cada estampa está narrada con la economía y el pulso de un relato breve, casi un drama corto.", descriptionAi: true },
    { title: "Anna Karenina", author: "Lev Tolstói", category: "Novela clásica", coverId: 12327215, description: "Novela monumental sobre la pasión adúltera entre Anna y el conde Vronski, paralela a la vida rural y reflexiva de Kostia Levin. El contraste entre las dos historias dibuja un retrato monumental de la sociedad rusa del siglo XIX —ciudad y campo, aristocracia y servidumbre, fe y secularización— y abre una de las novelas más leídas y discutidas de la literatura universal.", descriptionAi: true },
    { title: "Ilíada", author: "Homero", category: "Épica clásica", coverId: 10540134, description: "Poema épico que narra unos pocos días decisivos del décimo año del asedio aqueo a Troya, centrados en la cólera de Aquiles tras una ofensa de Agamenón y en el destino del príncipe troyano Héctor. El verso alternancia escenas de furia, ternura familiar e intervenciones divinas, con un sentido trágico del honor, el destino y la guerra. Texto fundacional de la literatura occidental, leído y reescrito durante casi tres mil años.", descriptionAi: true },
    { title: "Dioses y héroes: Leyendas de la antigüedad clásica", author: "Gustav Schwab", category: "Mitología", coverId: 997804, description: "Antología clásica de mitos griegos publicada en alemán a mediados del XIX y traducida a casi todas las lenguas: la creación del mundo, los doce trabajos de Heracles, los Argonautas, la guerra de Troya y el regreso de Odiseo. Ordena las leyendas en un hilo narrativo continuo y las cuenta con una claridad pensada para acompañar tanto al lector adulto como al juvenil. Una puerta de entrada al imaginario clásico que sigue siendo de referencia.", descriptionAi: true },
    { title: "Wild Rituals", author: "Caitlin O'Connell", category: "Naturaleza", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1606865252i/56133074.jpg", description: "Decades of fieldwork with elephants, baboons, wolves and other social mammals are condensed into ten rituals that humans share with other species: greetings, courtship, grief, play, gift-giving, group decisions, conflict resolution. Watching animals perform these rituals casts familiar human ceremonies in a new light and suggests how much of «culture» predates language.", descriptionAi: true },
    { title: "Cometas en el cielo", author: "Khaled Hosseini", category: "Novela", coverId: 12328138, status: "to-read", description: "Amistad rota entre Amir y Hassan en el Kabul previo a la invasión soviética; la culpa de una traición infantil persigue al protagonista hasta su exilio en California y lo lleva, ya adulto, a regresar a un Afganistán bajo el dominio talibán. La novela cuenta la historia reciente de un país a través de un duelo personal por la pureza perdida.", descriptionAi: true },
    { title: "Stillness Is the Key", author: "Ryan Holiday", category: "Filosofía / Estoicismo", coverId: 10203119, description: "Third in a popular series on Stoic virtues, devoted to stillness as the underlying capacity that lets every other excellence flourish. The book moves from the mind to the soul to the body, drawing on Marcus Aurelius, Anne Frank, Tiger Woods and Mr. Rogers to argue that disciplined inner quiet is the precondition for clear judgement and meaningful work.", descriptionAi: true },
    { title: "The Obstacle Is the Way", author: "Ryan Holiday", category: "Filosofía / Estoicismo", coverId: 14428233, status: "read", rating: 5, description: "Modern adaptation of the Stoic doctrine that what stands in the way becomes the way. Through historical case studies —John D. Rockefeller, Ulysses Grant, Demosthenes, Steve Jobs— the book teaches how to perceive obstacles accurately, act on them without flinching and convert adversity into propulsion. A short, punchy manual that helped popularize Stoicism for a new generation.", descriptionAi: true },
    { title: "El corazón de las tinieblas", author: "Joseph Conrad", category: "Novela clásica", coverId: 12325082, status: "read", rating: 4, description: "El marinero Charlie Marlow recuerda ante sus compañeros un viaje por el río Congo en busca del enigmático agente comercial Kurtz. La travesía río arriba se transforma en un descenso a los abismos del colonialismo europeo, en una crítica feroz a la civilización «iluminada» y en una pregunta inquietante sobre la condición humana. Una novela corta que cabe en un día de lectura y se queda en la memoria para siempre.", descriptionAi: true },
    { title: "Decidido", author: "Robert Sapolsky", category: "Neurociencia", coverId: 14049171, status: "read", rating: 5, description: "Síntesis de neurobiología, genética y filosofía para argumentar, paso a paso, que no existe el libre albedrío en el sentido que solemos darle a la expresión. La consecuencia ética y social de aceptarlo —dejar de odiar al otro como si pudiera haber elegido otra cosa— se vuelve el eje del libro. Una continuación natural y radical de la obra previa sobre estrés y comportamiento.", descriptionAi: true },
    { title: "Diferentes", author: "Frans de Waal", category: "Etología", coverId: 14128514, status: "read", rating: 5, description: "Revisión de décadas de etología de primates para mostrar que las diferencias entre sexos en los humanos son más matizadas, plásticas y dependientes del contexto de lo que sugiere el binario cultural. Mezcla observaciones de bonobos, chimpancés y humanos con un humor amable y una clara intención política: separar los datos biológicos de los estereotipos de género.", descriptionAi: true },
    { title: "En agosto nos vemos", author: "Gabriel García Márquez", category: "Novela", coverId: 14636533, status: "read", rating: 5, description: "Ana Magdalena Bach viaja cada año, el dieciséis de agosto, a una pequeña isla del Caribe colombiano para visitar la tumba de su madre. En cada visita escoge un amante distinto, y el libro va siguiendo cómo esos encuentros transforman su vida conyugal y su sentido del deseo. Novela póstuma corta, escrita en la mejor prosa colombiana del siglo XX.", descriptionAi: true },
    { title: "Humor, Seriously", author: "Jennifer Aaker y Naomi Bagdonas", category: "Negocios", coverId: 10389344, status: "read", rating: 5, description: "Four years of Stanford research distilled into a guide to why humor builds power, trust and resilience at work, and to how anyone can use it skillfully without becoming a class clown. Covers the four humor styles, the science behind funny, and how to deploy levity in meetings, presentations and tough conversations. Funny by design.", descriptionAi: true },
    { title: "Una tierra prometida", author: "Barack Obama", category: "Memorias", coverId: 10449357, status: "to-read", description: "Primer tomo de unas memorias presidenciales que abarcan la transición de Illinois al Senado nacional, las primarias del 2008, la victoria histórica y la primera mitad del mandato hasta la operación contra Bin Laden. Más que un libro de logros, es una crónica honesta de las contradicciones del poder, de la ambición que lo lleva a uno hasta la Casa Blanca y de los costos personales y políticos de gobernar en un país profundamente polarizado.", descriptionAi: true },
    { title: "El gen", author: "Siddhartha Mukherjee", category: "Divulgación científica", coverId: 11320163, status: "to-read", description: "La historia íntima del concepto de gen, desde los experimentos con guisantes en el siglo XIX hasta la edición del genoma con CRISPR. Entrelaza memoria familiar (con una saga de enfermedad mental como hilo conductor), historia de la ciencia y reflexión bioética para preguntar quiénes somos cuando podemos rescribirnos a nivel molecular. Una obra ambiciosa, narrada con la prosa de un médico que es también un escritor de raza.", descriptionAi: true },
    { title: "La transformación de la mente moderna", author: "Jonathan Haidt y Greg Lukianoff", category: "Psicología social", coverId: 10138103, status: "read", rating: 5, description: "Diagnóstico sobre cómo tres «grandes falsedades» —que somos frágiles, que las emociones siempre dicen la verdad y que la vida es una guerra entre buenos y malos— se han instalado en las universidades estadounidenses y han empeorado el debate público y la salud mental de los jóvenes. Propone, en clave estoica y liberal, antídotos pedagógicos basados en la terapia cognitiva, el desacuerdo civil y la antifragilidad.", descriptionAi: true },
    { title: "Monje y robot", author: "Becky Chambers", category: "Ciencia ficción", coverId: 10476616, status: "read", rating: 5, description: "Edición conjunta de dos novelas cortas. En un planeta donde la tecnología y la naturaleza alcanzaron hace siglos un pacto, un monje del té dedicado a escuchar a los humanos y un robot construido a la naturaleza recorren bosques y aldeas preguntándose qué necesita la gente cuando ya no necesita nada material. Solarpunk gentil y filosóficamente serio.", descriptionAi: true },
    { title: "En deuda: Una historia alternativa de la economía", author: "David Graeber", category: "Economía / Antropología", coverId: 6299464, status: "read", rating: 5, description: "Cinco mil años de historia de la deuda demuestran que el crédito antecede al dinero y al trueque, que las economías humanas se organizan tanto sobre la obligación como sobre el intercambio y que los grandes ciclos políticos han pivotado sobre la cancelación o la perpetuación de las deudas. Un argumento antropológico que desmonta el relato ortodoxo de los economistas y replantea qué es realmente una economía.", descriptionAi: true },
    { title: "El futuro por decidir", author: "Christiana Figueres y Tom Rivett-Carnac", category: "Medio ambiente", coverId: 9296919, status: "to-read", description: "Escrito por dos arquitectos del Acuerdo de París, contrapone dos escenarios climáticos posibles para 2050 —la inacción y la transformación— y propone una hoja de ruta práctica de acciones individuales y colectivas. Combina datos científicos rigurosos con un tono deliberadamente esperanzado: no porque la crisis sea menor, sino porque la desesperación es una mala estrategia política frente a la emergencia.", descriptionAi: true },
    { title: "Contra el estado", author: "James C. Scott", category: "Política / Antropología", coverId: 10381520, status: "read", rating: 5, description: "Los primeros Estados de Mesopotamia y de otras regiones se construyeron sobre la coerción, la esclavitud, el monocultivo del cereal y los registros tributarios. La tesis propone una historia alternativa de la civilización en la que los siglos en los que «no había Estado» no eran de barbarie sino de libertad, salud y diversidad alimentaria. Una sacudida a los relatos heredados sobre la civilización.", descriptionAi: true },
    { title: "The Matter with Things, Vol. II: What Then Is True?", author: "Iain McGilchrist", category: "Filosofía", coverId: 13219680, status: "to-read", description: "Second volume of a sequel to The Master and His Emissary. Building on the brain hemispheres and the structure of attention developed in volume one, it argues for a metaphysics that takes seriously matter, life, value, time, space and even the divine. A demanding but rewarding synthesis of neuroscience, philosophy of science and contemplative thought.", descriptionAi: true },
    { title: "The Matter with Things, Vol. I: The Ways to Truth", author: "Iain McGilchrist", category: "Filosofía", coverId: 13219680, status: "to-read", description: "First volume of an exhaustive two-volume project on perception, attention, judgment and reasoning. The book argues that the brain's two hemispheres attend to the world in genuinely different ways and that the modern overreliance on the left hemisphere has narrowed our access to truth. Long, careful and unusually well-illustrated.", descriptionAi: true },
    { title: "Material World", author: "Ed Conway", category: "Divulgación / Materiales", coverId: 14591884, status: "to-read", description: "Tells the story of the six raw materials that built the modern world —sand, salt, iron, copper, oil and lithium— and the immense extractive networks hidden behind everyday objects. The narrative travels from desert sand pits to lithium triangles in the Andes and reveals just how dependent the supposedly weightless digital economy still is on physical stuff.", descriptionAi: true },
    { title: "White Hot Hate", author: "Dick Lehr", category: "Crónica / Periodismo", coverId: 14424872, description: "Pulitzer-winning investigation of a 2016 plot by a Kansas militia, the Crusaders, to bomb an apartment building of Somali refugees the day after the U.S. presidential election. The reporting traces how three middle-aged men were radicalized into white supremacy in rural America and how the FBI used a paid informant to bring the plot down without bloodshed.", descriptionAi: true },
    { title: "Jerks at Work", author: "Tessa West", category: "Psicología organizacional", coverId: 12603134, status: "read", rating: 4, description: "A NYU social psychologist classifies the seven kinds of toxic colleagues you are likely to meet —the kiss-up/kick-down, the credit stealer, the gaslighter, the micromanager— and offers research-backed tactics to defuse each. The framework helps the reader stop blaming themselves for office friction and start running smarter experiments at work.", descriptionAi: true },
    { title: "Trabajos de mierda", author: "David Graeber", category: "Antropología", coverId: 8798647, status: "read", rating: 5, description: "Diagnóstico antropológico de una paradoja contemporánea: una parte enorme del empleo en oficinas, consultoras, burocracias y plataformas no aporta valor a quienes lo realizan ni a la sociedad y produce sufrimiento psíquico. El libro tipologiza —«lacayos», «tachatuercas», «taimados»— y propone, en el final, ideas para reducir el peso moral del trabajo inútil. Una crítica al productivismo desde la izquierda libertaria.", descriptionAi: true },
    { title: "El amanecer de todo: Una nueva historia de la humanidad", author: "David Graeber y David Wengrow", category: "Antropología / Historia", coverId: 11359192, status: "read", rating: 5, description: "Revisa, con la arqueología más reciente, los relatos lineales sobre el origen de la civilización y muestra que las sociedades prehistóricas fueron mucho más variadas, igualitarias y conscientes políticamente de lo que la versión Hobbes-Rousseau supone. Propone que la humanidad ensayó durante decenas de miles de años regímenes sociales muy distintos —con autoridad y sin ella— y que las jaulas del Estado y la propiedad no eran inevitables.", descriptionAi: true },
    { title: "El estrecho sendero entre deseos", author: "Patrick Rothfuss", category: "Fantasía", coverId: 7309640, status: "to-read", description: "Novela breve ambientada en la Cuatro Esquinas: durante un solo día, Bast, el aprendiz fae de Kvothe, recorre el pueblo concediendo favores en clave de cuento de hadas a los niños que sepan pagarlos con secretos. La prosa tiene la misma cadencia musical de la trilogía mayor y aprovecha la economía de las pocas páginas para explorar la moralidad enrevesada de los seres mágicos que no son ni buenos ni malos.", descriptionAi: true },
    { title: "80 Tools for Participatory Development", author: "Frans Geilfus", category: "Desarrollo participativo", coverUrl: "https://repositorio.iica.int/server/api/core/bitstreams/53681510-c8b7-4e6f-8510-9d50b56b3daf/content", description: "Field-tested manual gathering eighty participatory tools —maps, matrices, transect walks, calendars, ranking exercises, problem trees— for community-based rural development across Latin America. Each tool is presented with materials, time required, step-by-step instructions and tips for handling group dynamics. A staple of extension workers' shelves.", descriptionAi: true },
    { title: "A Little Princess", author: "Frances Hodgson Burnett", category: "Literatura juvenil", coverId: 2328315, description: "Sara Crewe is the spoiled but bookish daughter of a wealthy British captain in colonial India when she is sent to a London boarding school. After her father's sudden death and bankruptcy, she is reduced to scullery maid in the same school where she once reigned. The novel insists, with quiet defiance, that nobility of character is independent of circumstance.", descriptionAi: true },
    { title: "Los ensayos (Tomo I)", author: "Michel de Montaigne", category: "Ensayo clásico", coverId: 13482735, status: "read", rating: 5, description: "Primer tomo de los Essais, escritos en el último tercio del XVI: el género del ensayo personal nace aquí como diálogo del autor consigo mismo. Recorre la educación, la amistad, la muerte, la curiosidad y los hábitos del cuerpo con una mezcla inconfundible de cita clásica, anécdota y autoanálisis. La frase «¿Qué sé yo?» se vuelve método y permite empezar a leer literatura moderna como exploración de la propia interioridad.", descriptionAi: true },
    { title: "Los ensayos (Tomo II)", author: "Michel de Montaigne", category: "Ensayo clásico", coverId: 13482735, status: "read", rating: 5, description: "Segundo tomo de los Essais, donde el autor extiende sus reflexiones a la prudencia, los hábitos, la conciencia y la apología de Raimundo Sabunde —el ensayo más largo y filosófico de la obra—. Discute la educación de los hijos, la guerra, la imaginación y la presunción humana con una mezcla de escepticismo y compasión que solo madura con la edad. Una lectura ideal para acompañar varias estaciones.", descriptionAi: true },
    { title: "Los ensayos (Tomo III)", author: "Michel de Montaigne", category: "Ensayo clásico", coverId: 13482735, status: "read", rating: 5, description: "Tercer tomo de los Essais. Ya maduro y enfermo, el ensayista escribe sobre la vejez, la experiencia, el cuerpo, la fragilidad y la diplomacia en una prosa más íntima y libre que en los volúmenes previos. La célebre frase final —«Toda moral se aplica a una vida común y sin esplendor»— condensa el espíritu de la obra y la convierte en el mejor manual antiguo sobre cómo envejecer con elegancia.", descriptionAi: true },
    { title: "One Piece, vols. 1-2-3 (East Blue)", author: "Eiichiro Oda", category: "Manga", coverId: 1020563, description: "Opening volumes of the epic pirate manga. Monkey D. Luffy —who gained rubber powers from a forbidden fruit— sets sail in the East Blue chasing his dream of becoming the King of the Pirates and finding the legendary treasure One Piece. Along the way he begins to gather a misfit crew that includes the swordsman Roronoa Zoro and the master thief Nami.", descriptionAi: true },
    { title: "One Piece, vols. 4-5-6 (East Blue)", author: "Eiichiro Oda", category: "Manga", coverId: 9485994, description: "The Straw Hats face Captain Kuro at Syrup Village and Don Krieg on the floating Baratie restaurant, where Sanji the chef joins the crew and the swordsman Dracule Mihawk puts Zoro brutally in his place. Foundational early arcs that establish the manga's mix of slapstick, tragedy and over-the-top action.", descriptionAi: true },
    { title: "One Piece, vols. 7-8-9 (East Blue)", author: "Eiichiro Oda", category: "Manga", coverId: 1020569, description: "Arlong Park arc. Luffy and his crew take on the fishman pirate who has enslaved Nami's home village under a cruel tribute scheme. One of the most beloved early arcs, where the manga first reveals the depth of its emotional reach and Nami's backstory pays off in a roar.", descriptionAi: true },
    { title: "One Piece, vols. 10-11-12 (East Blue)", author: "Eiichiro Oda", category: "Manga", coverId: 1020698, description: "Closing volumes of the East Blue saga. The crew clashes with the marine captain Smoker in Loguetown, the city where Gold Roger was executed, picks up a new ship and a new dreamer, then sails through Reverse Mountain into the Grand Line in pursuit of the One Piece.", descriptionAi: true },
    { title: "One Piece, vols. 13-14-15 (Baroque Works)", author: "Eiichiro Oda", category: "Manga", coverId: 3122735, description: "Opening of the Alabasta saga. The crew lands on Whiskey Peak, meets princess Vivi, encounters the assassin Mister 9 and uncovers a plot by the criminal organization Baroque Works to overthrow the desert kingdom of Alabasta. Their newest member, the warrior reindeer doctor Tony Tony Chopper, joins the journey.", descriptionAi: true },
    { title: "One Piece, vols. 16-17-18 (Baroque Works)", author: "Eiichiro Oda", category: "Manga", coverId: 1020703, description: "Middle of the Alabasta saga. The Straw Hats race through the desert toward Alubarna to stop the Warlord Crocodile from seizing power, dodging sandstorms, dance ribbon mountains and a parade of Baroque Works officers whose codenames go from Mister 1 to Miss Doublefinger.", descriptionAi: true },
    { title: "Veronika decide morir", author: "Paulo Coelho", category: "Novela", coverId: 4926517, description: "Una joven eslovena de veinticuatro años sobrevive a su intento de suicidio y despierta en Villete, un sanatorio mental en Liubliana donde le anuncian que su corazón está dañado y que solo le quedan unos días de vida. En ese plazo descubre, por primera vez, intensidades que la vida acomodada nunca le había dado. Una novela breve sobre la cordura, la locura y el deseo de existir.", descriptionAi: true },
    { title: "Mamita Yunai", author: "Carlos Luis Fallas", category: "Novela", coverId: 13864196, description: "Crónica novelada de las brutales condiciones de los peones bananeros del Caribe costarricense bajo la United Fruit Company a comienzos del siglo XX. La voz narradora —un trabajador veterano— recorre el bosque, los campamentos, las elecciones manipuladas y los crímenes invisibilizados con una prosa exacta y desolada. Un clásico de la literatura social latinoamericana.", descriptionAi: true },
    { title: "El principito", author: "Antoine de Saint-Exupéry", category: "Literatura", coverId: 13499066, description: "Un aviador caído en el desierto del Sahara conoce a un niño venido de un asteroide, B-612, que cuida una rosa y se pregunta por el sentido de los adultos. Bajo el ropaje de cuento, una meditación poética sobre la amistad, el amor, la pérdida y la mirada que los adultos olvidan en su empeño por ser «serios». Quizá el libro más traducido y leído del siglo XX, y siempre distinto en cada relectura.", descriptionAi: true },
    { title: "Don Quijote de la Mancha (I)", author: "Miguel de Cervantes", category: "Novela clásica", coverId: 14428305, status: "read", rating: 4, description: "Primera parte publicada en 1605. Un hidalgo manchego enloquecido por las novelas de caballería se hace caballero andante con el nombre de Don Quijote, sale al mundo en busca de aventuras y se hace acompañar por un labrador llamado Sancho Panza. Cada episodio —los molinos, la venta, los galeotes, Dulcinea— se cuenta con humor, ternura y una distancia irónica que inaugura la novela moderna.", descriptionAi: true },
    { title: "Don Quijote de la Mancha (II)", author: "Miguel de Cervantes", category: "Novela clásica", coverId: 14428305, status: "read", rating: 5, description: "Segunda parte publicada en 1615. Don Quijote y Sancho viven nuevas aventuras, esta vez conscientes de su fama literaria: los personajes que se cruzan ya han leído el primer tomo y juegan con ellos. La novela se vuelve más reflexiva y melancólica, dialoga con el plagiario Avellaneda y se acerca, en la cabalgata final, a una de las muertes más conmovedoras de la literatura.", descriptionAi: true },
    { title: "Los anarquistas", author: "Roderick Kedward", category: "Historia política", coverId: 6383480, description: "Síntesis histórica del anarquismo europeo del siglo XIX a través de sus principales pensadores —Bakunin, Kropotkin, Proudhon— y de las acciones que marcaron a la opinión pública: la Comuna de París, los atentados de fin de siglo, las internacionales obreras. Un balance equilibrado de las ideas y de su práctica, que rastrea por qué este movimiento siguió siendo influyente mucho después de su derrota política frente al marxismo organizado.", descriptionAi: true },
    { title: "Sandy: Leyendas a la tica", author: "Roger Bolaños", category: "Folclor", description: "Recopilación de leyendas y tradiciones populares costarricenses adaptadas con humor tico y un toque didáctico. El Cadejos, la Tulivieja, la Llorona, el carretón sin bueyes y otros personajes del imaginario popular aparecen ordenados por regiones y acompañados de breves contextos históricos. Pensado para el público infantil y juvenil.", descriptionAi: true },
    { title: "Serpientes, venenos y ofidismo en Centroamérica", author: "Varios autores", category: "Biología", description: "Tratado técnico de herpetología y toxinología que describe las especies venenosas de la región, sus hábitos, los mecanismos de inoculación, las composiciones bioquímicas de cada veneno y los protocolos médicos de atención. Pensado tanto para naturalistas como para personal sanitario rural, sirve también de catálogo identificador con láminas y claves taxonómicas.", descriptionAi: true },
    { title: "Quién es quién en la pintura de Goya", author: "Pedro Jesús Fernández", category: "Arte", coverId: 12717205, description: "Identifica a los personajes históricos retratados por Francisco de Goya y reconstruye el contexto político y social de la corte española de finales del XVIII y principios del XIX. Quién es la duquesa de Alba, quién Cabarrús, quién aparece de espaldas en los Caprichos: cada cuadro se vuelve una pequeña intriga cortesana cuando se sabe leer a sus protagonistas.", descriptionAi: true },
    { title: "Guía de Razonamiento Lógico Matemático", author: "AMP", category: "Matemáticas", description: "Manual de preparación para pruebas universitarias y de admisión: lógica proposicional, secuencias, razonamiento abstracto, probabilidad básica y problemas de planteamiento. Cada tema viene con teoría breve, ejercicios resueltos y baterías de práctica diseñadas para entrenar la velocidad y la precisión en el examen. Material clásico de la AMP para bachilleres costarricenses.", descriptionAi: true },
    { title: "Breve historia contemporánea de Costa Rica", author: "Héctor Pérez Brignoli", category: "Historia", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1677794976i/3684777.jpg", description: "Síntesis crítica de la formación del Estado costarricense, la consolidación de la democracia, el modelo agroexportador y los desafíos del siglo XX. Tres tomos del Fondo de Cultura Económica condensados en una lectura accesible que da cuenta de las transformaciones económicas, demográficas y culturales del país en relación con la región centroamericana.", descriptionAi: true },
    { title: "El monje que vendió su Ferrari", author: "Robin S. Sharma", category: "Autoayuda", coverId: 48817, description: "Fábula sobre un abogado millonario que sufre un infarto durante un juicio, vende todas sus posesiones y se retira a los Himalayas; regresa años después, ya convertido en sabio, con siete lecciones sobre disciplina, propósito y paz interior. Un libro de autoayuda contado como cuento iniciático que se ha leído por millones en todo el mundo.", descriptionAi: true },
    { title: "Cómo ganar amigos e influir sobre las personas", author: "Dale Carnegie", category: "Autoayuda", coverId: 13195013, description: "Clásico de 1936 que recopila principios para ganar simpatía, persuadir y liderar a partir de historias reales —Lincoln, Edison, Rockefeller— y de reglas prácticas de trato con la gente. La premisa es simple y radical: la mayoría de los conflictos no se resuelven con razones sino con escucha, reconocimiento y atención sincera al interés ajeno. Casi un siglo después sigue siendo lectura obligatoria de la cultura corporativa.", descriptionAi: true },
    { title: "Memorias de un primate", author: "Robert Sapolsky", category: "Memorias / Ciencia", coverId: 12329605, status: "read", rating: 5, description: "Recuerdo de los veranos de juventud estudiando una tropa de babuinos en el Serengeti: las jerarquías, las amistades inesperadas, los celos, los duelos y la política primate. El libro alterna ciencia y memoir, retrata a personajes con nombres propios y traza, en paralelo, el aprendizaje del joven investigador cuyo trabajo posterior sobre el estrés humano nació allí.", descriptionAi: true },
    { title: "El nombre de la rosa", author: "Umberto Eco", category: "Novela histórica", coverId: 8598263, status: "read", rating: 5, description: "Ambientada en una abadía benedictina del norte de Italia en 1327, una serie de muertes envuelve a la comunidad y el franciscano Guillermo de Baskerville llega para investigar con su novicio Adso de Melk. La novela mezcla intriga policial, semiótica, debate teológico y un laberinto bibliotecario para conjurar el espíritu de un medievo que se aleja del cliché. Uno de los best-sellers culturales del siglo XX que jamás traicionó la inteligencia del lector.", descriptionAi: true },
    { title: "Don't Sleep, There Are Snakes", author: "Daniel L. Everett", category: "Lingüística / Antropología", coverId: 9833943, status: "read", rating: 5, description: "Decades among the Pirahã of the Amazon, an isolated group whose language has no numbers, no color terms and no recursive sentences, push a missionary turned linguist to question Noam Chomsky's universal grammar and his own faith. A memoir of fieldwork, conversion and de-conversion that became one of the most discussed books in cognitive science in years.", descriptionAi: true },
    { title: "Las ventajas de ser un marginado", author: "Stephen Chbosky", category: "Novela juvenil", coverId: 13556024, status: "read", rating: 5, description: "Novela epistolar protagonizada por Charlie, un adolescente introvertido que escribe cartas a un destinatario anónimo durante su primer año de secundaria. Las cartas relatan amistades intensas con dos compañeros mayores, descubrimientos literarios y musicales, una historia familiar atravesada por el abuso y un duelo no resuelto. Lectura adolescente convertida en clásico moderno.", descriptionAi: true },
    { title: "Todo está jodido", author: "Mark Manson", category: "Ensayo", coverId: 8231990, status: "read", rating: 5, description: "Crítica del optimismo terapéutico y la cultura de la autoayuda contemporánea: la sociedad de la abundancia material ha producido una crisis de esperanza que solo puede repararse aceptando lo trágico de la condición humana. Mezcla a Nietzsche, Becker y el estoicismo con anécdotas personales para proponer una ética del límite y del esfuerzo digno frente a la promesa de felicidad ilimitada.", descriptionAi: true },
    { title: "Circe", author: "Madeline Miller", category: "Mitología / Novela", coverId: 8739376, status: "read", rating: 5, description: "Retelling of Greek myth from the perspective of the witch of Aeaea, the minor goddess banished to the island where Odysseus will eventually land. The novel follows her from a slighted nymph in her father's palace through Daedalus, the Minotaur, Medea and Penelope to a slow self-creation as the most powerful woman in the cosmos. Lyrical, feminist and gripping.", descriptionAi: true },
    { title: "The Ultimate Hitchhiker's Guide to the Galaxy", author: "Douglas Adams", category: "Ciencia ficción", coverId: 12986869, status: "read", rating: 5, description: "Single-volume omnibus of the five Hitchhiker novels. Arthur Dent's increasingly absurd intergalactic travels after Earth is demolished to make way for a hyperspace bypass: the answer is forty-two, the question is missing, the dolphins have left, and Marvin the Paranoid Android complains for billions of years. Comedy as cosmology.", descriptionAi: true },
    { title: "Gilgamesh", author: "Anónimo", category: "Épica clásica", coverId: 474300, description: "El poema épico babilónico más antiguo conocido, escrito en tablillas de arcilla hace más de cuatro mil años. El rey de Uruk, dos terceras partes divino y un tercio humano, emprende con su amigo Enkidu hazañas heroicas; tras la muerte de éste, parte solo en busca de la inmortalidad y se enfrenta, al borde del río de la muerte, a la dura verdad del límite humano. Texto raíz de la literatura universal.", descriptionAi: true },
    { title: "El conde de Montecristo", author: "Alejandro Dumas", category: "Novela clásica", coverId: 14566908, status: "read", rating: 5, description: "Edmond Dantès, joven marino a punto de casarse y de ascender a capitán, es traicionado por la envidia de sus rivales y encerrado durante catorce años en el castillo de If. Al escapar y heredar el tesoro de un sabio compañero de celda, regresa convertido en conde para ejecutar una venganza minuciosa y aristocrática contra quienes lo destruyeron. Folletín perfecto sobre el peso del tiempo, la justicia y la imposibilidad del olvido.", descriptionAi: true },
    { title: "The Broken Ladder", author: "Keith Payne", category: "Psicología social", coverId: 8814832, status: "read", rating: 5, description: "How economic inequality —not just poverty in the abstract— affects health, happiness, parenting, voting and even risk taking. Drawing on social psychology experiments and natural data, the book shows that humans constantly compare and that gaps as much as absolute levels shape behaviour. Persuasive, with policy implications across the political spectrum.", descriptionAi: true },
    { title: "Orgullo y prejuicio", author: "Jane Austen", category: "Novela clásica", coverId: 13498988, status: "to-read", description: "El amor inicialmente hostil entre la inteligente Elizabeth Bennet y el reservado señor Darcy en la Inglaterra rural del XIX. La novela disecciona, con ironía y un oído imbatible para el diálogo, el sistema matrimonial, la herencia, el cotilleo y los modales de una sociedad donde una mujer solo podía asegurar su futuro casándose bien. Una comedia de costumbres convertida en clásico universal.", descriptionAi: true },
    { title: "Las leyes del Serengeti", author: "Sean B. Carroll", category: "Biología", coverId: 8881359, description: "El ecosistema de la sabana africana es la mejor escuela para entender cómo se regulan las poblaciones de seres vivos: del fitoplancton al león, los mismos principios de regulación —no de abundancia— sostienen la vida. La narración pasa de los grandes mamíferos al colesterol y al cáncer para mostrar que las células de nuestro cuerpo obedecen las mismas leyes que las cebras y los ñus en migración.", descriptionAi: true },
    { title: "Frankenstein", author: "Mary Shelley", category: "Novela clásica", coverId: 12356249, status: "read", rating: 3, description: "Subtitled The Modern Prometheus and first published anonymously in 1818. A young Genevese scientist obsessed with the secret of life assembles a being from corpses and animates it, then recoils in horror from his creation. The «creature», intelligent and miserable, embarks on a haunting confrontation with its maker that ranges from the Alps to the Arctic. A foundational text of science fiction.", descriptionAi: true },
    { title: "Dictadores", author: "Frank Dikötter", category: "Historia política", coverId: 10869587, description: "Estudio comparativo de ocho dictadores del siglo XX —Mussolini, Hitler, Stalin, Mao, Kim Il-sung, Ceauşescu, Duvalier y Mengistu— a través del culto a la personalidad que cada uno construyó para sostenerse en el poder. El libro examina las técnicas comunes: producir miedo, fabricar adulación pública y desconfianza privada, y reescribir la historia a su medida.", descriptionAi: true },
    { title: "Charlatanes", author: "Moisés Naím y Quico Toro", category: "Política", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1738639001i/225819376.jpg", status: "reading", description: "Anatomía de los políticos contemporáneos que utilizan la mentira sistemática como herramienta para acumular y conservar poder en la era de las redes sociales. Desde Trump y Bolsonaro hasta Maduro y Petro, el libro identifica patrones comunes —la victimización, la conspiración, el ataque a la prensa— y propone defensas institucionales para evitar que la mentira se vuelva ley.", descriptionAi: true },
    { title: "La sociedad de la transparencia", author: "Byung-Chul Han", category: "Filosofía", coverId: 8083811, description: "Crítica filosófica del imperativo contemporáneo de la transparencia total: lo que parece un avance democrático opera como una nueva forma de control, en la que la intimidad, la distancia y el misterio quedan abolidos. Una sociedad sin secretos es también una sociedad sin Eros, sin lo otro y sin posibilidad de pensamiento propio. Breve ensayo que abrió la serie corta del filósofo coreano-alemán.", descriptionAi: true },
    { title: "Si mi biblioteca ardiera esta noche", author: "Aldous Huxley", category: "Ensayo", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1289005233i/9649980.jpg", status: "to-read", description: "Selección breve de textos en los que el ensayista británico reflexiona sobre los libros que han marcado su vida y sobre la práctica de la lectura como forma de pensamiento. La pregunta del título es a la vez una hipótesis y una declaración: ¿qué quedaría en la cabeza si todas las páginas se perdieran? Una pieza pequeña y cálida sobre el oficio de leer.", descriptionAi: true },
    { title: "Cartas a Lucilio", author: "Lucio Anneo Séneca", category: "Filosofía clásica", coverId: 8256111, description: "Ciento veinticuatro cartas dirigidas a un discípulo durante los últimos años de vida del filósofo, en las que se conversa con franqueza sobre la amistad, la muerte, la riqueza, el tiempo y la libertad interior. Cada epístola es a la vez ejercicio espiritual y consejo práctico; juntas componen el manual estoico más entrañable y leído de la Antigüedad.", descriptionAi: true },
    { title: "La guerra no tiene rostro de mujer", author: "Svetlana Alexiévich", category: "Crónica", coverId: 13135723, description: "Testimonios de cientos de mujeres soviéticas que combatieron en la Segunda Guerra Mundial como francotiradoras, enfermeras, cocineras, mecánicas o tanquistas, junto a relatos de la vida en el frente y del regreso silencioso a casa. La obra restituye una memoria invisibilizada por la versión oficial heroica y masculina, con una atención obsesiva al detalle físico y emocional. Una de las obras maestras del periodismo literario del siglo XX.", descriptionAi: true },
    { title: "El lecho de Procusto", author: "Nassim Nicholas Taleb", category: "Filosofía", coverId: 14156240, status: "read", rating: 5, description: "Aforismos breves que destilan en pocas palabras las ideas centrales de un proyecto filosófico más amplio: la asimetría del conocimiento, la fragilidad de los expertos, la sabiduría de las prácticas tradicionales y los peligros de la abstracción contemporánea. Cada entrada es una provocación pulida y cada sección invita a meditarse despacio, como manual de bolsillo para mirar el mundo con escepticismo activo.", descriptionAi: true },
    { title: "Cuentos imprescindibles del siglo XX de América Latina", author: "Varios autores", category: "Antología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1753467428i/238970160.jpg", description: "Antología que reúne piezas canónicas del relato breve latinoamericano del XX: cuentos rurales, fantásticos, urbanos, políticos, eróticos y absurdos. Permite leer de un tirón a Borges, Cortázar, Rulfo, Onetti, García Márquez, Bombal o Lispector, y notar las afinidades subterráneas que conectan tradiciones nacionales muy distintas en una conversación literaria continental.", descriptionAi: true },
    { title: "How to Diagnose and Fix Everything Electronic", author: "Michael Jay Geier", category: "Electrónica", coverId: 9594813, description: "Hands-on guide that teaches hobbyists and technicians to troubleshoot and repair almost any consumer electronic device. Covers the right tools, basic measurements with a multimeter and oscilloscope, how to read schematics, and a methodical fault-tracing process that works whether the broken item is a power supply, a guitar amp or a vintage VCR.", descriptionAi: true },
    { title: "El arte de no ser gobernados", author: "James C. Scott", category: "Antropología política", coverId: 6289268, status: "read", rating: 4, description: "Historia de Zomia, la inmensa región montañosa del sureste asiático que durante siglos sirvió de refugio a pueblos que escogieron la marginalidad estatal frente al sometimiento. La tesis es contraintuitiva: la agricultura migratoria, los sistemas de escritura efímeros y las jerarquías difusas no son rezagos de la barbarie sino estrategias deliberadas para evitar el control de los reinos del valle. Repensar la historia desde quienes huyen.", descriptionAi: true },
    { title: "Meditaciones", author: "Marco Aurelio", category: "Filosofía clásica", coverId: 10469464, status: "read", rating: 5, description: "Cuaderno privado del emperador romano: doce libros de ejercicios espirituales escritos en griego durante las campañas militares en la frontera del Danubio. No fue concebido para publicarse, lo que explica su tono íntimo y reiterativo: aplicar los principios estoicos al juicio, la ira, la muerte y el deber del cargo. Un texto que sigue siendo manual de conducta para lectores muy distintos.", descriptionAi: true },
    { title: "Dominio", author: "Tom Holland", category: "Historia", coverId: 13458584, status: "read", rating: 4, description: "Tesis ambiciosa: los valores morales occidentales contemporáneos —incluidos los más laicos como la igualdad, los derechos humanos o la separación entre Iglesia y Estado— están profundamente moldeados por dos mil años de cristianismo. La historia recorre los Padres de la Iglesia, las cruzadas, la Reforma, la Ilustración y el feminismo para mostrar cómo la herencia cristiana atraviesa incluso a quienes se creen ajenos a ella.", descriptionAi: true },
    { title: "Miradas sobre la desigualdad", author: "Branko Milanović", category: "Economía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1715966942i/206801504.jpg", description: "Tres siglos de teoría económica sobre la desigualdad, desde Quesnay y Smith hasta Marx, Pareto, Kuznets y Piketty. Cada autor recibe un capítulo que cruza biografía, método y datos, y muestra cómo la pregunta por «quién recibe qué y por qué» ha sido siempre central a la economía y la política. Un libro a la altura de su autor, gran especialista en desigualdad global.", descriptionAi: true },
    { title: "Historia de Costa Rica", author: "Iván Molina y Steven Palmer", category: "Historia", coverId: 12286807, description: "Síntesis crítica de la historia del país desde la conquista hasta el siglo XXI, atenta tanto a los grandes procesos económicos y demográficos —caficultura, banano, café, urbanización— como a las transformaciones culturales, religiosas y políticas. Una historiografía rigurosa y legible, escrita para no especialistas.", descriptionAi: true },
    { title: "Hacia las estrellas", author: "Mary Robinette Kowal", category: "Ciencia ficción", coverId: 8290909, status: "to-read", description: "Primera novela de la serie Lady Astronaut. En 1952, un meteorito devasta el planeta y la humanidad acelera la carrera espacial para asegurar la supervivencia en otros mundos. Elma York, matemática y aviadora durante la Segunda Guerra Mundial, lucha por ser la primera astronauta en una NASA dispuesta a usar sus cálculos pero no a verla volar. Ciencia ficción dura con conciencia de género y clase.", descriptionAi: true },
    { title: "Matadero Cinco", author: "Kurt Vonnegut", category: "Novela", coverId: 12727001, status: "read", rating: 5, description: "Billy Pilgrim, soldado estadounidense superviviente del bombardeo de Dresde, queda «desencajado del tiempo» y rememora episodios de su vida en cualquier orden: la guerra, su matrimonio, la abducción extraterrestre, su muerte. La novela —fragmentada, irónica, antibelicista— se ha convertido en uno de los textos centrales del posmodernismo estadounidense.", descriptionAi: true },
    { title: "Las mil y una noches (Tomo I)", author: "Anónimo", category: "Literatura clásica", coverId: 12339547, description: "Primer volumen del ciclo árabe en el que la astuta Sherezade aplaza su ejecución contándole al rey Shahriar un cuento cada noche. Reúne historias de Aladino, los siete viajes de Simbad y otras leyendas del mundo islámico medieval, con su mezcla característica de magia, viajes mercantiles y deseo. Una obra abierta que ha crecido durante mil años con cada nuevo traductor.", descriptionAi: true },
    { title: "Las mil y una noches (Tomo II)", author: "Anónimo", category: "Literatura clásica", coverId: 12339547, description: "Segundo volumen del ciclo. Continúan las historias que Sherezade narra al sultán para conservar la vida: viajes a tierras remotas, amores desmesurados, demonios encerrados en lámparas, sultanes destronados y ciudades fantasmas en el desierto. Una geografía imaginaria que va de Bagdad a Cantón y que sigue alimentando la fantasía universal.", descriptionAi: true },
    { title: "The 48 Laws of Power", author: "Robert Greene", category: "Estrategia", coverId: 6424160, status: "to-read", description: "Compendium of laws distilled from three thousand years of history, ranging from Sun Tzu to Talleyrand to Hollywood power players. Each law is stated as an aphorism («Never outshine the master», «Win through your actions, never through argument») and illustrated with parallel historical anecdotes, observances and transgressions. A cynical, instructive book that is simultaneously a manual and a warning.", descriptionAi: true },
    { title: "The Subtle Art of Not Giving a F*ck", author: "Mark Manson", category: "Autoayuda", coverId: 8231990, status: "read", rating: 5, description: "Pop-philosophy bestseller arguing that the secret to a good life is choosing carefully what to care about. Mixes blunt language, autobiographical anecdotes and threads of Stoicism and Buddhist thought to push back against the cult of relentless positivity. A short, punchy book that became a global counter-cultural phenomenon.", descriptionAi: true },
    { title: "The Daily Stoic", author: "Ryan Holiday y Stephen Hanselman", category: "Filosofía / Estoicismo", coverId: 10302294, description: "366 daily meditations on Stoic philosophy: one passage per day from Marcus Aurelius, Seneca, Epictetus or others, paired with a contemporary commentary and a daily theme. Built as a structured year-long practice for readers who want to internalize Stoic principles rather than just read about them. A bedside-table classic of the modern Stoic revival.", descriptionAi: true },
    { title: "Seres sintientes", author: "Jackie Higgins", category: "Biología", coverId: 12657268, description: "Trece sentidos animales —el olfato del salmón que vuelve al río, el campo magnético del petirrojo, el oído del búho, la visión ultravioleta de la mantis camaronera— iluminan capacidades sensoriales humanas que no sabíamos tener. Un viaje a la fenomenología comparada de la percepción que cambia la idea de lo que significa estar vivo.", descriptionAi: true },
    { title: "Final de partida", author: "Peter Turchin", category: "Historia / Sociología", coverId: 13790624, description: "Aplicación de la cliodinámica al ciclo histórico de auge y crisis de las élites para argumentar, con modelos cuantitativos, que Estados Unidos se acerca a un período de inestabilidad estructural similar al de las décadas previas a las guerras civiles del XIX. Un análisis frío y polémico de la política contemporánea desde la historia comparada.", descriptionAi: true },
    { title: "Anarquía relacional", author: "JC Pérez Cortés", category: "Sociología", coverId: 10371434, status: "to-read", description: "Introducción a la propuesta de relaciones afectivas sin jerarquías ni etiquetas predefinidas, en la que cada vínculo se construye según los acuerdos de los participantes y no según un guion social. Discute la pareja, la familia, la amistad y los celos a la luz de la teoría queer y del activismo no monógamo. Un manual para pensar cómo nos relacionamos cuando los moldes heredados ya no nos sirven.", descriptionAi: true },
    { title: "Modos de existir", author: "James Bridle", category: "Filosofía / Tecnología", coverId: 14435859, status: "to-read", description: "Defensa de una ecología expandida de inteligencias —animales, vegetales, microbianas, computacionales y geológicas— que dilata la noción occidental de qué significa pensar y existir. El libro alterna ensayo, manifiesto y poema en prosa para reorganizar la jerarquía habitual del «yo» y de «el otro».", descriptionAi: true },
    { title: "Ilustración pirata", author: "David Graeber", category: "Antropología", coverId: 14407897, status: "read", rating: 4, description: "Las repúblicas piratas del siglo XVIII en Madagascar, lejos de ser bandas de criminales aislados, organizaron formas radicales de igualdad, asambleas en cubierta y reparto del botín que prefiguraron las ideas democráticas que después circularían por Europa. Esta investigación antropológica e histórica recompone esos experimentos políticos como un capítulo perdido de la Ilustración global.", descriptionAi: true },
    { title: "El camino a la realidad", author: "Roger Penrose", category: "Física / Matemáticas", coverId: 8427776, status: "to-read", description: "Guía exhaustiva a las matemáticas y la física teóricas que sustentan nuestra comprensión actual del universo: de los números reales y complejos a la teoría de la relatividad y la gravedad cuántica, sin saltarse las herramientas. Un tratado ambicioso, mil quinientas páginas para construir, paso a paso, una imagen coherente del mundo a la altura del estado del arte.", descriptionAi: true },
    { title: "La desaparición de los rituales", author: "Byung-Chul Han", category: "Filosofía", coverId: 13291480, description: "Diagnostica la liquidación contemporánea de los rituales y de las formas comunitarias que estructuraban la experiencia humana, sustituidos por la producción individualizada y el consumo continuo. Sin rituales no hay tiempo común, no hay duelo y no hay verdadera fiesta; queda una vida llena de eventos. Otro de los breves ensayos críticos sobre la subjetividad neoliberal del filósofo coreano-alemán.", descriptionAi: true },
    { title: "Nudge", author: "Richard H. Thaler y Cass R. Sunstein", category: "Economía conductual", coverId: 6402116, status: "read", rating: 4, description: "Argues that the way choices are framed —the «choice architecture»— powerfully shapes decisions in retirement plans, organ donation, school cafeterias and credit cards. Behavioral economics is used to design «nudges» that preserve freedom of choice while pushing people toward better outcomes. A defining text of «libertarian paternalism» as a policy approach.", descriptionAi: true },
    { title: "La revancha de los poderosos", author: "Moisés Naím", category: "Política", coverId: 14250134, status: "read", rating: 5, description: "Anatomía del ascenso global de los líderes autoritarios contemporáneos —de Putin a Trump, de Orbán a Bukele— mediante la tríada populismo, polarización y posverdad. Mostrar cómo esa combinación ataca simultáneamente a partidos, prensa, judicatura y memoria, y enumera las defensas democráticas posibles. Lectura imprescindible para entender la política de los últimos veinte años.", descriptionAi: true },
    { title: "Historia de la economía", author: "John Kenneth Galbraith", category: "Economía", coverId: 10633764, description: "Historia accesible y elegante del pensamiento económico desde Aristóteles hasta el monetarismo, atenta a las circunstancias políticas que hicieron posible cada teoría. Conecta la filosofía moral, las grandes crisis y la historia del comercio para mostrar que la economía nunca ha sido una ciencia neutral sino el resultado de batallas intelectuales por explicar la riqueza y el poder.", descriptionAi: true },
    { title: "La disciplina marcará tu destino", author: "Ryan Holiday", category: "Filosofía / Estoicismo", coverId: 13153179, description: "Segunda entrega de la tetralogía sobre las virtudes cardinales estoicas, dedicada a la disciplina como hábito que distingue a quienes logran sus metas de quienes ceden a la inercia. Mezcla biografías históricas —Eisenhower, Lou Gehrig, Marina Abramović— con principios estoicos y rutinas concretas para entrenar el autocontrol y el orden interior en una época de distracción permanente.", descriptionAi: true },
    { title: "Mirar", author: "John Berger", category: "Arte / Ensayo", coverId: 13252940, description: "Ensayos sobre el acto de mirar: los animales en los zoológicos, las fotografías de guerra, la pintura clásica, las puertas y las naturalezas muertas. Cada texto es un ejercicio breve de atención política y estética; juntos forman uno de los grandes libros de teoría visual del siglo XX.", descriptionAi: true },
    { title: "Cuentos de amor, de locura y de muerte", author: "Horacio Quiroga", category: "Cuento", coverId: 99816, status: "read", rating: 4, description: "Dieciocho relatos publicados en 1917 en los que la selva misionera, la enfermedad mental y la fragilidad del cuerpo se entretejen en un realismo sombrío y de filo. Cuentos como «El almohadón de plumas» o «La gallina degollada» se han vuelto piezas canónicas del relato breve hispanoamericano, con una crueldad seca que cuesta olvidar.", descriptionAi: true },
    { title: "Popol Vuh", author: "Anónimo", category: "Mitología", coverId: 584099, description: "Libro sagrado de los mayas k'iche': la creación del mundo, los intentos fallidos de los dioses por modelar a la humanidad, las luchas de los héroes gemelos Hunahpú e Ixbalanqué contra los señores de Xibalbá y las migraciones de los pueblos del altiplano de Guatemala. Texto cosmogónico fundamental de la literatura mesoamericana.", descriptionAi: true },
    { title: "How AI Will Change Your Life", author: "Patrick Dixon", category: "Tecnología", coverUrl: "https://profilebooks.com/wp-content/uploads/2024/07/9781805222576.jpg", description: "Concise survey of the near-term impact of artificial intelligence on work, health, education, war and creativity. Mixes technical context with concrete forecasts of how customer service, drug discovery, music composition or military decision-making will be reshaped within a decade. Written by a futurist with thirty years of corporate consulting under his belt.", descriptionAi: true },
    { title: "1984", author: "George Orwell", category: "Novela distópica", coverId: 14351142, status: "read", rating: 4, description: "Winston Smith works at the Ministry of Truth in Oceania, where his job is to rewrite history so that the Party's version is always accurate. He keeps a forbidden diary, falls into an even more forbidden affair with Julia, and is eventually broken in Room 101. The novel introduced Big Brother, doublethink, Newspeak and the boot stamping on a human face into the world's political vocabulary.", descriptionAi: true },
    { title: "En busca del tiempo perdido (Tomo 1)", author: "Marcel Proust", category: "Novela clásica", coverId: 10153245, status: "to-read", description: "Por el camino de Swann: el narrador rememora desde la adultez sus veranos infantiles en Combray —la magdalena mojada en té y la duermevela maternal— y reconstruye la pasión de Charles Swann por la cortesana Odette. La primera novela abre el ciclo y fija sus obsesiones: la memoria involuntaria, los celos, la mundanidad y la búsqueda del tiempo que aparentemente se ha perdido.", descriptionAi: true },
    { title: "En busca del tiempo perdido (Tomo 2)", author: "Marcel Proust", category: "Novela clásica", coverId: 10153245, status: "to-read", description: "A la sombra de las muchachas en flor: el narrador, ya adolescente, descubre el amor en Balbec ante un grupo de jovencitas en flor —entre ellas Albertine— mientras entra en los salones literarios de París. La novela describe la transformación de la sensibilidad estética y amorosa con una prosa larguísima, demorada y siempre dispuesta al hallazgo.", descriptionAi: true },
    { title: "En busca del tiempo perdido (Tomo 3)", author: "Marcel Proust", category: "Novela clásica", coverId: 10153245, status: "to-read", description: "El mundo de Guermantes: el narrador es admitido en la alta sociedad del faubourg Saint-Germain, frecuenta el círculo de la duquesa de Guermantes y observa, con ojo despiadado, los rituales del mundo aristocrático. El caso Dreyfus sacude París mientras la novela disecciona la mundanidad como un arte casi militar.", descriptionAi: true },
    { title: "La crisis de la narración", author: "Byung-Chul Han", category: "Filosofía", coverId: 14576033, description: "Diagnóstico del ruido informativo del presente como una crisis de las narraciones que dan sentido a la vida. Lo que llamamos información no es contar: son fragmentos sin tiempo, sin demora y sin escucha. Propone recuperar el contar como acto comunitario, lento y poético, capaz de devolverle al lenguaje su capacidad de estructurar la experiencia.", descriptionAi: true },
    { title: "Zen en el arte del tiro con arco", author: "Eugen Herrigel", category: "Filosofía oriental", coverId: 3346542, status: "to-read", description: "Crónica de seis años de aprendizaje del kyudo en Japón como vía de iniciación al zen. La práctica disuelve la voluntad del tirador hasta que la flecha se dispara sola; el ego deja de interponerse entre el arquero y el blanco. Un libro breve, profundamente ético, que abrió a muchas lectoras occidentales el camino del zen contemporáneo.", descriptionAi: true },
    { title: "Hijos de la Bruma I: El Imperio Final", author: "Brandon Sanderson", category: "Fantasía", coverId: 14658160, status: "read", rating: 5, description: "Apertura de la trilogía Mistborn. En un mundo cubierto de ceniza y vigilado por la Inquisición, una banda de ladrones encabezada por Kelsier planea derrocar al Señor Tenebroso, un dios-emperador inmortal que ha gobernado durante mil años. La joven huérfana Vin descubre, en mitad del plan, que es una nacida de la bruma con poderes alománticos. Fantasía épica con sistema mágico claro y trama de heist.", descriptionAi: true },
    { title: "Hijos de la Bruma II: El Pozo de la Ascensión", author: "Brandon Sanderson", category: "Fantasía", coverId: 14658341, status: "read", rating: 5, description: "Segundo volumen de la trilogía Mistborn. Tras la caída del Señor Tenebroso, Vin y Elend deben sostener el frágil reino que crearon mientras una niebla mortal se extiende, ejércitos rivales sitian la capital y profecías antiguas reclaman a un Héroe de las Eras. La trama gana en política, intriga y revelaciones sobre la verdadera naturaleza del mundo.", descriptionAi: true },
    { title: "Hijos de la Bruma III: El Héroe de las Eras", author: "Brandon Sanderson", category: "Fantasía", coverId: 14658094, status: "read", rating: 5, description: "Cierre de la trilogía Mistborn. El Pozo de la Ascensión ha liberado a un poder antiguo que amenaza con destruir el mundo: la ceniza cubre el cielo, las plantas mueren y solo Vin descubre, página a página, el verdadero significado del Héroe de las Eras. Un final con todas las piezas del puzzle encajando con la habilidad meticulosa de la fantasía épica contemporánea.", descriptionAi: true },
    { title: "Mito y significado", author: "Claude Lévi-Strauss", category: "Antropología", coverId: 8695485, status: "to-read", description: "Cinco conferencias radiofónicas en las que el antropólogo francés explica con claridad sus tesis sobre el mito como pensamiento estructurado, la oposición entre ciencia y mito y el papel del estructuralismo. Una excelente puerta de entrada a una obra que en otros formatos puede resultar más exigente.", descriptionAi: true },
    { title: "Thinking In Systems: A Primer", author: "Donella H. Meadows", category: "Negocios", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1390169859l/3828902.jpg", status: "read", rating: 5, description: "Posthumous introduction to systems thinking by one of the field's pioneers. Stocks, flows, feedback loops, delays, and the famous «system traps» (drift to low performance, escalation, success to the successful) are explained with the patience of a teacher who actually wants you to use the tools. Indispensable for anyone trying to change a complex organization or a complex policy.", descriptionAi: true, owned: false },
    { title: "Astrophysics for People in a Hurry", author: "Neil deGrasse Tyson", category: "", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1562761669l/32191710.jpg", status: "read", rating: 4, description: "Modern cosmology distilled into a short, brisk tour: the Big Bang, dark matter, dark energy, the cosmic microwave background, exoplanets and the chemistry of the stars. Written for readers with no science background, with a tone that is at once humble before the universe and patient with the reader.", descriptionAi: true, owned: false },
    { title: "One Day, Everyone Will Have Always Been Against This", author: "Omar El Akkad", category: "", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1764097849l/213870084.jpg", status: "read", rating: 5, description: "Sharp essay on the Western response to the war in Gaza and on how official narratives are rewritten once atrocities can no longer be denied. Mixing personal memoir, history of the literary novel and political analysis, it offers a meditation on complicity, on language, and on what it costs to speak clearly while events are still unfolding.", descriptionAi: true, owned: false },
    { title: "Switch: How to Change Things When Change Is Hard", author: "Chip Heath", category: "", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1422839688l/6570502.jpg", status: "read", rating: 4, description: "Practical framework for personal and organizational change built on a single metaphor: the rational rider on top of an emotional elephant on a path. To make change stick you have to direct the rider, motivate the elephant and shape the path. Each principle is illustrated with case studies from medicine, marketing and social policy.", descriptionAi: true, owned: false },
    { title: "La conquista de la felicidad", author: "Bertrand Russell", category: "", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1327274673l/2604877.jpg", status: "read", rating: 5, description: "Ensayo claro y empírico de 1930 que diagnostica las causas modernas de la infelicidad —celos, fatiga, miedo a la opinión pública, persecución del éxito— y propone, en contrapartida, condiciones racionales para vivir bien. Mezcla observación social, sentido común y una prosa luminosa que envejece sorprendentemente bien.", descriptionAi: true, owned: false },
    { title: "Ownership: Reinventing Companies, Capitalism, and Who Owns What", author: "Corey Rosen", category: "", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1642987531l/59891628.jpg", status: "read", rating: 4, description: "Argues that broad-based employee share schemes are a proven and underused way to make capitalism work for workers, strengthen firms and reduce inequality at the same time. Surveys decades of research, profiles successful ESOPs and proposes specific policy and tax changes to scale them up. A constructive manifesto from inside the corporate-finance world.", descriptionAi: true, owned: false },
    { title: "The Price is Wrong: Why Capitalism Won't Save the Planet", author: "Brett Christophers", category: "", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1686005184l/165937650.jpg", status: "read", rating: 4, description: "Cheap renewables, even when they outcompete fossil fuels on a per-megawatt basis, are not being deployed at the scale and speed required by the climate crisis because private investors demand returns that the technology cannot provide. The argument is that public investment, public ownership and public planning are unavoidable if decarbonization is to happen on time.", descriptionAi: true, owned: false },
    { title: "How the World Made the West: A 4,000 Year History", author: "Josephine Quinn", category: "Historia", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1717437075l/203956660.jpg", status: "read", rating: 4, description: "Dismantles the standard story of a singular Western civilization that runs from Athens through Rome to today's Atlantic powers. Four millennia of cultural exchange across the Mediterranean and beyond are reconstructed to show that what we call «the West» is a recent rebranding of a long history of borrowing, mixing and forgetting.", descriptionAi: true, owned: false },
    { title: "Dune Messiah", author: "Frank Herbert", category: "", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1577043824l/44492285.jpg", status: "read", rating: 4, description: "Sequel to Dune. Twelve years after the jihad, Paul Atreides is Emperor of the universe and his Fremen disciples have killed billions in his name. Trapped in his own prescient vision and surrounded by a conspiracy that includes the Bene Gesserit, the Tleilaxu and the Spacing Guild, he must decide what to sacrifice to escape the religion he became. Shorter and darker than the original.", descriptionAi: true, owned: false },
    { title: "The Fabric of Civilization: How Textiles Made the World", author: "Virginia Postrel", category: "Historia", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1601345373l/52686790.jpg", status: "read", rating: 5, description: "Argues that fiber, thread, dye and cloth are not background details of history but engines of it. Each chapter follows a different aspect of textiles —the domestication of silkworms, the chemistry of indigo, the math behind weaving, the politics of fashion— and shows how textiles drove global trade, technological innovation and inequality.", descriptionAi: true, owned: false },
    { title: "The Poppy War", author: "R.F. Kuang", category: "Fantasía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1515691735l/35068705.jpg", status: "read", rating: 3, description: "Debut grimdark fantasy. War-orphan Rin tests into an elite military academy in a country modeled on early-twentieth-century China, only to discover shamanic powers as a brutal imperial war erupts. Inspired by the second Sino-Japanese war and especially by the Rape of Nanjing, the novel makes no concessions about what war does to those who survive it.", descriptionAi: true, owned: false },
    { title: "Siddhartha", author: "Hermann Hesse", category: "Mitología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1629378189l/52036.jpg", status: "read", rating: 5, description: "A young Brahmin in ancient India leaves his comfortable life to seek enlightenment. He passes through ascetic discipline, lust, wealth, fatherhood and despair before discovering wisdom by the side of a river. A short, lyrical novel that synthesizes European Bildungsroman with Buddhist and Hindu thought and became a touchstone for the twentieth-century search for inner life.", descriptionAi: true, owned: false },
    { title: "El Cerebro Dividido: Maneras de prestar atención y construir el mundo Edition)", author: "Iain McGilchrist", category: "Psicología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1721732753l/216672197.jpg", status: "read", rating: 5, description: "Los dos hemisferios cerebrales atienden el mundo de maneras complementarias: uno totalmente disponible para lo nuevo, lo lateral y lo encarnado; el otro especializado en lo conocido, lo abstracto y lo controlado. La dominancia progresiva del hemisferio izquierdo configura buena parte de la cultura occidental moderna, su exactitud y su empobrecimiento sensorial. Un tratado interdisciplinario que cruza neurociencia, filosofía e historia del arte.", descriptionAi: true, owned: false },
    { title: "A Beautifully Foolish Endeavor", author: "Hank Green", category: "Ciencia ficción", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1576697804l/49003616.jpg", status: "read", rating: 5, description: "Sequel to An Absolutely Remarkable Thing. With April May presumed dead, her friends and the alien Carls' game return; the world has changed and the dream sequences become a battleground. The novel ramps up the satire of online fame, identity politics and the temptations of being a Voice for a generation.", descriptionAi: true, owned: false },
    { title: "An Absolutely Remarkable Thing", author: "Hank Green", category: "Ciencia ficción", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1520026196l/24233708.jpg", status: "read", rating: 5, description: "Twenty-three-year-old April May stumbles upon a giant alien statue in midtown Manhattan, posts a video and wakes up famous. Soon identical Carls appear in cities around the world and humanity has to decide what to do with them while April rides the cyclone of online attention. A novel about influence, friendship and what it costs to become a brand.", descriptionAi: true, owned: false },
    { title: "Dune", author: "Frank Herbert", category: "", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1555447414l/44767458.jpg", status: "read", rating: 4, description: "Set on the desert planet Arrakis, the story of the boy Paul Atreides, heir to a noble family tasked with ruling an inhospitable world where the only thing of value is the «spice» melange. Betrayal, prescience, ecology and religion fuse into a sweeping science-fiction epic that invented modern world-building.", descriptionAi: true, owned: false },
    { title: "Super Agers: An Evidence-Based Approach to Longevity", author: "Eric Topol", category: "Divulgación científica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1730640080l/220160337.jpg", status: "read", rating: 4, description: "Synthesizes the data on what actually extends healthy lifespan: diet, exercise, sleep, social ties, immune resilience and the new tools of AI-assisted medicine for personalizing prevention. Written by a cardiologist who has spent a career questioning unproven medical fads, it refuses both panic and snake oil.", descriptionAi: true, owned: false },
    { title: "Central America's Forgotten History: Revolution, Violence, and the Roots of Migration", author: "Aviva Chomsky", category: "", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1601938710l/54815903.jpg", status: "read", description: "Traces five hundred years of U.S. intervention in Central America —from filibusters to banana republics to Cold War-era counterinsurgency— to explain the contemporary crises that drive Salvadoran, Guatemalan and Honduran migration north. A counter-history that puts displacement at the center of any honest immigration debate.", descriptionAi: true, owned: false },
    { title: "Other People's Money: The Real Business of Finance", author: "John Kay", category: "", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1712505194l/24612279.jpg", status: "read", rating: 4, description: "Modern finance, the argument goes, has stopped serving the real economy and instead devotes itself to trading other people's money among traders. Surveys what financial intermediaries are supposed to do —payments, capital allocation, insurance, savings management— and shows how the industry has drifted away from each of these functions while extracting enormous rents.", descriptionAi: true, owned: false },
    { title: "Finance and the Good Society", author: "Robert J. Shiller", category: "Economía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1348262894l/13384575.jpg", status: "read", rating: 4, description: "Defends finance as a powerful social technology and proposes ways it can be redesigned to address inequality and human well-being rather than merely amplify private wealth. Topics include insurance, mortgages, philanthropy, social impact bonds and the political legitimacy of financial innovation. A constructive answer to the post-2008 mood.", descriptionAi: true, owned: false },
    { title: "We Are What We Pretend To Be: The First and Last Works", author: "Kurt Vonnegut Jr.", category: "Cuentos", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1340327859l/15716409.jpg", status: "read", rating: 4, description: "A posthumous volume pairing an unpublished first novel, Basic Training, with the unfinished If God Were Alive Today, bookending a career obsessed with kindness, war, absurdity and the limits of decency. The result is less a tidy collection than an honest framing of a writer at his beginning and his end.", descriptionAi: true, owned: false },
    { title: "Obliquity: Why Our Goals Are Best Achieved Indirectly", author: "John Kay", category: "", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1347801679l/7888001.jpg", status: "read", rating: 4, description: "Through case studies from business strategy, economics, war and personal happiness, the book argues that complex goals are most reliably reached by indirect routes; direct optimization usually defeats itself. The lesson for managers, policy makers and individuals is to plan for adaptation rather than for control.", descriptionAi: true, owned: false },
    { title: "Los ensayos (según la edición de 1595 de Marie de Gournay)", author: "Michel de Montaigne", category: "", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1411400457l/3232646.jpg", status: "read", rating: 5, description: "Reedición integral de los Essais basada en la última versión póstuma que preparó la «hija de alianza» del ensayista. Es la edición canónica del corpus, con los añadidos y reformulaciones que dejan ver la última cabeza del autor. Lectura obligada para quien quiera entender el texto en su forma definitiva.", descriptionAi: true, owned: false },
    { title: "Farenheit 451", author: "Ray Bradbury", category: "Novela clásica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1608059811l/56302573.jpg", status: "read", rating: 4, description: "En una sociedad futura donde los libros están prohibidos, el bombero Guy Montag tiene como oficio quemarlos hasta que, una mañana, se queda con uno. La distopía pasa del entretenimiento televisivo y la prisa permanente al silencio de los libros escondidos en el bosque. Un clásico breve sobre la lectura, la censura y la memoria.", descriptionAi: true, owned: false },
    { title: "The Wise Man's Fear", author: "Patrick Rothfuss", category: "Fantasía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1452624392l/1215032.jpg", status: "read", rating: 5, description: "Second volume of the Kingkiller Chronicle. Kvothe continues his story for the Chronicler: more adventures at the University in Imre, an embassy to the court of the Maer Alveron, a hunt for bandits in the forest of Eld, an erotic education with Felurian among the Fae and a martial education with the Adem. A long, immersive middle book.", descriptionAi: true, owned: false },
    { title: "Culture: The surprising connections and influences between civilisations.", author: "Martin Puchner", category: "Historia", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1675867915l/106209313.jpg", status: "read", rating: 5, description: "Human culture is fundamental remix. Through fifteen historical episodes —from Nefertiti's bust to Hokusai's prints, the Book of the Dead to the printing of the Don Quixote— the book shows how supposedly pure civilizations have always been hybrids and how their reach depends on transmission, translation and theft.", descriptionAi: true, owned: false },
    { title: "Race, Monogamy, and Other Lies They Told You: Busting Myths about Human Nature", author: "Agustín Fuentes", category: "Antropología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1342036184l/12933643.jpg", status: "read", rating: 3, description: "Uses biology, archaeology and the social sciences to dismantle three popular myths: that race is biological, that monogamy is natural and that aggression is encoded in human genes. Each chapter walks through the evidence and shows how cultural narratives masquerade as nature when convenient.", descriptionAi: true, owned: false },
    { title: "Birds, Sex and Beauty: The Extraordinary Implications of Charles Darwin's Strangest Idea", author: "Matt Ridley", category: "", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1739375971l/216269105.jpg", status: "read", rating: 4, description: "Rehabilitates the most controversial idea in The Descent of Man —that female birds choose mates for sheer beauty— and traces its consequences for evolutionary theory and the origins of art. Mixes bird-watching, philosophy and history of science with characteristic relish.", descriptionAi: true, owned: false },
    { title: "The Logic of Scientific Discovery", author: "Karl Popper", category: "Filosofía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1405192590l/61550.jpg", status: "read", rating: 4, description: "Foundational work of twentieth-century philosophy of science. Replaces verification with falsification as the demarcation criterion for science: a theory is scientific to the extent that it forbids events, and corroborated only as long as no observation has refuted it. Dense but enormously influential, especially for working scientists who feel that statistical induction never quite tells the whole story.", descriptionAi: true, owned: false },
    { title: "Your Life Is Manufactured: How We Make Things, Why It Matters and How We Can Do It Better", author: "Tim Minshall", category: "Divulgación científica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1730911521l/221193153.jpg", status: "read", rating: 4, description: "A walk through the global manufacturing systems behind everyday objects: the smartphone, the cup of coffee, the bicycle, the t-shirt. Each chapter explains the supply chains, the engineering disciplines and the geopolitics involved, then argues that understanding how things are made is essential to building a sustainable future.", descriptionAi: true, owned: false },
    { title: "Life, the Universe and Everything", author: "Douglas Adams", category: "Ciencia ficción", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1333577589l/8694.jpg", status: "read", rating: 4, description: "Third installment of the Hitchhiker series. Arthur Dent, Ford Prefect and Slartibartfast must save the universe from the planet Krikkit, whose inhabitants want to obliterate everything that is not Krikkit. Cricket, time travel, talking mattresses on Squornshellous Zeta and the answer to the meaning of life are again at stake.", descriptionAi: true, owned: false },
    { title: "Mother Night", author: "Kurt Vonnegut Jr.", category: "Novela clásica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1344621657l/9592.jpg", status: "read", rating: 5, description: "Howard W. Campbell Jr., an American playwright who was the Voice of Nazi Propaganda during the Second World War —and a simultaneous Allied spy embedding coded messages in his broadcasts— awaits trial in an Israeli jail and writes his confession. A short, brilliant novel about the impossibility of standing outside the masks one chooses to wear.", descriptionAi: true, owned: false },
    { title: "How We Learn: Why Brains Learn Better Than Any Machine . . . for Now", author: "Stanislas Dehaene", category: "Divulgación científica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1562573168l/46064083.jpg", status: "read", rating: 4, description: "Cognitive neuroscience meets pedagogy. Four pillars of learning —attention, active engagement, error feedback and consolidation— are exposed in detail, with implications for school classrooms, parenting and even the design of artificial intelligence systems. A rigorous bridge between lab and practice.", descriptionAi: true, owned: false },
    { title: "Education for Critical Consciousness (Impacts)", author: "Paulo Freire", category: "Filosofía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1388657657l/169949.jpg", status: "read", rating: 4, description: "Twin essays that lay out the political pedagogy of critical consciousness: education as practice of freedom rather than reproduction of the existing social order. Drawing on adult-literacy campaigns in Brazil, the text proposes a dialogic method that treats the learner as a co-investigator of the world. A founding document of liberation pedagogy.", descriptionAi: true, owned: false },
    { title: "The Restaurant at the End of the Universe", author: "Douglas Adams", category: "Ciencia ficción", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1521213881l/8695.jpg", status: "read", rating: 5, description: "Second installment of the Hitchhiker series. After the Heart of Gold survives the previous adventures, Arthur, Ford, Zaphod, Trillian and Marvin pursue dinner at the Restaurant at the End of the Universe —the only restaurant that watches the End of Everything between courses— and uncover the secret of who really runs the universe.", descriptionAi: true, owned: false },
    { title: "Wool", author: "Hugh Howey", category: "Ciencia ficción", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1327889474l/12287209.jpg", status: "read", rating: 4, description: "Self-published debut that became a cult phenomenon. In a post-apocalyptic future, what remains of humanity lives inside an immense underground silo whose only sin is to wish to go outside —a wish that is punished with «cleaning», an exile to the toxic surface where the condemned scrub the camera lenses before they die. The plot expands the small original story into a sweeping resistance saga.", descriptionAi: true, owned: false },
    { title: "Chaos Kings: How Wall Street Traders Make Billions in the New Age of Crisis", author: "Scott Patterson", category: "Negocios", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1686093170l/62918551.jpg", status: "read", rating: 4, description: "Profiles the «crisis hunters» —Nassim Taleb, Mark Spitznagel, Universa— who built funds designed to win exactly when markets break, and traces their influence on twenty-first-century finance. Reads as an intellectual thriller about how a small group of contrarians took advantage of every market crash since 1987.", descriptionAi: true, owned: false },
    { title: "The Social Brain: The Psychology of Successful Groups", author: "Tracey Camilleri", category: "Psicología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1677852282l/60438875.jpg", status: "read", rating: 3, description: "Combines evolutionary psychology with management research to identify what makes small groups thrive and why almost no organization tolerates the size —around 150 active relationships— that the human brain prefers. Suggests practical ways to structure teams for connection rather than scale.", descriptionAi: true, owned: false },
    { title: "Doctors by Nature: How Ants, Apes, and Other Animals Heal Themselves", author: "Jaap de Roode", category: "Divulgación científica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1726572153l/218059153.jpg", status: "read", rating: 4, description: "Catalog of the surprising medical behaviors observed in nonhuman animals: monkeys eating clay, bees lining nests with antimicrobial resin, sparrows weaving cigarette butts into their nests, dolphins rubbing on antibacterial corals. The argument is that medicine predates humanity and that we have a lot to learn by watching.", descriptionAi: true, owned: false },
    { title: "Everything Is Tuberculosis: The History and Persistence of Our Deadliest Infection", author: "John  Green", category: "Historia", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1729825992l/220341389.jpg", status: "read", rating: 5, description: "A history of tuberculosis from prehistoric times to today's drug-resistant strains, with a special focus on the lived experience of patients in sub-Saharan Africa. The book mixes science, advocacy and personal memoir to make a passionate case that we already have the tools to end the deadliest infectious disease in human history.", descriptionAi: true, owned: false },
    { title: "The Illusion of Choice: 16 ½ psychological biases that influence what we buy", author: "Richard Shotton", category: "Psicología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1669667548l/60784553.jpg", status: "read", rating: 3, description: "Walks through sixteen and a half cognitive biases that shape consumer decisions —the anchoring effect, the labour illusion, the keenness for round numbers, social proof— and shows marketers how to put them to work ethically. Studded with hundreds of small experiments and brand stories.", descriptionAi: true, owned: false },
    { title: "From Chaos to Stability: How the Brain Invents Our Conscious Worlds (The New Neuroscience)", author: "Israel Rosenfield", category: "Psicología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1719010231l/213584333.jpg", status: "read", rating: 4, description: "Consciousness is a continuous construction, an act of organizing perception against chaos that draws on memory, body and language. The argument moves from clinical cases of disordered consciousness to philosophical reflection on what it means to be a self, in a tradition that runs through William James and Oliver Sacks.", descriptionAi: true, owned: false },
    { title: "Foundation and Earth", author: "Isaac Asimov", category: "Ciencia ficción", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1389759320l/29582.jpg", status: "read", rating: 5, description: "Cierre cronológico de la saga clásica. La búsqueda continúa: ahora se trata de encontrar Tierra, el planeta de origen de la humanidad, y de elegir entre Gaia, la Fundación y la Segunda Fundación qué futuro construir para la galaxia. Las piezas de las series Robot, Imperio y Fundación se conectan en una sola línea de tiempo.", descriptionAi: true, owned: false },
    { title: "Foundation's Edge", author: "Isaac Asimov", category: "Ciencia ficción", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1442311409l/76683.jpg", status: "read", rating: 5, description: "Cuarta entrega, escrita treinta años después. Un consejero de Terminus, convencido de que la Segunda Fundación nunca fue destruida, parte en un viaje galáctico hacia el planeta legendario Gaia y se encuentra con una propuesta que pone en duda todo el plan Seldon. Recupera con elegancia los misterios y los expande hacia una conclusión más ambiciosa.", descriptionAi: true, owned: false },
    { title: "The Wayfinders: Why Ancient Wisdom Matters in the Modern World (CBC Massey Lecture)", author: "Wade Davis", category: "Historia", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1395458406l/6373455.jpg", status: "read", rating: 4, description: "Massey Lectures devoted to the surviving traditional knowledge systems of indigenous peoples around the world: Polynesian navigation by stars and waves, Andean ritual agriculture, Inuit hunting on sea ice, Tibetan Buddhist contemplative science. The lectures argue that the loss of cultural diversity is as catastrophic as the loss of biodiversity and that the knowledge held by traditional wayfinders is irreplaceable.", descriptionAi: true, owned: false },
    { title: "Mindwandering: How Your Constant Mental Drift Can Improve Your Mood and Boost Your Creativity", author: "Moshe Bar", category: "Psicología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1721438129l/58293283.jpg", status: "read", rating: 4, description: "Reframes daydreaming as essential —rather than a productivity bug— to creativity, problem-solving and emotional regulation. Mixes lab studies of the default mode network with practical advice on how to give the wandering mind the space it needs in a culture that punishes anything that looks like staring out a window.", descriptionAi: true, owned: false },
    { title: "Belonging: The Science of Creating Connection and Bridging Divides", author: "Geoffrey L. Cohen", category: "Psicología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1656129594l/60165404.jpg", status: "read", rating: 4, description: "Decades of research on belonging in schools, workplaces, healthcare and politics distilled into concrete interventions that reduce loneliness and prejudice. The book describes brief writing exercises, mentor structures and identity-affirming practices that have produced measurable shifts in classrooms and clinics.", descriptionAi: true, owned: false },
    { title: "The Epic of Gilgamesh", author: "Anonymous", category: "Novela clásica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1388287904l/19351.jpg", status: "read", rating: 5, description: "Translation of the oldest surviving long story in human literature. The hero Gilgamesh, king of Uruk, befriends the wild man Enkidu; together they slay the giant Humbaba and resist the goddess Ishtar, but Enkidu's death sends Gilgamesh on a quest for the secret of immortality at the edge of the world. A foundational text whose echoes still reach us.", descriptionAi: true, owned: false },
    { title: "Why Zebras Don&apos;t Get Ulcers", author: "Robert M. Sapolsky", category: "", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1441955030l/327.jpg", status: "read", rating: 5, description: "Classic explanation of why chronic psychological stress damages bodies that evolved for short bursts of physical threat, and what we now know about preventing the diseases —cardiovascular, gastrointestinal, neurological, immune— that follow chronic stress. Mixes endocrinology, neuroscience and field observations of primates with a rare combination of clinical seriousness and wit.", descriptionAi: true, owned: false },
    { title: "The Education of a British-Protected Child: Essays", author: "Chinua Achebe", category: "Ensayo", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1436379772l/6406840.jpg", status: "read", rating: 5, description: "Collected essays —partly memoir, partly cultural criticism— that recount what it was like to grow up Igbo in colonial and postcolonial Nigeria. The pieces touch on language, the politics of African literature, Achebe's friendship with James Baldwin, and the responsibility of the African writer in a world still shaped by empire.", descriptionAi: true, owned: false },
    { title: "Fluke: Chance, Chaos, and Why Everything We Do Matters", author: "Brian Klaas", category: "Divulgación científica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1686591877l/177058906.jpg", status: "read", rating: 5, description: "Tour of chaos theory, contingency and the small accidents that change history: a turn at a stoplight, a misfired email, a Tokyo trip that saved Kyoto from the atomic bomb. Argues that the dominant scientific narrative —orderly, predictable, individualistic— misunderstands the world and offers a more humble framework for living in it.", descriptionAi: true, owned: false },
    { title: "The People vs. Democracy: Why Our Freedom Is in Danger and How to Save It", author: "Yascha Mounk", category: "Política", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1514781968l/36738610.jpg", status: "read", rating: 5, description: "Diagnoses the global erosion of liberal democracy as a divorce between liberalism (rule of law, minority rights) and democracy (popular sovereignty), each captured by different camps. Proposes a programmatic response that reconnects the two and that takes seriously the economic, identity and digital drivers of the current crisis.", descriptionAi: true, owned: false },
    { title: "The Hidden World: How Insects Sustain Life on Earth Today and Will Shape Our Lives Tomorrow", author: "George McGavin", category: "Divulgación científica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1681584006l/121141757.jpg", status: "read", rating: 4, description: "Makes the case for insects as the silent infrastructure of the planet —pollinators, recyclers, food for higher animals, indicators of ecosystem health— and warns about the consequences of their global decline. Stays both wide and humane, with a deep affection for the creatures most people prefer to swat.", descriptionAi: true, owned: false },
    { title: "Poverty for Profit: How Corporations Get Rich off America’s Poor", author: "Anne    Kim", category: "", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1709762400l/195473593.jpg", status: "read", rating: 5, description: "Investigative survey of the industries —payday lenders, prison telecoms, dialysis chains, charter-management organizations, predatory landlords, debt collectors— that systematically extract wealth from the U.S. poor while being subsidized by public dollars. Each chapter follows the money trail and proposes specific regulatory remedies.", descriptionAi: true, owned: false },
    { title: "Win Every Argument: The Art of Debating, Persuading, and Public Speaking", author: "Mehdi Hasan", category: "Autoayuda", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1648416732l/60505565.jpg", status: "read", rating: 5, description: "Lessons from competitive debate and broadcast interviews are distilled into a practical guide for arguing more effectively in public and private life. Covers structure, evidence, rhetorical devices, body language and how to recover from a punch. Aimed at anyone who has to stand up and speak in front of people who might not agree.", descriptionAi: true, owned: false },
    { title: "Anger and Forgiveness: Resentment, Generosity, Justice", author: "Martha C. Nussbaum", category: "Filosofía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1450647202l/26721206.jpg", status: "read", rating: 4, description: "Philosophical argument that anger, when scrutinized, is almost always either incoherent (when payback fantasies stand in for justice) or normatively wrong. Constructive politics, friendship and personal life all require turning toward generosity and forward-looking justice instead, even when ancient instincts pull the other way.", descriptionAi: true, owned: false },
    { title: "The Vital Question: Energy, Evolution, and the Origins of Complex Life", author: "Nick Lane", category: "Divulgación científica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1444265552l/26530386.jpg", status: "read", rating: 5, description: "How did life make the leap from prokaryotes to eukaryotes, the complex cells from which animals, plants and fungi descend? The answer, the book argues, lies in chemiosmosis at deep-sea alkaline vents and in a single endosymbiotic event that almost certainly happened only once. A bold reconstruction of life's most consequential bottleneck.", descriptionAi: true, owned: false },
    { title: "Los cuatro acuerdos: Una guía practica para la libertad personal", author: "Miguel Ruiz", category: "Autoayuda", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1348256973l/6600.jpg", status: "read", rating: 5, description: "Cuatro principios extraídos de la sabiduría tolteca: ser impecable con la palabra, no tomarse nada personal, no hacer suposiciones y hacer siempre lo mejor. Cada uno se propone como un acuerdo voluntario con uno mismo capaz de liberar a la persona de los pactos automáticos que aprendió de niña. Un manual breve de psicología práctica con resonancias espirituales.", descriptionAi: true, owned: false },
    { title: "The Earth Transformed: An Untold History", author: "Peter Frankopan", category: "Historia", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1677838656l/61965394.jpg", status: "read", rating: 4, description: "Global history retold through climate and environment: how shifts in rainfall, temperature and ecology shaped civilizations from Mesopotamia to today. The narrative moves between continents and centuries to show that human history has always been entangled with the planet, and that today's emergency is the latest chapter of a much older story.", descriptionAi: true, owned: false },
    { title: "The Serviceberry: Abundance and Reciprocity in the Natural World", author: "Robin Wall Kimmerer", category: "Biología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1760641870l/208840291.jpg", status: "read", rating: 4, description: "Short meditation on the gift economy of a single fruit. The serviceberry, generously offered by trees, birds and grandmothers, is used as a model for a non-extractive economics rooted in indigenous lifeways and gratitude. A small book with a large political implication.", descriptionAi: true, owned: false },
    { title: "Second Foundation", author: "Isaac Asimov", category: "Ciencia ficción", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1661015922l/29580.jpg", status: "read", rating: 5, description: "Tercera entrega. Mientras el Mulo sigue su búsqueda de la Segunda Fundación, los descendientes de Terminus comienzan también a sospechar de su existencia. La novela combina dos misterios paralelos sobre la naturaleza de esa fundación oculta y, sobre todo, sobre quién la dirige y dónde se esconde.", descriptionAi: true, owned: false },
    { title: "POPOL VUH: español", author: "MAYAS QUICHES", category: "", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1573412274l/48747828.jpg", status: "read", rating: 4, description: "Edición en español del libro sagrado de los mayas k'iche': la creación del mundo, los intentos fallidos de los dioses por modelar a la humanidad, las hazañas de los héroes gemelos Hunahpú e Ixbalanqué contra los señores de Xibalbá y las migraciones de los pueblos del altiplano guatemalteco. Texto cosmogónico fundamental de la literatura mesoamericana.", descriptionAi: true, owned: false },
    { title: "A Prayer for the Crown-Shy", author: "Becky Chambers", category: "Ciencia ficción", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1733422002l/40864030.jpg", status: "read", rating: 5, description: "Sequel to A Psalm for the Wild-Built. The tea monk Sibling Dex and the robot Mosscap continue their slow road trip across Panga, visiting villages and asking what people need now that the planet has rewilded. A gentle, solarpunk meditation on enough.", descriptionAi: true, owned: false },
    { title: "El señor presidente", author: "Miguel Ángel Asturias", category: "Política", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1376424137l/327281.jpg", status: "read", rating: 4, description: "Crónica esperpéntica de la dictadura de Manuel Estrada Cabrera en Guatemala. Una corte de aduladores, asesinos a sueldo, perros torturados, mendigos y víctimas inocentes orbita alrededor de un tirano sin nombre que controla todo desde un palacio. La prosa, deformada y alucinada, abrió en español el camino de la novela del dictador latinoamericano.", descriptionAi: true, owned: false },
    { title: "Foundation and Empire", author: "Isaac Asimov", category: "Ciencia ficción", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1391454612l/29581.jpg", status: "read", rating: 5, description: "Segunda novela de la saga. Las primeras crisis Seldon ya quedaron atrás cuando un mutante con habilidades mentales —el Mulo— irrumpe en la escena y altera el plan psicohistórico, demostrando que la historia no se predice fácilmente cuando aparecen individuos extraordinarios. La trama mezcla intriga política, persecuciones y un giro final memorable.", descriptionAi: true, owned: false },
    { title: "Foundation", author: "Isaac Asimov", category: "Ciencia ficción", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1417900846l/29579.jpg", status: "read", description: "Comienzo de la saga de la Fundación. En un imperio galáctico de doce mil años en decadencia, el matemático Hari Seldon desarrolla la psicohistoria —una ciencia capaz de predecir el comportamiento estadístico de grandes poblaciones— y planea fundar dos enclaves en los extremos de la galaxia para abreviar la edad de oscuridad que se avecina. Una de las obras fundacionales de la ciencia ficción.", descriptionAi: true, owned: false },
    { title: "Migrants: The Story of Us All", author: "Sam Miller", category: "Historia", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1668096353l/63270981.jpg", status: "read", rating: 5, description: "Sweeping global history of human migration that argues moving —not staying put— is the default human condition. Each chapter covers a different epoch and pattern, from prehistoric expansions out of Africa to refugee crossings in the Mediterranean, placing contemporary migrations in deep time and shared experience.", descriptionAi: true, owned: false },
    { title: "An Immense World: How Animal Senses Reveal the Hidden Realms Around Us", author: "Ed Yong", category: "Divulgación científica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1652105350l/59575939.jpg", status: "read", rating: 5, description: "Tour of the umwelten of dozens of species: electric fish, magnetoreceptive birds, infrared-detecting snakes, ultrasonic bats, vibration-reading spiders. Each chapter explains how an animal experiences the world through its own combination of senses, and reshapes the reader's sense of what perception even means.", descriptionAi: true, owned: false },
    { title: "Las venas abiertas de América Latina (Edición conmemorativa)", author: "Eduardo Galeano", category: "Historia", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1687936571l/123749149.jpg", status: "read", rating: 4, description: "Crónica feroz y poética de cinco siglos de extracción colonial y neocolonial en América Latina, desde el oro de Potosí hasta las dictaduras del siglo XX. Combina datos económicos, retratos de personajes y prosa de fuego para denunciar el saqueo continental. Una obra militante que sigue siendo lectura iniciática de la izquierda latinoamericana.", descriptionAi: true, owned: false },
    { title: "The Ultimate Hidden Truth of the World", author: "David Graeber", category: "Política", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1706474365l/205363978.jpg", status: "read", rating: 5, description: "Posthumous essay collection gathering some of the most-cited pieces by an anthropologist and activist of bureaucracy, debt, value, ritual and play. The essays span thirty years of thought and read together as an introduction to a generous, irreverent way of doing social science.", descriptionAi: true, owned: false },
    { title: "Pedro Páramo", author: "Juan Rulfo", category: "Novela clásica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1697799709l/136160907.jpg", status: "read", rating: 4, description: "Novela breve y vertiginosa. Juan Preciado llega a Comala, el pueblo donde le dijeron que encontraría a su padre, Pedro Páramo, y descubre que sus habitantes son fantasmas, ecos de un cacicazgo de violencia y deseo. La narración se rompe en voces sin tiempo y cierra la puerta entre la vida y la muerte. Cumbre de la prosa mexicana del XX.", descriptionAi: true, owned: false },
    { title: "Dust", author: "Hugh Howey", category: "Ciencia ficción", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1436806122l/18866705.jpg", status: "read", rating: 4, description: "Tercera novela de la saga del silo. Mientras los silos siguen funcionando bajo sus reglas crueles, los habitantes que han escapado intentan sobrevivir afuera y descubrir la verdad sobre la catástrofe que los enterró. El cierre de una distopía construida pieza a pieza desde un cuento de tres mil palabras.", descriptionAi: true, owned: false },
    { title: "Shift", author: "Hugh Howey", category: "Ciencia ficción", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1379003176l/17306293.jpg", status: "read", rating: 4, description: "Precuela y segunda novela de la saga del silo. Cuenta la historia del proyecto que creó los silos, los responsables políticos que decidieron meter a la humanidad bajo tierra y los siglos que pasaron antes del comienzo de la primera novela. Un giro narrativo que reorganiza por completo la lectura de la saga.", descriptionAi: true, owned: false },
    { title: "A Man for All Markets: From Las Vegas to Wall Street, How I Beat the Dealer and the Market", author: "Edward O. Thorp", category: "Negocios", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1471282417l/25733505.jpg", status: "read", rating: 5, description: "Autobiography of the mathematician who invented card counting at blackjack and went on to apply the same probabilistic mindset to running one of the first quantitative hedge funds. Equal parts memoir, gambling lore and primer on rational investment, with cameos by Claude Shannon, Warren Buffett and Rudy Giuliani.", descriptionAi: true, owned: false },
    { title: "The Mosquito: A Human History of Our Deadliest Predator", author: "Timothy C. Winegard", category: "Historia", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1544102229l/42983957.jpg", status: "read", rating: 4, description: "Rewrites the history of empires, religions and revolutions as a tale of mosquitoes and the diseases they carry: malaria, yellow fever, dengue, zika. Argues that the mosquito has killed more humans than all wars combined and that resisting or exploiting it has shaped major political turning points from Athens to Vietnam.", descriptionAi: true, owned: false },
    { title: "Are We Smart Enough to Know How Smart Animals Are?", author: "Frans de Waal", category: "Divulgación científica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1490975607l/30231743.jpg", status: "read", rating: 4, description: "Survey of comparative cognition that pushes back against the long tradition of testing animals on tasks designed for humans. Octopuses, crows, elephants, chimpanzees and dogs all turn out to be much smarter than we assumed —but only when the questions we ask them respect their own evolutionary history.", descriptionAi: true, owned: false },
    { title: "The Anthropocene Reviewed: Essays on a Human-Centered Planet", author: "John  Green", category: "Ensayo", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1616514130l/55145261.jpg", status: "read", rating: 4, description: "Essay collection growing out of a podcast: each chapter «reviews» a feature of the present —Diet Dr Pepper, sunsets, the Lascaux cave paintings, Halley's comet— on a five-star scale, mixing personal memoir with planetary observation. The cumulative effect is a quiet love letter to a fragile world.", descriptionAi: true, owned: false },
    { title: "The Righteous Mind: Why Good People Are Divided by Politics and Religion", author: "Jonathan Haidt", category: "Psicología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1534528902l/11324722.jpg", status: "read", rating: 4, description: "Social-psychology argument that moral judgment is intuitive first and reasoned afterwards, and that liberals and conservatives differ because they weigh six distinct moral foundations —care, fairness, liberty, loyalty, authority and sanctity— in different proportions. A hopeful framework for understanding political disagreement without dehumanizing the other side.", descriptionAi: true, owned: false },
    { title: "El fin de la muerte", author: "Liu Cixin", category: "Ciencia ficción", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1538051959l/32827109.jpg", status: "read", rating: 4, description: "Cierre de la trilogía de los Tres Cuerpos. La humanidad y los Trisolarianos llegan a un equilibrio basado en la disuasión cósmica; cuando este se rompe, el universo entero revela sus reglas oscuras y la teoría del «bosque oscuro» adquiere su sentido más radical. Una de las cumbres recientes de la ciencia ficción.", descriptionAi: true, owned: false },
    { title: "El bosque oscuro", author: "Liu Cixin", category: "Ciencia ficción", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1508781967l/32827084.jpg", status: "read", rating: 4, description: "Segunda parte de la trilogía. La humanidad descubre la teoría del bosque oscuro —cada civilización debe ocultarse o ser destruida— y selecciona a cuatro Wallfacers para enfrentar a la inminente flota trisolariana. La novela cruza el thriller geopolítico con la metafísica fría del cosmos, todo a escala de siglos.", descriptionAi: true, owned: false },
    { title: "El problema de los tres cuerpos", author: "Liu Cixin", category: "Ciencia ficción", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1511909569l/28487182.jpg", status: "read", rating: 5, description: "Inicio de la trilogía de ciencia ficción. Durante la Revolución Cultural, una astrofísica china traumatizada envía una señal al espacio que despierta la atención de una civilización agonizante en Alfa Centauri. Décadas después, una serie de suicidios entre científicos pone en marcha una investigación que conecta la física fundamental con una invasión que llegará en cuatro siglos.", descriptionAi: true, owned: false },
    { title: "Through a Glass Brightly: Using Science to See Our Species as We Really Are", author: "David Philip Barash", category: "Biología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1515277902l/36794097.jpg", status: "read", rating: 4, description: "Uses contemporary biology to dismantle several flattering self-images: human exceptionalism, free will, perfectibility, the assumption that we are the goal of evolution. Builds the case for a more honest humanism that takes our animal condition seriously rather than trying to wish it away.", descriptionAi: true, owned: false },
    { title: "Greed Is Dead", author: "Paul Collier", category: "Economía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1597161167l/52692578.jpg", status: "read", rating: 4, description: "The «homo economicus» model is empirically wrong. Cooperation, mutual obligation and shared identity drive prosperous societies; redesigning policy around this insight requires rebuilding trust, regional institutions and a richer language for the public good. A pragmatic, post-pandemic manifesto.", descriptionAi: true, owned: false },
    { title: "Other Minds", author: "Peter Godfrey-Smith", category: "Divulgación científica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1606353700l/28116739.jpg", status: "read", rating: 4, description: "Encounter between a philosopher of science and the octopus. The book follows the evolutionary path of cephalopods —who developed complex nervous systems independently from vertebrates— and uses them to ask big questions about the origin of consciousness and what it can possibly feel like to be a creature with eight arms that taste.", descriptionAi: true, owned: false },
    { title: "Thinking with Your Hands: The Surprising Science Behind How Gestures Shape Our Thoughts", author: "Susan Goldin-Meadow", category: "Psicología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1681110534l/62874262.jpg", status: "read", rating: 4, description: "Decades of work showing that gesture is not decoration. It shapes how we learn, reason and explain ideas to others. The book is full of experiments —teachers who gesture, children who learn faster when they do, surgeons who think with their fingers— that change the way you watch a conversation.", descriptionAi: true, owned: false },
    { title: "Orientalism", author: "Edward W. Said", category: "Historia", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1704228087l/355190.jpg", status: "read", rating: 4, description: "Foundational text of postcolonial studies. Argues that European representations of «the Orient» —in literature, philology, painting and policy memos— form a coherent body of knowledge whose function is to enable Western political domination. The book inaugurated a whole field of critical scholarship and remains polemically alive.", descriptionAi: true, owned: false },
    { title: "Virtue Signaling: Essays on Darwinian Politics & Free Speech", author: "Geoffrey Miller", category: "Psicología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1568843294l/50885372.jpg", status: "read", rating: 3, description: "Collection of essays arguing that political behavior often functions as costly signaling of moral fitness, and defending robust free-speech norms as the only sustainable defense against runaway moralized status games. Provocative, sometimes mischievous and always engaged with evolutionary theory.", descriptionAi: true, owned: false },
    { title: "Shame: The Politics and Power of an Emotion", author: "David Keen", category: "Política", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1680892443l/126249451.jpg", status: "read", rating: 3, description: "Examines how shame and humiliation drive politics —from genocide to populism to school discipline— and the conditions under which collective shame can fuel reform rather than backlash. Brings together psychology, history and conflict studies into a coherent argument about an emotion most political theory ignores.", descriptionAi: true, owned: false },
    { title: "The Histories", author: "Herodotus", category: "Historia", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1399225547l/1362.jpg", status: "read", rating: 5, description: "Foundational work of Greek history written in the fifth century BCE: an inquiry into the causes of the Persian Wars that doubles as a sprawling ethnography of the known world, from Egypt to Scythia. The text mixes anecdote, oral tradition, geography and political analysis with a curiosity that still feels modern.", descriptionAi: true, owned: false },
    { title: "Brains Through Time: A Natural History of Vertebrates", author: "Georg F. Striedter", category: "Neurociencia", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1577850440l/50234145.jpg", status: "read", rating: 4, description: "Reconstruction of half a billion years of brain evolution across vertebrates, organ by organ. Cerebellums, hypothalami, olfactory bulbs, neocortices: each structure is followed through its appearance in fish, amphibians, reptiles, birds and mammals, showing how new structures piggyback on ancient ones rather than replacing them.", descriptionAi: true, owned: false },
    { title: "How to Grow Old: Ancient Wisdom for the Second Half of Life (Ancient Wisdom for Modern Readers)", author: "Marcus Tullius Cicero", category: "Filosofía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1445789371l/26597350.jpg", status: "read", rating: 5, description: "Modern Princeton translation of De Senectute. Short, lucid arguments from a Roman elder statesman on why old age is not the catastrophe it is made out to be: physical decline is offset by experience, freedom from desire and the deeper pleasures of friendship, books and the garden.", descriptionAi: true, owned: false },
    { title: "Becoming Earth: How Our Planet Came to Life", author: "Ferris Jabr", category: "Divulgación científica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1705955968l/200634712.jpg", status: "read", rating: 5, description: "Argues that Earth is best understood as a single, evolving organism shaped by the organisms that inhabit it. Each chapter follows a co-evolutionary loop —between life and atmosphere, life and rock, life and rivers— to make the Gaia hypothesis empirically vivid rather than mystical.", descriptionAi: true, owned: false },
    { title: "Why We Remember: Unlocking Memory's Power to Hold on to What Matters", author: "Charan Ranganath", category: "", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1699034966l/157981712.jpg", status: "read", rating: 5, description: "Reframes memory as future-facing. We remember selectively in order to navigate, plan and connect; the bugs we complain about —forgetting names, misplacing keys— are usually features. Synthesizes recent neuroscience and offers a practical framework for living with the memory we have.", descriptionAi: true, owned: false },
    { title: "Writing to Persuade: How to Bring People Over to Your Side", author: "Trish Hall", category: "Lingüística", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1556344923l/41817516.jpg", status: "read", rating: 3, description: "Distilled craft of persuasive nonfiction writing, by a longtime opinion editor. Covers how to find a fresh argument, how to structure it, how to write a punchy lede, how to handle the editor and how to recover when the public turns on you. Indispensable for op-ed writers, advocates and lecturers.", descriptionAi: true, owned: false },
    { title: "Skin in the Game: The Hidden Asymmetries in Daily Life", author: "Nassim Nicholas Taleb", category: "Filosofía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1510319798l/36064445.jpg", status: "read", rating: 4, description: "Fifth entry in the Incerto. Argues that the world makes more sense when you keep an eye on who suffers when their advice is wrong: pundits, bureaucrats and CEOs without skin in the game create fragility for everyone else. A militant defense of practical knowledge over abstract expertise.", descriptionAi: true, owned: false },
    { title: "Pedagogy of the Oppressed", author: "Paulo Freire", category: "Autobiografía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1388180018l/72657.jpg", status: "read", rating: 5, description: "Founding text of liberation pedagogy, written from exile in the late 1960s. Argues against the «banking model» of education, where knowledge is deposited into passive students, and proposes a dialogical pedagogy where teacher and student investigate the world together. Among the most influential books of twentieth-century education.", descriptionAi: true, owned: false },
    { title: "Cultish: The Language of Fanaticism", author: "Amanda Montell", category: "Psicología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1762247387l/55338982.jpg", status: "read", rating: 4, description: "Linguistic field guide to how cult-like groups —from sects to multilevel marketing to fitness studios to political movements— use loaded language, jargon, mantras and thought-terminating clichés to bind members and silence dissent. Funny, sharp and disturbingly close to home.", descriptionAi: true, owned: false },
    { title: "High Conflict: Why We Get Trapped and How We Get Out", author: "Amanda Ripley", category: "Psicología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1611497693l/55711592.jpg", status: "read", rating: 5, description: "Distinguishes healthy «good conflict» from corrosive «high conflict» —the identity-fueled type that consumes families, organizations and politics. Through stories of mediators, ex-gang members and divorce coaches, shows that escape is possible and outlines what it actually takes.", descriptionAi: true, owned: false },
    { title: "El poder de las historias: O cómo han cautivado al ser humano, de la Ilíada a Harry Potter", author: "Martin Puchner", category: "Historia", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1551230468l/44149042.jpg", status: "read", rating: 5, description: "Dieciséis textos fundacionales —de Gilgamesh y la Ilíada al Quijote, los Manifiestos comunistas y Harry Potter— sirven para mostrar cómo las narraciones han forjado culturas, religiones, revoluciones y formas de leer. Cada capítulo combina historia material del libro y análisis literario para argumentar que las grandes historias siempre han sido también vehículos de poder.", descriptionAi: true, owned: false },
    { title: "Co-Intelligence: Living and Working with AI", author: "Ethan Mollick", category: "Tecnología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1709537279l/198678736.jpg", status: "read", rating: 5, description: "Pragmatic guide to using large language models in professional and personal life. Lays out four principles —invite AI to the table, be the human in the loop, treat AI as a strange person, assume this is the worst AI you'll ever use— and dozens of small experiments that build intuition quickly.", descriptionAi: true, owned: false },
    { title: "Plunder: Private Equity's Plan to Pillage America", author: "Brendan Ballou", category: "", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1667340956l/62874267.jpg", status: "read", rating: 4, description: "Documents how the private equity industry has extracted wealth from retail, healthcare, housing and prisons through leveraged buyouts that load companies with debt and strip them of assets. Each case study comes with the regulatory and political reforms that could rein in the industry.", descriptionAi: true, owned: false },
    { title: "A Beautifully Foolish Endeavor", author: "Hank Green", category: "Ciencia ficción", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1594920502l/49039441.jpg", status: "read", rating: 5, description: "Sequel to An Absolutely Remarkable Thing. With April May presumed dead, her friends and the alien Carls' game return, and Hank Green ramps up his satire of online fame, identity and political polarization.", descriptionAi: true, owned: false },
    { title: "The Utopia of Rules: On Technology, Stupidity, and the Secret Joys of Bureaucracy", author: "David Graeber", category: "Política", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1417415465l/22245334.jpg", status: "read", rating: 5, description: "Anarchist essays on bureaucracy in late capitalism. Argues that contemporary life is drowning in administrative forms and that this paperwork dystopia is the result of specific political choices, not a neutral consequence of scale. Provocative, funny and morally serious at the same time.", descriptionAi: true, owned: false },
    { title: "The Paradox of Choice: Why More Is Less", author: "Barry Schwartz", category: "Psicología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1410138134l/10639.jpg", status: "read", rating: 4, description: "Empirical case that the proliferation of options in modern consumer life —42 kinds of jam, 19 kinds of mortgage— increases anxiety, regret and dissatisfaction rather than freedom. Distinguishes maximizers from satisficers and offers strategies to reduce the cognitive load of decision-making.", descriptionAi: true, owned: false },
    { title: "Order without Design: How Markets Shape Cities", author: "Alain Bertaud", category: "Economía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1544515502l/39644188.jpg", status: "read", rating: 4, description: "Urban economist's challenge to top-down planning orthodoxy. Cities work, the argument goes, because land prices coordinate millions of decisions far more efficiently than masterplans; the planner's job should be to enable that order, not to fight it. Controversial and grounded in decades of practice from Hartford to Shanghai.", descriptionAi: true, owned: false },
    { title: "Change: How Organizations Achieve Hard-to-Imagine Results in Uncertain and Volatile Times", author: "John P. Kotter", category: "Negocios", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1620291553l/57961293.jpg", status: "read", rating: 2, description: "Synthesizes thirty years of work on change leadership for a world where the pace of disruption keeps accelerating. Argues that organizations need both the «survive» channel (hierarchy, processes, KPIs) and the «thrive» channel (networks, opportunity, urgency) operating in parallel.", descriptionAi: true, owned: false },
    { title: "The Playbook: How to Deny Science, Sell Lies, and Make a Killing in the Corporate World", author: "Jennifer Jacquet", category: "Política", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1659191480l/60044520.jpg", status: "read", rating: 4, description: "Identifies the recurring tactics —manufacturing doubt, attacking scientists, blaming consumers, sponsoring fake research— that corporations from tobacco to sugar to oil have used to delay regulation. Each tactic is named, illustrated and paired with a counter-tactic that public-interest advocates have used to fight back.", descriptionAi: true, owned: false },
    { title: "Technopoly: The Surrender of Culture to Technology", author: "Neil Postman", category: "Tecnología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1388365812l/79678.jpg", status: "read", rating: 5, description: "Argues that technology is never neutral and that the United States has slid from a tool-using culture, through a technocracy, to a full «technopoly» in which technology dictates the questions worth asking. A pessimistic but useful diagnosis written before social media made it more urgent.", descriptionAi: true, owned: false },
    { title: "Saving Normal: An Insider's Revolt Against Out-Of-Control Psychiatric Diagnosis, DSM-5, Big Pharma, and the Medicalization of Ordinary Life", author: "Allen Frances", category: "", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1364850431l/16248231.jpg", status: "read", rating: 5, description: "Critique of the expansion of psychiatric diagnoses written by one of the architects of DSM-IV. Argues that the DSM-5 turned ordinary unhappiness, distractibility and grief into diseases and gave Big Pharma cover to prescribe pills for them. A call for diagnostic restraint and clinical wisdom.", descriptionAi: true, owned: false },
    { title: "Mind in Motion: How Action Shapes Thought", author: "Barbara Tversky", category: "Psicología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1557350633l/42118411.jpg", status: "read", rating: 4, description: "Argues that thought is built from spatial cognition: we think with our bodies first and abstract ideas later, inheriting the structures of physical action. Each chapter draws on cognitive psychology experiments to show how navigation, gesture and orientation underlie language, math and storytelling.", descriptionAi: true, owned: false },
    { title: "The Open Society and Its Enemies", author: "Karl Popper", category: "Filosofía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1417985695l/240592.jpg", status: "read", rating: 5, description: "Two-volume defense of liberal democracy against historicism, written during the Second World War. Plato, Hegel and Marx are read as champions of «closed» societies hostile to piecemeal reform; the alternative is an open society of fallible institutions that can be corrected without violence. A founding text of postwar liberalism.", descriptionAi: true, owned: false },
    { title: "Same as Ever: A Guide to What Never Changes", author: "Morgan Housel", category: "Psicología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1680687321l/125116554.jpg", status: "read", rating: 5, description: "Twenty-three short essays on the recurring patterns in human behavior —risk, story, envy, surprise, expectations— that endure even as technology and markets keep changing. The argument is that betting on what won't change is usually more durable than predicting what will.", descriptionAi: true, owned: false },
    { title: "Getting the Love You Want: A Guide for Couples", author: "Harville Hendrix", category: "Autoayuda", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1388871224l/46188.jpg", status: "read", rating: 4, description: "Classic introduction to «imago» therapy: a structured method for couples to recognize how childhood wounds shape adult conflict, to identify the unconscious partner they keep choosing and to use the relationship itself as the site of healing. Comes with exercises and an extensive workbook.", descriptionAi: true, owned: false },
    { title: "Narrative Economics: How Stories Go Viral and Drive Major Economic Events", author: "Robert J. Shiller", category: "Economía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1565785098l/44526017.jpg", status: "read", rating: 5, description: "Argues that economic shifts are driven not just by data but by the contagious narratives people share about the economy: stories about real estate, technology, generations, debt. Borrows tools from epidemiology to model how narratives spread and proposes including them in macroeconomic analysis.", descriptionAi: true, owned: false },
    { title: "Enzymes: A Very Short Introduction", author: "Paul  Engel", category: "Divulgación científica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1594055893l/52049776.jpg", status: "read", rating: 4, description: "Concise overview of enzymes —what they are, how they catalyze life's chemistry, the kinetic models used to describe them, and how biotechnology, medicine and industry put them to work. A small volume that punches well above its weight as a portable introduction.", descriptionAi: true, owned: false },
    { title: "Isaac Newton", author: "James Gleick", category: "Biografía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1386745732l/17098.jpg", status: "read", rating: 5, description: "Short biography of the seventeenth-century mathematician and natural philosopher who invented calculus, mapped the rainbow, formulated universal gravitation and ran the Royal Mint. Captures both his genius and his eccentricities —the alchemical experiments, the warden's persecutions, the long simmering feuds— in elegant journalistic prose.", descriptionAi: true, owned: false },
    { title: "Two Cheers for Anarchism: Six Easy Pieces on Autonomy, Dignity and Meaningful Work and Play", author: "James C. Scott", category: "Política", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1384020718l/14891877.jpg", status: "read", rating: 5, description: "Six short essays that apply the anarchist sensibility to ordinary life: the petty officialisms we tolerate, the small acts of insubordination that make institutions livable, the difference between standardized expertise and vernacular knowledge, the politics of red tape. A friendly companion to a larger body of writing about everyday autonomy.", descriptionAi: true, owned: false },
    { title: "The Master and His Emissary: The Divided Brain and the Making of the Western World", author: "Iain McGilchrist", category: "Psicología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1328826802l/6968772.jpg", status: "read", rating: 5, description: "Argues that the brain's two hemispheres attend to the world in genuinely complementary ways, and that the progressive dominance of the left hemisphere has shaped Western culture toward abstraction, control and rationalism at the cost of context, embodiment and meaning. Densely argued, with implications for art, religion and science.", descriptionAi: true, owned: false },
    { title: "Systems Thinking For Social Change: A Practical Guide to Solving Complex Problems, Avoiding Unintended Consequences, and Achieving Lasting Results", author: "David Peter Stroh", category: "Negocios", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1444660467l/26089423.jpg", status: "read", rating: 4, description: "Adapts systems-thinking tools —causal loops, leverage points, behavior-over-time graphs— for nonprofits and social-change leaders trying to break stuck patterns. Each chapter is built around a real campaign, with exercises that translate Donella Meadows into the daily life of a foundation officer.", descriptionAi: true, owned: false },
    { title: "Amusing Ourselves to Death: Public Discourse in the Age of Show Business", author: "Neil Postman", category: "Filosofía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1568871230l/74034.jpg", status: "read", rating: 5, description: "Cultural criticism that compares Orwell and Huxley as competing dystopias and argues that television, by turning all public discourse —news, politics, religion, education— into entertainment, fulfilled Huxley's nightmare. Required reading made even more relevant by the internet that came after.", descriptionAi: true, owned: false },
    { title: "Evolutionary Ideas: Unlocking ancient innovation to solve tomorrow’s challenges", author: "Sam Tatam", category: "", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1644339048l/60316858.jpg", status: "read", rating: 5, description: "Reframes innovation as natural selection on ideas, with case studies from advertising, public health and product design. Twenty practical principles derived from biology —exaptation, niche construction, mimicry, intermediate forms— are turned into a toolkit for designing experiments that let useful ideas survive contact with reality.", descriptionAi: true, owned: false },
    { title: "Attention!: The power of simple decisions in a distracted world", author: "Rob  Hatch", category: "Audiobook", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1601939137l/55575388.jpg", status: "read", rating: 3, description: "Makes the case for small, repeatable decisions as the highest-leverage move in a noisy economy. Argues that the scarce resource is no longer information but attention, and that the discipline to spend it well separates resilient people and organizations from the rest.", descriptionAi: true, owned: false },
    { title: "Hidden Potential: The Science of Achieving Greater Things", author: "Adam M. Grant", category: "Autoayuda", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1689111352l/157095669.jpg", status: "read", rating: 5, description: "Argues that what we call talent often masks character traits and structural luck. Shows research-backed ways to build the skills that compound over time —discomfort tolerance, sponging absorption, deliberate scaffolding— and to design systems that draw out hidden potential in classrooms, teams and oneself.", descriptionAi: true, owned: false },
    { title: "The Narrow Road Between Desires", author: "Patrick Rothfuss", category: "Fantasía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1716011662l/157265081.jpg", status: "read", rating: 5, description: "Expanded reissue of the Bast novella «The Lightning Tree». A single day in the life of Kvothe's mischievous apprentice as he grants favors to children, trades in secrets and arranges small revenges in a sleepy village. The same musical prose of the Kingkiller Chronicle in pocket form.", descriptionAi: true, owned: false },
    { title: "A Hunter-Gatherer's Guide to the 21st Century: Evolution and the Challenges of Modern Life", author: "Heather E. Heying", category: "", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1611977225l/56883406.jpg", status: "read", rating: 5, description: "Argues that many modern ills —diet, parenting, education, mating, sleep— stem from mismatches between our hunter-gatherer adaptations and contemporary life. Each chapter pairs evolutionary analysis with practical advice, sometimes contrarian and always provocative.", descriptionAi: true, owned: false },
    { title: "The Lightning Tree", author: "Patrick Rothfuss", category: "Fantasía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1659900457l/55262194.jpg", status: "read", rating: 5, description: "Short story in the Rogues anthology. A single day with Bast, who concedes favors and trades in secrets in a sleepy village; later expanded into The Narrow Road Between Desires.", descriptionAi: true, owned: false },
    { title: "Wanting: The Power of Mimetic Desire in Everyday Life", author: "Luke  Burgis", category: "", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1615240502l/54860444.jpg", status: "read", rating: 4, description: "Brings René Girard's theory of imitative desire into the world of work, dating and consumer culture: most of our wants are borrowed from models we rarely notice. Includes practical exercises to identify those models and to choose «thick» desires worth pursuing over «thin» ones imported by social comparison.", descriptionAi: true, owned: false },
    { title: "God: An Anatomy", author: "Francesca Stavrakopoulou", category: "Espiritualidad", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1619419541l/57282028.jpg", status: "read", rating: 4, description: "Reconstructs the corporeal Yahweh of the ancient Israelites —his feet, hands, genitals and face— from biblical and extrabiblical sources, and shows how a richly embodied tribal god became the disembodied God of monotheism. Provocative biblical scholarship written for general readers.", descriptionAi: true, owned: false },
    { title: "Gut: The Inside Story of Our Body's Most Underrated Organ", author: "Giulia Enders", category: "", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1435168687l/23013953.jpg", status: "read", rating: 5, description: "Witty popular tour of the digestive tract, the enteric nervous system and the microbiome, mixing science with everyday health advice. Originally a German bestseller, the book made it acceptable to talk about constipation, allergies and probiotics at the dinner table.", descriptionAi: true, owned: false },
    { title: "Understanding Complexity", author: "Scott E. Page", category: "Divulgación científica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1654077152l/46138936.jpg", status: "read", rating: 4, description: "Distills complexity science —agents, networks, emergence, adaptation, robust-yet-fragile systems— into a brisk primer for readers who want to think more clearly about social and economic phenomena. Comes with a clear set of mental models that can be applied to anything from city growth to organizational design.", descriptionAi: true, owned: false },
    { title: "Bernoulli's Fallacy: Statistical Illogic and the Crisis of Modern Science", author: "Aubrey Clayton", category: "", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1622419217l/55825328.jpg", status: "read", rating: 5, description: "Argues that the standard frequentist toolkit of significance testing is built on a logical error inherited from a nineteenth-century misreading of Bernoulli, and that Bayesian inference is the correct foundation. A polemical history that doubles as a tutorial on how scientific evidence should be evaluated.", descriptionAi: true, owned: false },
    { title: "How to Be an Antiracist", author: "Ibram X. Kendi", category: "Misterio", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1560163756l/40265832.jpg", status: "read", rating: 5, description: "Argues that the opposite of «racist» is not «not racist» but actively antiracist, and that this distinction has political and personal consequences. Mixes autobiography, history and policy analysis to map how power, policy and individual choice interlock —and how each can be changed.", descriptionAi: true, owned: false },
    { title: "One Day All This Will Be Yours", author: "Adrian Tchaikovsky", category: "Ciencia ficción", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1593355556l/54303485.jpg", status: "read", rating: 5, description: "Short novel. The last survivor of the Time War lives alone at the very end of history and murders anyone who shows up; until visitors arrive who refuse to be killed and the comfortable apocalypse he has built begins to break open. Black-comedy science fiction at its most economical.", descriptionAi: true, owned: false },
    { title: "Walking to Aldebaran", author: "Adrian Tchaikovsky", category: "Ciencia ficción", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1539510199l/42201505.jpg", status: "read", rating: 4, description: "Novella. The astronaut Gary Rendell wanders lost through an alien artifact in the outer solar system, narrating his slow transformation into something other than human while readers slowly understand what is really going on. Compact horror science fiction at a sustained boil.", descriptionAi: true, owned: false },
    { title: "Autopilot: The Art & Science of Doing Nothing", author: "Andrew  Smart", category: "Psicología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1399494666l/18053732.jpg", status: "read", rating: 4, description: "Argues that idleness is essential to creativity and decision-making, drawing on neuroscience to defend daydreaming, slowness and unstructured time as productive rather than wasteful. Counterpoint to the cult of productivity for readers who already suspect that the always-on life is not working.", descriptionAi: true, owned: false },
    { title: "Against Method", author: "Paul Karl Feyerabend", category: "Filosofía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1373999202l/137979.jpg", status: "read", rating: 5, description: "Subtitled «Outline of an Anarchistic Theory of Knowledge». Argues that the history of science shows no single «scientific method»; the great breakthroughs of Galileo, Copernicus and others required tactics that any methodological rulebook would have forbidden. A landmark of philosophy of science whose final motto —«anything goes»— still scandalizes.", descriptionAi: true, owned: false },
    { title: "The Story of the Human Body: Evolution, Health, and Disease", author: "Daniel E. Lieberman", category: "Divulgación científica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1375545961l/17736859.jpg", status: "read", rating: 5, description: "Traces the evolutionary history of the human body from the first bipedal apes to the seated modern office worker. Argues that many contemporary diseases —diabetes, low-back pain, myopia, anxiety— are «mismatch» diseases caused by living in environments our bodies were not designed for.", descriptionAi: true, owned: false },
    { title: "Life on the Edge: The Coming of Age of Quantum Biology", author: "Johnjoe McFadden", category: "Divulgación científica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1429821731l/24040194.jpg", status: "read", rating: 5, description: "Surveys the growing evidence that quantum-mechanical effects play a role in biology: photosynthesis, enzyme catalysis, bird navigation, even consciousness. A friendly introduction to a young field that does not pretend to have all the answers.", descriptionAi: true, owned: false },
    { title: "Lives of the Stoics: The Art of Living from Zeno to Marcus Aurelius", author: "Ryan Holiday", category: "Filosofía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1594616854l/50484473.jpg", status: "read", rating: 5, description: "Brief biographies of twenty-six Stoic philosophers —from the obscure founders to Roman senators and emperors— that show how the philosophy was lived as well as theorized. A complement to the better-known anthologies of Stoic texts.", descriptionAi: true, owned: false },
    { title: "Why We Work (TED Books)", author: "Barry Schwartz", category: "Negocios", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1440993087l/23280225.jpg", status: "read", rating: 5, description: "Argues against the Adam-Smithian view that people work only for money. Surveys the conditions —meaning, autonomy, mastery, voice, community— that make work flourishing rather than miserable, and shows how the dominant economic model has actively suppressed those conditions for two centuries.", descriptionAi: true, owned: false },
    { title: "Stumbling on Happiness", author: "Daniel Todd Gilbert", category: "Psicología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1327947323l/56627.jpg", status: "read", rating: 5, description: "Cognitive-science investigation of why humans are bad at predicting what will make them happy. Loss aversion, focusing illusion, immune system to memory: each chapter shows another way in which the brain simulates futures inaccurately. Funny and unusually well written for a science book.", descriptionAi: true, owned: false },
    { title: "Persian Fire: The First World Empire and the Battle for the West", author: "Tom Holland", category: "Historia", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1171501730l/103749.jpg", status: "read", rating: 4, description: "Narrative history of the Persian wars: the rise of the Achaemenid empire, the Ionian revolt, Marathon, Thermopylae, Salamis and Plataea. Argues that the Greco-Persian conflict was a world-historical encounter between two civilizations whose outcome shaped what we now call «the West».", descriptionAi: true, owned: false },
    { title: "The (Mis)Behavior of Markets", author: "Benoît B. Mandelbrot", category: "Negocios", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1387705519l/665134.jpg", status: "read", rating: 5, description: "Applies fractal geometry to financial markets and argues that the standard Gaussian models of risk badly underestimate the frequency and severity of crashes. Combines memoir, popular mathematics and finance history into a critique of modern portfolio theory that the 2008 crash made painfully concrete.", descriptionAi: true, owned: false },
    { title: "The Song of the Cell: An Exploration of Medicine and the New Human", author: "Siddhartha Mukherjee", category: "Divulgación científica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1666198162l/60321392.jpg", status: "read", rating: 5, description: "History and current frontier of cell biology, from Hooke's microscope to CAR-T cells and stem-cell therapies. Argues that medicine is on the verge of an era in which engineered cells —rather than drugs— become the principal therapeutic tool. Equal parts science, biography and clinical narrative.", descriptionAi: true, owned: false },
    { title: "The Denial of Death", author: "Ernest Becker", category: "Filosofía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1388432490l/2761.jpg", status: "read", rating: 3, description: "Argues that human civilization is built atop heroic systems designed to deny mortality, and that recognizing this denial is the first step toward maturity. Pulitzer-winning synthesis of psychoanalysis, anthropology and existential philosophy whose influence on terror-management theory is still felt.", descriptionAi: true, owned: false },
    { title: "The Stranger", author: "Albert Camus", category: "Novela clásica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1738704267l/49552.jpg", status: "read", rating: 4, description: "1942 novel. Meursault, a clerk in colonial Algiers, kills an Arab on a sunlit beach and is then condemned more for refusing to feign emotion than for the crime itself. Short, hypnotic and inseparable from the existentialist tradition.", descriptionAi: true, owned: false },
    { title: "This Changes Everything: Capitalism vs. The Climate", author: "Naomi Klein", category: "Política", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1418103804l/21913812.jpg", status: "read", rating: 4, description: "Argues that the climate crisis is not an environmental issue that capitalism can solve with greener products, but a fundamental challenge to the extractive logic of the system itself. Reports from frontline communities in Greece, Alberta, Greece and India to imagine a different political economy.", descriptionAi: true, owned: false },
    { title: "The Forgetting Machine: Memory, Perception, and the \"Jennifer Aniston Neuron\"", author: "Rodrigo Quian Quiroga", category: "Divulgación científica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1502135343l/34196225.jpg", status: "read", rating: 4, description: "Recounts the discovery of «concept cells» —individual neurons that fire selectively for a specific person or idea— and what they imply for memory, perception and the self. Explains a major recent breakthrough in cognitive neuroscience for the general reader.", descriptionAi: true, owned: false },
    { title: "Mission Economy: A Moonshot Guide to Changing Capitalism", author: "Mariana Mazzucato", category: "Economía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1611523123l/52745048.jpg", status: "read", rating: 4, description: "Draws on the Apollo program to argue for mission-driven public investment as the way to tackle climate, inequality and digital monopolies. Reorients the role of the state from market-corrector to market-maker and proposes governance frameworks to make it democratic.", descriptionAi: true, owned: false },
    { title: "The Scout Mindset: Why Some People See Things Clearly and Others Don't", author: "Julia Galef", category: "Psicología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1612196393l/42041926.jpg", status: "read", rating: 5, description: "Contrasts «soldier» reasoning, which defends preexisting beliefs, with the «scout» mindset of seeking accurate maps. Offers practices —probabilistic thinking, calibration exercises, identity hygiene— to strengthen the latter and a friendly philosophy of how to update one's mind without losing one's footing.", descriptionAi: true, owned: false },
    { title: "Galápagos", author: "Kurt Vonnegut Jr.", category: "Ciencia ficción", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1585146350l/9593.jpg", status: "read", rating: 4, description: "Crucero a las Galápagos varado durante una pandemia mundial que esteriliza al resto de la humanidad. Un narrador fantasma cuenta desde el futuro cómo, un millón de años después, los descendientes de los náufragos —ya con cabezas pequeñas y aletas— se han adaptado al océano. Una de las novelas más oscuramente cómicas sobre la inteligencia humana.", descriptionAi: true, owned: false },
    { title: "For Profit: A History of Corporations", author: "William Magnuson", category: "Historia", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1647264648l/60568507.jpg", status: "read", rating: 5, description: "Traces the corporation from ancient Rome through the East India Company to modern tech giants, arguing that the institution oscillates between civic missions and predatory phases. The history is told as a series of regulatory bargains that we can renegotiate when the moment calls for it.", descriptionAi: true, owned: false },
    { title: "The Triumph of Seeds: How Grains, Nuts, Kernels, Pulses, and Pips Conquered the Plant Kingdom and Shaped Human History", author: "Thor Hanson", category: "Divulgación científica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1416445819l/23013818.jpg", status: "read", rating: 4, description: "Natural history of the seed: how this evolutionary innovation came to dominate land plants, how human civilizations rose by domesticating a handful of seed crops, and how seeds keep showing up in unexpected places —chocolate, coffee, cotton, gunpowder. Curiosity-driven botany.", descriptionAi: true, owned: false },
    { title: "The Basic Laws of Human Stupidity", author: "Carlo M. Cipolla", category: "Filosofía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1595814345l/49348225.jpg", status: "read", rating: 5, description: "Deadpan essay laying out a taxonomy of intelligence and stupidity according to whether each act benefits or harms self and others. Ends with the unsettling conclusion that stupid people are the most dangerous category and that their proportion in any society is a constant. Short, brilliant, oddly bracing.", descriptionAi: true, owned: false },
    { title: "Phishing for Phools: The Economics of Manipulation and Deception", author: "George A. Akerlof", category: "Economía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1431977642l/25560530.jpg", status: "read", rating: 5, description: "Argues that any free market with information asymmetries will tend to produce «phishing» —the manipulation of consumers in directions they would not choose if fully informed— and that this is a structural feature of capitalism rather than a bug. Updates Akerlof's lemons argument for the era of behavioral economics.", descriptionAi: true, owned: false },
    { title: "Work: A Deep History, from the Stone Age to the Age of Robots", author: "James Suzman", category: "Historia", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1589287074l/53398570.jpg", status: "read", rating: 5, description: "Traces 300,000 years of human work and argues that our modern obsession with toil is a recent aberration, not a continuation of ancestral life. Hunter-gatherers worked little, agricultural villagers worked seasonally, industrial workers around the clock; today's office workers may be returning to something stranger still.", descriptionAi: true, owned: false },
    { title: "The Body Keeps the Score: Brain, Mind, and Body in the Healing of Trauma", author: "Bessel van der Kolk", category: "Psicología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1594559067l/18693771.jpg", status: "read", rating: 5, description: "Synthesis of decades of clinical research on trauma. Shows how the body remembers what the mind cannot bear to recall and surveys the therapeutic approaches —EMDR, yoga, neurofeedback, internal family systems— that work with this somatic memory. A book that helped reshape public understanding of PTSD.", descriptionAi: true, owned: false },
    { title: "Blindsight: The (Mostly) Hidden Ways Marketing Reshapes Our Brains", author: "Matt           Johnson", category: "Psicología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1588033552l/52225003.jpg", status: "read", rating: 5, description: "Lays out the neuroscience of advertising —attention, emotion, memory, reward, social identification— and how brands exploit it, with practical defenses for consumers. Stays evidence-based throughout while still being funny about TikTok ads and Liquid Death.", descriptionAi: true, owned: false },
    { title: "Strangers to Ourselves: Discovering the Adaptive Unconscious", author: "Timothy D. Wilson", category: "Psicología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1430649296l/15658.jpg", status: "read", rating: 5, description: "Argues that most of mental life is unconscious in a sense different from Freud's: a fast, adaptive system that makes most of our decisions before consciousness even shows up. Surveys the empirical literature and asks what self-knowledge can possibly mean if the deciding self is mostly hidden.", descriptionAi: true, owned: false },
    { title: "Thinking: The New Science of Decision-Making, Problem-Solving, and Prediction", author: "John Brockman", category: "Psicología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1630574310l/17349252.jpg", status: "read", rating: 5, description: "Edited Edge.org anthology in which leading psychologists, economists and computer scientists summarize the recent science of judgment for general readers. Topics range from prospect theory to deep learning, with each chapter standing as a primer in its own right.", descriptionAi: true, owned: false },
    { title: "Evolutionary Psychology: A Beginner's Guide", author: "Robin I.M. Dunbar", category: "Psicología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1407814382l/1144140.jpg", status: "read", rating: 4, description: "Primer on the central ideas, methods and controversies of evolutionary psychology, written for general readers. Covers mating, parenting, language, morality and aggression with examples that show how the discipline tests hypotheses rather than just speculates about them.", descriptionAi: true, owned: false },
    { title: "The Horse, the Wheel, and Language: How Bronze-Age Riders from the Eurasian Steppes Shaped the Modern World", author: "David W. Anthony", category: "Historia", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1619046003l/1831667.jpg", status: "read", rating: 5, description: "Reconstructs the migration of Indo-European-speaking horse-and-wagon cultures out of the Pontic-Caspian steppe, who carried language, mythology and bronze technology across Eurasia. Synthesizes archaeology, historical linguistics and genetics into a rare integrated picture.", descriptionAi: true, owned: false },
    { title: "Capitalist Realism: Is There No Alternative?", author: "Mark Fisher", category: "Política", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1732718088l/6763725.jpg", status: "read", rating: 4, description: "Short polemic arguing that the dominant cultural mood of late capitalism is the conviction that there is no alternative —not because we have proven it true but because the imagination has been colonized. Mixes Marxist theory, mental-health diagnosis and pop culture in equal measure.", descriptionAi: true, owned: false },
    { title: "How Religion Evolved: And Why It Endures", author: "Robin I.M. Dunbar", category: "Espiritualidad", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1633159816l/57001983.jpg", status: "read", rating: 5, description: "Uses evolutionary psychology to argue that religion emerged as a way to bond ever-larger human groups, and that its enduring forms exploit the same neural systems as music, laughter and the experience of awe. Combines field studies, lab experiments and history.", descriptionAi: true, owned: false },
    { title: "The Story Paradox: How Our Love of Storytelling Builds Societies and Tears them Down", author: "Jonathan Gottschall", category: "Psicología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1617717672l/56643990.jpg", status: "read", rating: 5, description: "Examines the dark side of narrative. Stories can build cooperation, but they also drive conspiracy theories, tribalism and political collapse; the same cognitive machinery that produces literature produces QAnon. A counterweight to romantic theories of story.", descriptionAi: true, owned: false },
    { title: "Capital in the Twenty First Century", author: "Thomas Piketty", category: "Economía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1390111547l/18736925.jpg", status: "read", rating: 4, description: "Marshals two centuries of data to show that when the return on capital exceeds growth, wealth concentrates relentlessly, with destabilizing political consequences. Proposes a global tax on capital as the only structurally adequate response. A defining book of the post-2008 economic debate.", descriptionAi: true, owned: false },
    { title: "In Search of Mycotopia: Citizen Science, Fungi Fanatics, and the Untapped Potential of Mushrooms", author: "Doug Bierend", category: "Divulgación científica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1611556197l/55854545.jpg", status: "read", rating: 3, description: "Embeds with the global community of amateur mycologists rediscovering the role of fungi in medicine, food, materials and the imagination. Equal parts travelogue, interview and scientific reporting, with stops in Reishi farms and psilocybin labs.", descriptionAi: true, owned: false },
    { title: "Don't Think of an Elephant! Know Your Values and Frame the Debate: The Essential Guide for Progressives", author: "George Lakoff", category: "", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1429063124l/13455.jpg", status: "read", rating: 4, description: "Manual on cognitive framing for the U.S. political left. Explains how the choice of words —«tax relief», «death tax», «entitlements»— pre-decides debates and gives the right an enduring advantage. Includes case studies on tax, war, abortion and family policy and proposes alternative progressive frames.", descriptionAi: true, owned: false },
    { title: "Exercised: The Science of Physical Activity, Rest and Health", author: "Daniel E. Lieberman", category: "Divulgación científica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1597669547l/54993634.jpg", status: "read", rating: 5, description: "Argues that human beings did not evolve to exercise but to move when survival demanded it, and that today's sedentary diseases stem from a mismatch between hunter-gatherer bodies and chair-bound lives. Surveys decades of research on walking, running, lifting and sleeping and arrives at common-sense prescriptions backed by data.", descriptionAi: true, owned: false },
    { title: "Algorithms to Live By: The Computer Science of Human Decisions", author: "Brian  Christian", category: "Divulgación científica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1454296875l/25666050.jpg", status: "read", rating: 5, description: "Applies computer-science concepts —optimal stopping, explore/exploit, caching, scheduling, Bayesian inference, overfitting— to everyday human problems. The result is an unusual self-help book that explains why your sock drawer should be a stack, when to stop looking for an apartment and how to manage email tractably.", descriptionAi: true, owned: false },
    { title: "A Thousand Brains: A New Theory of Intelligence", author: "Jeff Hawkins", category: "Divulgación científica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1609237769l/54503521.jpg", status: "read", rating: 5, description: "Proposes that the neocortex builds intelligence by running thousands of complementary models of the world in parallel, each anchored to a reference frame. Argues that this architecture, once understood, will reshape artificial intelligence and explains why current deep-learning models still fall short of brains.", descriptionAi: true, owned: false },
    { title: "The Unthinkable: Who Survives When Disaster Strikes—and Why", author: "Amanda Ripley", category: "Psicología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1320430266l/2706211.jpg", status: "read", rating: 5, description: "Investigative account of how human beings actually behave when buildings collapse, ships sink, planes burn or hostages are taken. The book identifies the three-stage response —denial, deliberation, decisive moment— and finds, surprisingly often, that the difference between survivors and victims is rehearsal, leadership and a few seconds of clear thinking.", descriptionAi: true, owned: false },
    { title: "The WEIRDest People in the World: How the West Became Psychologically Peculiar and Particularly Prosperous", author: "Joseph Henrich", category: "", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1582603169l/51710349.jpg", status: "read", rating: 3, description: "Argues that Western, Educated, Industrialized, Rich, Democratic populations are psychological outliers —more individualistic, analytical, trust-extending and guilt-prone than every other population studied. Traces the surprising medieval origins of those traits in the Catholic Church's prohibitions on cousin marriage and family corporations.", descriptionAi: true, owned: false },
    { title: "Doing Good Better: How Effective Altruism Can Help You Make a Difference", author: "William MacAskill", category: "Filosofía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1414351487l/23398748.jpg", status: "read", rating: 5, description: "Introduces effective altruism. The argument is that, given immense suffering and limited resources, individuals are morally obligated to use evidence and cost-effectiveness when deciding where to donate, work and volunteer. Discusses career choices, charity evaluation and the moral pitfalls of well-meaning but ineffective giving.", descriptionAi: true, owned: false },
    { title: "Confronting Climate Gridlock: How Diplomacy, Technology, and Policy Can Unlock a Clean Energy Future", author: "Daniel S. Cohan", category: "Desarrollo y sostenibilidad", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1642217288l/58616824.jpg", status: "read", rating: 5, description: "Argues that breaking the climate impasse requires simultaneously pushing diplomacy, technological deployment and smart industrial policy on three fronts. Atmospheric science is married to political analysis to map the bottlenecks —from grid permits to international finance— that have to be cleared in the next decade.", descriptionAi: true, owned: false },
    { title: "Hurricane Lizards and Plastic Squid: The Fraught and Fascinating Biology of Climate Change", author: "Thor Hanson", category: "Divulgación científica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1630955309l/56643993.jpg", status: "read", rating: 5, description: "Travels around the world to document how individual species respond to a rapidly warming planet: lizards developing larger toepads to grip in hurricanes, squid switching to plastic ingestion, plants flowering earlier each year. Both alarming and weirdly hopeful natural history.", descriptionAi: true, owned: false },
    { title: "The Folly of Fools: The Logic of Deceit and Self-Deception in Human Life", author: "Robert Trivers", category: "Psicología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1320861437l/13033022.jpg", status: "read", rating: 5, description: "Comprehensive evolutionary argument that self-deception evolved precisely because it makes interpersonal deceit more effective. Surveys the strategy in animal signaling, courtship, politics, religion and war, and asks what humans would look like if they took the pervasiveness of their own self-flattery seriously.", descriptionAi: true, owned: false },
    { title: "Calling Bullshit: The Art of Skepticism in a Data-Driven World", author: "Carl T. Bergstrom", category: "Divulgación científica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1592246867l/48889983.jpg", status: "read", rating: 4, description: "Practical course in spotting statistical and visual nonsense. Covers misleading axes, selection effects, p-hacking, dubious base rates, viral misinformation and machine-learning hype. Each chapter ends with case studies drawn from popular media and clear rules of thumb for the data-overloaded reader.", descriptionAi: true, owned: false },
    { title: "The Nature of Plants: An Introduction to How Plants Work", author: "Craig N Huegel", category: "Biología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1548823464l/41543512.jpg", status: "read", rating: 4, description: "Accessible introduction to plant structure, physiology and ecology, aimed at gardeners and naturalists. Covers photosynthesis, water transport, mineral nutrition, reproduction and adaptations to extreme environments, with abundant illustrations and minimal jargon.", descriptionAi: true, owned: false },
    { title: "Return to Reason: The Science of Thought", author: "Scientific American", category: "Divulgación científica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1536108019l/41714569.jpg", status: "read", rating: 4, description: "Scientific American special collection of essays on rationality, judgment, memory and bias —and on what the cognitive sciences are doing to improve everyday reasoning. Useful as a primer for readers who want a quick survey of the field without committing to a textbook.", descriptionAi: true, owned: false },
    { title: "Chaos: Making a New Science", author: "James Gleick", category: "Divulgación científica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1327941595l/64582.jpg", status: "read", rating: 4, description: "Narrative history of the discovery of chaos theory in the 1960s and 1970s, when meteorologists, physicists and biologists noticed that simple nonlinear equations could produce wildly unpredictable behavior. Profiles the strange-attractor pioneers and explains the math through butterfly wings, dripping faucets and irregular heartbeats.", descriptionAi: true, owned: false },
    { title: "The Science of Storytelling", author: "Will Storr", category: "Lingüística", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1544377518l/43183121.jpg", status: "read", rating: 5, description: "Blends evolutionary psychology, neuroscience and screenwriting craft to explain why stories grip us and how writers can engineer that grip on purpose. Argues that all powerful stories involve a flawed protagonist forced into change and provides a clear toolkit for building one.", descriptionAi: true, owned: false },
    { title: "Honeybee Democracy", author: "Thomas D. Seeley", category: "Divulgación científica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1348651493l/8705048.jpg", status: "read", rating: 5, description: "Decades of field research on the swarming behavior of honeybees show that a colony's decision about where to nest is reached by an open, decentralized, peer-reviewed process that resembles the best practices of human democracies. Each chapter is a small parable for organizational design and collective intelligence.", descriptionAi: true, owned: false },
    { title: "Educated", author: "Tara Westover", category: "Memorias", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1774287363l/35133922.jpg", status: "read", rating: 5, description: "Memoir of growing up the youngest of seven children in a survivalist Mormon family in rural Idaho with no formal schooling, no birth certificate and a father convinced the end was near. The narrator teaches herself enough to pass entrance exams, ends up at Cambridge and Harvard, and pays the family cost of her own education. A modern classic.", descriptionAi: true, owned: false },
    { title: "The Book of Humans: A Brief History of Culture, Sex, War and the Evolution of Us", author: "Adam Rutherford", category: "Divulgación científica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1537251428l/39939050.jpg", status: "read", rating: 4, description: "Surveys the behaviors that humans share with other animals —tool use, war, sex, deception, art, language— to argue that we are at once less and more exceptional than we tend to think. Brings recent genetics and archaeology to bear on perennial questions of who we are.", descriptionAi: true, owned: false },
    { title: "The Value of Everything: Making and Taking in the Global Economy", author: "Mariana Mazzucato", category: "Economía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1458793853l/29502362.jpg", status: "read", rating: 4, description: "Distinguishes between activities that create real value and those that merely extract it, and argues that modern accounting and political language have confused us about which firms are doing which. Builds the case for a more discerning industrial policy that supports value creation and constrains value extraction.", descriptionAi: true, owned: false },
    { title: "The Evolution Of Desire: Strategies of Human Mating", author: "David M. Buss", category: "Psicología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1348779994l/27491.jpg", status: "read", rating: 4, description: "Foundational evolutionary-psychology study of human mating strategies built on a survey of over ten thousand people across thirty-seven cultures. Argues that women and men face different reproductive constraints and that this asymmetry shapes courtship, jealousy and the strategies of casual versus long-term mating.", descriptionAi: true, owned: false },
    { title: "The Enigma of Reason", author: "Hugo Mercier", category: "Psicología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1488567927l/32336635.jpg", status: "read", rating: 5, description: "Argues that human reasoning evolved not to find truth in private deliberation but to win arguments and to justify oneself in social settings. The puzzling biases that show up in psychology experiments make perfect sense in this interactionist view of reason. A bold reframing of cognitive science.", descriptionAi: true, owned: false },
    { title: "Remember: The Science of Memory and the Art of Forgetting", author: "Lisa Genova", category: "Divulgación científica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1598831596l/54895704.jpg", status: "read", rating: 5, description: "Explains why we forget —and why we should not be alarmed by most of it— alongside lifestyle measures that keep memory robust: sleep, exercise, social engagement, novelty. Covers Alzheimer's, anesthesia and the difference between misplacing keys and disease.", descriptionAi: true, owned: false },
    { title: "Atomic Habits: An Easy & Proven Way to Build Good Habits & Break Bad Ones", author: "James Clear", category: "Autoayuda", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1655988385l/40121378.jpg", status: "read", rating: 5, description: "Practical framework for building habits through four simple laws —make it obvious, attractive, easy and satisfying— and breaking bad ones by inverting them. Each principle is backed by anecdotes from athletes, business leaders and behavioral scientists, with concrete templates anyone can apply that same evening.", descriptionAi: true, owned: false },
    { title: "The Storytelling Animal: How Stories Make Us Human", author: "Jonathan Gottschall", category: "Psicología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1344670945l/12743473.jpg", status: "read", rating: 4, description: "Draws on psychology, evolution and literary scholarship to argue that storytelling is a core adaptation that builds shared minds and social glue. Surveys evidence from children's pretend play to nightly dreams to political campaigns, and asks why a species so practical spends so much time inhabiting fictions.", descriptionAi: true, owned: false },
    { title: "Give and Take: A Revolutionary Approach to Success", author: "Adam M. Grant", category: "Negocios", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1356136579l/16158498.jpg", status: "read", rating: 4, description: "Argues that the most successful people in many fields are not takers or matchers but givers, and that the apparent exceptions —burned-out, exploited givers— follow predictable patterns that can be redesigned. A research-backed defense of generosity as a long-term strategy at work.", descriptionAi: true, owned: false },
    { title: "Entangled Life: How Fungi Make Our Worlds, Change Our Minds & Shape Our Futures", author: "Merlin Sheldrake", category: "Divulgación científica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1575341220l/52668915.jpg", status: "read", rating: 5, description: "Tour of the fungal kingdom: mycelial networks that connect forests, lichens that survive on Antarctic rocks, magic mushrooms that may have reshaped human consciousness, yeasts that ferment bread and beer. A book that turns the soil under your feet into a barely visible city.", descriptionAi: true, owned: false },
    { title: "Speaking Peace: Connecting with Others Through Non-Violent Communication", author: "Marshall B. Rosenberg", category: "Psicología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1347415591l/560818.jpg", status: "read", rating: 5, description: "Audiobook companion to the Nonviolent Communication practice: how to translate observations, feelings, needs and requests into language that avoids reactivity and blame. Includes role-played dialogues and exercises for use in couples, classrooms and conflict mediation.", descriptionAi: true, owned: false },
    { title: "The Fires of Heaven", author: "Robert Jordan", category: "Fantasía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1327866286l/13895.jpg", status: "read", rating: 5, description: "Fifth volume of the Wheel of Time. Rand al'Thor leaves the Stone of Tear and embarks on a desperate trek across the Aiel Waste while Nynaeve and Elayne pursue the Black Ajah through circus tents and gleeman caravans. The series widens its political map and the Forsaken close in.", descriptionAi: true, owned: false },
    { title: "The Shadow Rising", author: "Robert Jordan", category: "Fantasía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1638239837l/9539.jpg", status: "read", rating: 5, description: "Fourth volume of the Wheel of Time. Rand visits the Aiel Waste and learns the secret history of the people he is destined to lead. In Tear, Perrin returns to the Two Rivers to face Whitecloaks and Trollocs while Min and Egwene's storylines take new shapes. The most pivotal book of the early series.", descriptionAi: true, owned: false },
    { title: "Mastery", author: "Robert Greene", category: "Autoayuda", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1348274726l/13589182.jpg", status: "read", rating: 5, description: "Distills decades of research on how exceptional achievers —Mozart, Darwin, da Vinci, Coltrane— actually became masters. The argument is that mastery is a lengthy apprenticeship to reality, not a flash of genius, and the book lays out the stages and the temptations that derail most people halfway through.", descriptionAi: true, owned: false },
    { title: "Friends: Understanding the Power of our Most Important Relationships", author: "Robin I.M. Dunbar", category: "Psicología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1611983671l/56883977.jpg", status: "read", rating: 4, description: "Synthesizes decades of research on the size, structure and biology of friendship circles, including the famous Dunbar number. Explores why we have inner circles, why religion and sport bond strangers and why isolation kills as surely as smoking does.", descriptionAi: true, owned: false },
    { title: "HBR's 10 Must Reads on Strategy", author: "Michael E. Porter", category: "Negocios", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1344703931l/9612515.jpg", status: "read", rating: 4, description: "Anthology of canonical Harvard Business Review essays on strategy —Porter on five forces, Kim and Mauborgne on blue oceans, Christensen on disruption, Hamel and Prahalad on core competencies— plus newer pieces on execution. A starter pack for anyone responsible for the strategic direction of a team.", descriptionAi: true, owned: false },
    { title: "Proust and the Squid: The Story and Science of the Reading Brain", author: "Maryanne Wolf", category: "Divulgación científica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1338486201l/289751.jpg", status: "read", rating: 5, description: "Traces the cultural history and neural basis of reading, from clay tablets in Sumer to the dyslexic Boston elementary schools where the science of reading is now being applied. Warns that the digital reading habit may be quietly rewiring the brain away from deep concentration.", descriptionAi: true, owned: false },
    { title: "The Drunkard's Walk: How Randomness Rules Our Lives", author: "Leonard Mlodinow", category: "", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1320392907l/2272880.jpg", status: "read", rating: 4, description: "Popular history of probability theory and a guide to how the mathematics of randomness explains streaks in sports, success in show business, results in science and reversals of fortune in personal life. Mixes biography, anecdote and elegant explanation.", descriptionAi: true, owned: false },
    { title: "Behave: The Biology of Humans at Our Best and Worst", author: "Robert M. Sapolsky", category: "Divulgación científica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1517732866l/31170723.jpg", status: "read", rating: 5, description: "Comprehensive synthesis of the biological factors behind human behavior, written across timescales: a second, a minute, hours, days, years and millennia before any action. Each layer —neurons, hormones, childhood, evolution— contributes to whether someone pulls a trigger, gives a speech or kisses a stranger.", descriptionAi: true, owned: false },
    { title: "Will", author: "Will  Smith", category: "Biografía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1624126289l/58375739.jpg", status: "read", rating: 5, description: "Memoir written with a popular self-help collaborator: a difficult West Philadelphia childhood, the rise of The Fresh Prince, blockbuster fame, marriage, public infidelity, the Oscar slap and a long reckoning with what fame and ambition do to a person. Unusually candid for a celebrity book.", descriptionAi: true, owned: false },
    { title: "Humankind: A Hopeful History", author: "Rutger Bregman", category: "Historia", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1577251406l/52879286.jpg", status: "read", rating: 5, description: "Revisits famous experiments in cruelty and obedience —Stanford Prison, Milgram, Lord of the Flies— and finds them flawed or fabricated. The argument is that humans are, by default, decent and that institutions should be redesigned with that assumption rather than with the Hobbesian one.", descriptionAi: true, owned: false },
    { title: "The Dragon Reborn", author: "Robert Jordan", category: "Fantasía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1659905781l/34897.jpg", status: "read", rating: 5, description: "Third volume of the Wheel of Time. Rand finally claims the title of the Dragon Reborn and goes to recover the sword Callandor in the Stone of Tear, while the series fans out into a sprawling cast of characters and political factions.", descriptionAi: true, owned: false },
    { title: "The Design of Everyday Things", author: "Donald A. Norman", category: "Arte", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1442460745l/840.jpg", status: "read", rating: 5, description: "Classic of user-centered design. Explains why doors push when they should pull, why stovetop controls are so often misaligned and what good affordances, mappings and feedback look like in physical and digital objects. The vocabulary it introduced is now standard in every UX team.", descriptionAi: true, owned: false },
    { title: "The Psychology of Money: Timeless Lessons on Wealth, Greed, and Happiness", author: "Morgan Housel", category: "Negocios", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1581527774l/41881472.jpg", status: "read", rating: 5, description: "Argues that doing well with money has less to do with smarts than with behavior. Twenty short essays cover compounding, ego, the role of luck, the importance of room for error and the underrated value of just leaving the portfolio alone for decades. A bedside-table classic of personal finance.", descriptionAi: true, owned: false },
    { title: "A Crack in Creation: Gene Editing and the Unthinkable Power to Control Evolution", author: "Jennifer A. Doudna", category: "Divulgación científica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1474820838l/30971755.jpg", status: "read", rating: 4, description: "Memoir and primer on CRISPR-Cas9, written by one of the inventors of the technology. The first half explains how the bacterial immune system was hijacked into a precise genome editor; the second half wrestles with the ethical implications, from sickle cell to designer babies.", descriptionAi: true, owned: false },
    { title: "The Great Hunt", author: "Robert Jordan", category: "Fantasía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1659905799l/233649.jpg", status: "read", rating: 5, description: "Second volume of the Wheel of Time. Rand pursues a stolen horn of legend across the Aiel Waste while Egwene and Nynaeve enter the White Tower in Tar Valon. The cosmology of the series is widened and the first taste of trans-world travel appears.", descriptionAi: true, owned: false },
    { title: "Numbers Don't Lie: 71 Things You Need to Know About the World", author: "Vaclav Smil", category: "Divulgación científica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1666542864l/50705179.jpg", status: "read", rating: 5, description: "Seventy-one short data essays on energy, food, transport, environment and human well-being, written as antidotes to lazy claims about the modern world. Each piece is a few crisp pages of numbers; together they amount to a robust intuition about how the planet actually works.", descriptionAi: true, owned: false },
    { title: "The Eye of the World", author: "Robert Jordan", category: "Fantasía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1659905815l/228665.jpg", status: "read", rating: 5, description: "First volume of the Wheel of Time. Three young men flee their idyllic village after a Trolloc raid and discover that one of them is the Dragon Reborn, fated to fight and break the world a second time. The opening of an enormous fantasy series that defined the genre for a generation.", descriptionAi: true, owned: false },
    { title: "Evolution for Everyone: How Darwin's Theory Can Change the Way We Think About Our Lives", author: "David Sloan Wilson", category: "", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1320436409l/159062.jpg", status: "read", rating: 5, description: "Argues that evolutionary thinking belongs in every classroom and shows what it can offer disciplines as different as economics, religion, parenting and gossip. Conversational rather than academic, the book invites the reader to do simple experiments with their own family and community.", descriptionAi: true, owned: false },
    { title: "Models: Attract Women Through Honesty", author: "Mark Manson", category: "Autoayuda", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1375568311l/12633800.jpg", status: "read", rating: 5, description: "Counter-intuitive dating book that drops manipulation tactics in favor of vulnerability, self-development and emotional honesty. Argues that attractiveness is primarily a matter of who you actually are rather than how you stage yourself, and that learning to be rejected gracefully is the central skill.", descriptionAi: true, owned: false },
    { title: "Good Economics for Hard Times: Better Answers to Our Biggest Problems", author: "Abhijit V. Banerjee", category: "Economía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1562348201l/51014619.jpg", status: "read", rating: 5, description: "Surveys the empirical evidence on the central economic policy debates of our time —immigration, trade, growth, climate, inequality, automation— and finds that the most confident claims on left and right are usually unsupported. Nobel-quality humility about what economists actually know.", descriptionAi: true, owned: false },
    { title: "The Truth About Trust: How It Determines Success in Life, Love, Learning, and More", author: "David  DeSteno", category: "Psicología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1374638765l/18114085.jpg", status: "read", rating: 3, description: "Synthesizes psychological research on the cognitive and emotional machinery behind trust: how we decide whom to believe, why first impressions matter and matter again, the role of body language and gesture, and how trust can be designed in workplaces and relationships.", descriptionAi: true, owned: false },
    { title: "Ego Is the Enemy", author: "Ryan Holiday", category: "Autoayuda", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1459114043l/27036528.jpg", status: "read", rating: 4, description: "Companion to The Obstacle Is the Way. Through historical case studies —Howard Hughes, Jackie Robinson, Genghis Khan— argues that ego sabotages ambition, success and recovery, and that humility is the operating system of those who do the actual work. Stoic ethics applied to modern careers.", descriptionAi: true, owned: false },
    { title: "Conformity: The Power of Social Influences", author: "Cass R. Sunstein", category: "Psicología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1557572989l/42832291.jpg", status: "read", rating: 4, description: "Synthesizes social-psychology research on how groups generate conformity, polarization and group-think, and draws institutional lessons for committees, juries and democracies. Argues that good institutions deliberately design for productive dissent rather than relying on it to emerge.", descriptionAi: true, owned: false },
    { title: "What We Owe Each Other: A New Social Contract for a Better Society", author: "Minouche Shafik", category: "Economía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1613414340l/56213211.jpg", status: "read", rating: 4, description: "Proposes a renewed social contract that strengthens collective insurance from cradle to grave —childcare, healthcare, education, retirement, transitions across the lifecycle— while preserving individual responsibility and the political legitimacy of fiscal trade-offs.", descriptionAi: true, owned: false },
    { title: "Collapse: How Societies Choose to Fail or Succeed", author: "Jared Diamond", category: "Historia", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1441419222l/475.jpg", status: "read", rating: 4, description: "Comparative study of how past and present societies have managed —or failed to manage— the combined pressures of environmental degradation, climate change, hostile neighbors and friendly trade. Case studies range from Easter Island and the Norse Greenlanders to modern Rwanda, Haiti and Australia.", descriptionAi: true, owned: false },
    { title: "Blockchain Chicken Farm: And Other Stories of Tech in China's Countryside", author: "Xiaowei Wang", category: "", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1585632441l/50403472.jpg", status: "read", rating: 5, description: "Essays from rural China reporting on the encounter between advanced technology —blockchain-tracked chickens, AI-managed pig farms, livestreamed villages— and the lives of farmers and migrants. Pushes back against the urban-centric narrative of Chinese modernization with on-the-ground complexity.", descriptionAi: true, owned: false },
    { title: "The Social Instinct: How Cooperation Shaped the World", author: "Nichola Raihani", category: "Divulgación científica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1621844547l/56269229.jpg", status: "read", rating: 4, description: "Evolutionary biologist's account of why cooperation evolves, where it breaks down and what the answers imply for everything from fish-cleaning stations to climate negotiations. Draws connections between studies of cooperation in animals and the design of human institutions.", descriptionAi: true, owned: false },
    { title: "Ingredients: The Strange Chemistry of What We Put in Us and on Us", author: "George Zaidan", category: "Divulgación científica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1574355997l/48822623.jpg", status: "read", rating: 5, description: "Untangles food labels, cosmetics and the everyday chemistry behind processed products. Pushes back against both blanket panic and blanket reassurance about additives, preservatives and synthetic materials. Witty, opinionated and grounded in actual chemistry.", descriptionAi: true, owned: false },
    { title: "The Demon-Haunted World: Science as a Candle in the Dark", author: "Carl Sagan", category: "Divulgación científica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1553691804l/17349.jpg", status: "read", rating: 5, description: "Essay collection in defense of scientific thinking against the constant pressure of pseudoscience, religious fundamentalism, superstition and political mendacity. Includes the famous «baloney detection kit», a checklist of intellectual tools any citizen of a democracy should carry.", descriptionAi: true, owned: false },
    { title: "Everybody Lies: Big Data, New Data, and What the Internet Can Tell Us About Who We Really Are", author: "Seth Stephens-Davidowitz", category: "Divulgación científica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1489069766l/28512671.jpg", status: "read", rating: 4, description: "Uses anonymous Google search data, porn site queries and other digital traces to argue that humans confess to keyboards what they would never tell each other. Each chapter explores a hidden truth —racism, sex, child abuse, professional advice— revealed when surveys are replaced by digital footprints.", descriptionAi: true, owned: false },
    { title: "The Upside of Irrationality: The Unexpected Benefits of Defying Logic at Work and at Home", author: "Dan Ariely", category: "Psicología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1268511997l/7815744.jpg", status: "read", rating: 4, description: "Follow-up to Predictably Irrational. Experiments show how emotions, motivation and adaptation distort and sometimes enrich our decisions at work and at home. Topics include revenge, paying for sex, online dating, getting used to good things and the strange way we accept big setbacks.", descriptionAi: true, owned: false },
    { title: "Noise: A Flaw in Human Judgment", author: "Daniel Kahneman", category: "Psicología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1617709587l/55339408.jpg", status: "read", rating: 5, description: "Identifies «noise» —random variability in expert judgment, from doctors to judges to forecasters— as a costly twin of bias, and proposes techniques to reduce it. Even when bias is absent, noise produces unfair and inefficient outcomes; algorithmic decision-support and structured procedures can dramatically reduce it.", descriptionAi: true, owned: false },
    { title: "Complexity: The Emerging Science at the Edge of Order and Chaos", author: "M. Mitchell Waldrop", category: "Divulgación científica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1405259833l/337123.jpg", status: "read", rating: 5, description: "Narrative history of the Santa Fe Institute and the people who built the field of complexity science: physicists, biologists, economists, computer scientists who saw the same kinds of patterns in their data and decided to talk to each other. A foundational popular account of a still-young discipline.", descriptionAi: true, owned: false },
    { title: "Purple Cow: Transform Your Business by Being Remarkable", author: "Seth Godin", category: "Negocios", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1309203098l/641604.jpg", status: "read", rating: 4, description: "Argues that the only marketing that works in a saturated economy is to build something so unusual that it advertises itself —a purple cow in a field of brown ones. Filled with short, punchy examples of small businesses, products and services that quietly conquered niches by being remarkable.", descriptionAi: true, owned: false },
    { title: "Science Fictions: How Fraud, Bias, Incompetence, and Hype Undermine the Search for Truth", author: "Stuart Ritchie", category: "Divulgación científica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1580203662l/52079565.jpg", status: "read", rating: 5, description: "Critical survey of the replication crisis in psychology and biomedicine, the perverse incentives that produce p-hacking and salami slicing, and the structural reforms —preregistration, open data, post-publication peer review— that are starting to repair the system.", descriptionAi: true, owned: false },
    { title: "The Sports Gene: Inside the Science of Extraordinary Athletic Performance", author: "David   Epstein", category: "Divulgación científica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1378677673l/16171221.jpg", status: "read", rating: 4, description: "Investigates the genetic and developmental factors behind elite athletic performance. Argues that the «10 000-hour rule» is misleading: practice matters enormously, but it interacts with body type, neurology and trainability that vary across individuals and populations.", descriptionAi: true, owned: false },
    { title: "SPIN Selling: Situation Problem Implication Need-payoff", author: "Neil Rackham", category: "Negocios", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1433591836l/833015.jpg", status: "read", rating: 3, description: "Empirical framework for high-value consultative selling: ask Situation, Problem, Implication and Need-payoff questions to lead the buyer to articulate their own need. The conclusions come from observation of thousands of real sales calls and remain the empirical basis for most modern B2B sales training.", descriptionAi: true, owned: false },
    { title: "The Ride of a Lifetime: Lessons Learned from 15 Years as CEO of the Walt Disney Company", author: "Robert Iger", category: "Negocios", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1556036622l/44525305.jpg", status: "read", rating: 5, description: "Memoir of one of the most successful turnaround CEOs in entertainment. Chronicles the acquisitions of Pixar, Marvel, Lucasfilm and Fox, the launch of Disney+, and the management principles —optimism, curiosity, courage, fairness— that the author believes made them possible.", descriptionAi: true, owned: false },
    { title: "The New Corporation: How \"Good\" Corporations Are Bad for Democracy", author: "Joel Bakan", category: "Política", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1590444239l/52487931.jpg", status: "read", rating: 4, description: "Argues that corporate social responsibility, ESG investing and sustainability reporting have become a sophisticated branding strategy that masks the same old extractive behavior, while crowding out the political space for real accountability. A direct challenge to «conscious capitalism».", descriptionAi: true, owned: false },
    { title: "Green Swans: The Coming Boom In Regenerative Capitalism", author: "John Elkington", category: "Desarrollo y sostenibilidad", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1585943210l/52919387.jpg", status: "read", rating: 5, description: "Proposes «green swans» as positive exponential shifts that, with the right design, could turn industries regenerative within a generation —the opposite of Taleb's destructive black swans. Surveys the technologies, business models and policy levers that would be required.", descriptionAi: true, owned: false },
    { title: "The Structure of Scientific Revolutions", author: "Thomas S. Kuhn", category: "Divulgación científica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1396422530l/61539.jpg", status: "read", rating: 4, description: "Introduces the vocabulary of «paradigm shifts» to the philosophy of science. Argues that science usually proceeds by «normal science» within an accepted paradigm and only occasionally undergoes the revolutions that replace one paradigm with another. A book that changed how scientists, historians and policymakers think about science.", descriptionAi: true, owned: false },
    { title: "Looking for Alaska", author: "John  Green", category: "Novela juvenil", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1652042180l/99561.jpg", status: "read", rating: 5, description: "Young-adult debut. Miles, a Floridian obsessed with last words, enrolls at a boarding school in Alabama where he falls in with a tight group of friends and an unforgettable girl called Alaska. The novel is divided into «Before» and «After» a tragedy that hangs over the second half. Modern teen literature classic.", descriptionAi: true, owned: false },
    { title: "Business Model Generation", author: "Alexander Osterwalder", category: "Negocios", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1384676138l/7723797.jpg", status: "read", rating: 4, description: "Illustrated workbook for designing, testing and pivoting business models using the Business Model Canvas. Co-created by a global community of practitioners, it has become the de facto starting toolkit for entrepreneurs, startup mentors and corporate innovation teams worldwide.", descriptionAi: true, owned: false },
    { title: "Ripper", author: "Isabel Allende", category: "Misterio", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1422871316l/18090150.jpg", status: "read", rating: 4, description: "Mystery novel set in present-day San Francisco. Amanda, a teenage member of an online role-playing game called Ripper, draws her detective stepfather into a string of grisly murders that may be connected to her own mother's disappearance and to a darker pattern stretching back decades. The plot weaves family secrets, esoteric clues and gamer culture into a procedural with the texture of a magical-realist family saga.", descriptionAi: true, owned: false },
    { title: "Freakonomics: A Rogue Economist Explores the Hidden Side of Everything", author: "Steven D. Levitt", category: "Economía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1550917827l/1202.jpg", status: "read", rating: 4, description: "Apply microeconomic tools to sumo wrestlers, drug dealers, real-estate agents and the falling crime rate. Each chapter answers a counter-intuitive question by following the incentives, and popularized a whole genre of pop-data writing that came after.", descriptionAi: true, owned: false },
    { title: "Peter Pan in Scarlet", author: "Geraldine McCaughrean", category: "Fantasía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1388340899l/34264.jpg", status: "read", description: "Authorized sequel to J. M. Barrie's classic. The Lost Boys, now grown men, find their old dreams of Neverland invading their adult lives and return to find the island in trouble, the captain transformed and Peter himself in danger of disappearing. A welcome epilogue with the tonal honesty of the original.", descriptionAi: true, owned: false },
    { title: "The Alchemist", author: "Paulo Coelho", category: "Novela clásica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1483412266l/865.jpg", status: "read", rating: 3, description: "Allegorical novella. Santiago, a young Andalusian shepherd, leaves his flock to follow a recurring dream of treasure at the Egyptian pyramids. The journey introduces him to gypsies, alchemists, an Englishman and a beloved at the oasis, and teaches him the «Personal Legend» —the unique calling each person is meant to follow.", descriptionAi: true, owned: false },
    { title: "Turtles All the Way Down", author: "John  Green", category: "Novela juvenil", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1503002776l/35504431.jpg", status: "read", rating: 4, description: "Aza, a sixteen-year-old struggling with severe OCD, gets pulled into the search for a missing billionaire by her best friend Daisy and the billionaire's son Davis. The novel is at once a mystery, a love story and one of the most honest fictional portraits of intrusive thoughts in young-adult literature.", descriptionAi: true, owned: false },
    { title: "The End of Power: From Boardrooms to Battlefields and Churches to States, Why Being In Charge Isn't What It Used to Be", author: "Moisés Naím", category: "", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1350395884l/16043519.jpg", status: "read", rating: 4, description: "Argues that power across politics, business, religion and the military is decaying: it is easier to acquire, harder to use and easier to lose than at any point in the past century. Surveys why micro-powers (insurgents, hedge funds, NGOs) keep upending macro-incumbents and what that means for governance.", descriptionAi: true, owned: false },
    { title: "Harry Potter and the Sorcerer's Stone", author: "J.K. Rowling", category: "", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1474154022l/3.jpg", status: "read", rating: 4, description: "First novel of the series. Orphan Harry, raised in misery by his aunt and uncle, discovers on his eleventh birthday that he is a wizard. At Hogwarts School of Witchcraft and Wizardry he makes lifelong friends, learns to fly a broomstick and confronts the dark wizard who killed his parents and survived only because of him.", descriptionAi: true, owned: false },
    { title: "Harry Potter and the Chamber of Secrets", author: "J.K. Rowling", category: "Fantasía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1474169725l/15881.jpg", status: "read", rating: 4, description: "Second year at Hogwarts. A mysterious entity is paralyzing Muggle-born students and writing threats on the castle walls. Harry, Ron and Hermione investigate, uncover a fifty-year-old crime and descend into the Chamber of Secrets where a basilisk —and the memory of a young Lord Voldemort— await.", descriptionAi: true, owned: false },
    { title: "Harry Potter and the Prisoner of Azkaban", author: "J.K. Rowling", category: "Fantasía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1630547330l/5.jpg", status: "read", rating: 5, description: "Third year. The supposed mass-murderer Sirius Black has escaped the wizard prison of Azkaban and Hogwarts is surrounded by soul-sucking Dementors. Harry meets a new Defense Against the Dark Arts teacher, learns the patronus charm and discovers the truth about the night his parents died.", descriptionAi: true, owned: false },
    { title: "Harry Potter and the Goblet of Fire", author: "J.K. Rowling", category: "Fantasía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1554006152l/6.jpg", status: "read", rating: 4, description: "Fourth year. Hogwarts hosts the Triwizard Tournament; Harry's name comes out of the goblet despite being underage and he must compete against older students from three schools. The book closes with the return of Lord Voldemort to a body and marks the tonal shift toward the darker second half of the series.", descriptionAi: true, owned: false },
    { title: "Harry Potter and the Order of the Phoenix", author: "J.K. Rowling", category: "Fantasía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1546910265l/2.jpg", status: "read", rating: 5, description: "Fifth year. The Ministry of Magic denies the return of Voldemort and installs a sadistic bureaucrat at Hogwarts. Harry, isolated and traumatized, forms a resistance group called Dumbledore's Army while a prophecy in the Department of Mysteries reshapes the war to come.", descriptionAi: true, owned: false },
    { title: "Harry Potter and the Half-Blood Prince", author: "J.K. Rowling", category: "Fantasía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1587697303l/1.jpg", status: "read", rating: 5, description: "Sixth year. Harry and Dumbledore use a Pensieve to investigate Voldemort's past, gathering memories that reveal how the Dark Lord split his soul into Horcruxes. Meanwhile Hogwarts feels the first weight of war and a beloved character meets a terrible fate on the Astronomy Tower.", descriptionAi: true, owned: false },
    { title: "Harry Potter and the Deathly Hallows", author: "J.K. Rowling", category: "Fantasía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1663805647l/136251.jpg", status: "read", rating: 5, description: "Seventh and final book. Harry, Ron and Hermione drop out of Hogwarts and travel across Britain hunting the remaining Horcruxes, hunted in turn by Snatchers and the reorganized Ministry. The last hundred pages take place at the Battle of Hogwarts and resolve every storyline begun in the previous six volumes.", descriptionAi: true, owned: false },
    { title: "Guns, Germs, and Steel: The Fates of Human Societies", author: "Jared Diamond", category: "Historia", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1453215833l/1842.jpg", status: "read", rating: 5, description: "Asks why some societies came to dominate others over the last thirteen thousand years. Argues that the answer is geographic and biological, not racial or cultural: the lucky distribution of domesticable plants and animals along the Eurasian east-west axis gave farmers there a long head start.", descriptionAi: true, owned: false },
    { title: "Scrum: The Art of Doing Twice the Work in Half the Time", author: "Jeff Sutherland", category: "Negocios", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1393221649l/19288230.jpg", status: "read", rating: 4, description: "Practical manifesto for the Scrum framework, drawn from its co-founder's experience helping teams in software, manufacturing and even the FBI cut development time in half. Covers sprints, backlogs, retrospectives and the cultural ground that has to be prepared for any of it to work.", descriptionAi: true, owned: false },
    { title: "Range: Why Generalists Triumph in a Specialized World", author: "David   Epstein", category: "Negocios", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1550048292l/41795733.jpg", status: "read", rating: 5, description: "Argues that early specialization is overrated. In «wicked» domains where feedback is slow and rules change, broad sampling, late commitment and analogical thinking produce more durable expertise than narrow head-starts. Case studies range from tennis prodigies to NASA disasters.", descriptionAi: true, owned: false },
    { title: "Superforecasting: The Art and Science of Prediction", author: "Philip E. Tetlock", category: "Negocios", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1435684424l/23995360.jpg", status: "read", rating: 4, description: "Reports on a multi-year tournament in which volunteer forecasters consistently outperformed intelligence-agency analysts on geopolitical questions. Distills the techniques the best forecasters used —probabilistic thinking, fox-style breadth, post-mortems on errors— into a practical curriculum.", descriptionAi: true, owned: false },
    { title: "Zero to One: Notes on Startups, or How to Build the Future", author: "Peter Thiel", category: "Negocios", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1630663027l/18050143.jpg", status: "read", rating: 5, description: "Compressed manifesto for ambitious entrepreneurs. The argument is that real value comes from creating something new (zero to one) rather than copying what works (one to n), and that monopolies built on a genuine secret are the engine of progress. Required reading in Silicon Valley.", descriptionAi: true, owned: false },
    { title: "The Algebra of Happiness: Notes on the Pursuit of Success, Love, and Meaning", author: "Scott Galloway", category: "Autoayuda", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1553767026l/42872963.jpg", status: "read", rating: 4, description: "Short, blunt and emotionally honest essays distilled from a popular NYU business-school lecture on career, money, relationships, parenting and grief. The chapters resemble letters to a younger self and to one's children at once.", descriptionAi: true, owned: false },
    { title: "Trust Me, I'm Lying: Confessions of a Media Manipulator", author: "Ryan Holiday", category: "", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1340124369l/13542853.jpg", status: "read", rating: 4, description: "Memoir-cum-exposé of the contemporary online media ecosystem, written by a former marketer who built campaigns for clients by manipulating blogs, aggregators and news outlets. Lays out the incentive structure that makes contemporary journalism so easy to spin.", descriptionAi: true, owned: false },
    { title: "Northern Lights", author: "Philip Pullman", category: "Fantasía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1327235223l/70947.jpg", status: "read", rating: 4, description: "First book of His Dark Materials. Lyra Belacqua, raised by Oxford scholars, sets out for the Arctic to rescue kidnapped children and discovers that her own daemon, polar bears in armor and the strange substance called Dust are all wrapped up in a war about the Authority. Modern children's literature at its most philosophically ambitious.", descriptionAi: true, owned: false },
    { title: "The Subtle Knife", author: "Philip Pullman", category: "Fantasía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1535965085l/41637836.jpg", status: "read", rating: 4, description: "Second book of His Dark Materials. Lyra crosses into a parallel world and meets Will Parry, a boy from our own world looking for his lost father. Together they find the subtle knife, which can cut between universes, and discover that what is happening is much bigger than any one world's war.", descriptionAi: true, owned: false },
    { title: "Political Risk: How Businesses and Organizations Can Anticipate Global Insecurity", author: "Condoleezza Rice", category: "Negocios", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1646318146l/36589095.jpg", status: "read", rating: 5, description: "Describes how shifting geopolitics, social activism, supply-chain fragility and reputational pressure affect firms, NGOs and even families, and walks through a framework for understanding, communicating and managing political risk. Includes detailed case studies from recent events.", descriptionAi: true, owned: false },
    { title: "How Not to Be Wrong: The Power of Mathematical Thinking", author: "Jordan Ellenberg", category: "Divulgación científica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1387726285l/18693884.jpg", status: "read", rating: 4, description: "Shows how mathematical reasoning illuminates everyday questions —lottery tickets, elections, slime molds, missing soldier statistics— without requiring formal mathematics from the reader. Each chapter is an invitation to think about a familiar topic with a slightly different mental tool.", descriptionAi: true, owned: false },
    { title: "The Creative Spark: How Imagination Made Humans Exceptional", author: "Agustín Fuentes", category: "Divulgación científica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1475528465l/31626670.jpg", status: "read", rating: 5, description: "Anthropological argument that human creativity is not a luxury but the central evolutionary advantage of the species: cooperation, language, art, technology and even violence are all expressions of an unusual imaginative range. Traces creativity from stone tools to gene editing.", descriptionAi: true, owned: false },
    { title: "Every Tool's a Hammer: Life Is What You Make It", author: "Adam Savage", category: "Biografía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1555856209l/43319933.jpg", status: "read", rating: 3, description: "Personal manifesto on making, building and tinkering, full of practical advice and stories from a long career building props for film and television. Covers list-keeping, deadlines, screwing up, sharing the work and the deep pleasure of putting your hands on physical material.", descriptionAi: true, owned: false },
    { title: "The Choice Factory: 25 behavioural biases that influence what we buy", author: "Richard Shotton", category: "Negocios", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1518390503l/38487327.jpg", status: "read", rating: 5, description: "Twenty-five behavioral biases —social proof, scarcity, framing, the pratfall effect, default options— explained with case studies from advertising and consumer experiments, and applied to the design of ads, packaging and pricing. A practical handbook for marketers who want evidence instead of vibes.", descriptionAi: true, owned: false },
    { title: "Alchemy: The Surprising Power of Ideas That Don't Make Sense", author: "Rory Sutherland", category: "", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1549539347l/26210508.jpg", status: "read", rating: 5, description: "Companion edition of Alchemy: a sustained case for psycho-logic over arithmetic in marketing, policy and design. Argues that the most powerful business and political ideas are usually irrational, counter-intuitive and untestable, and that the best decision-makers know it.", descriptionAi: true, owned: false },
    { title: "Pre-Suasion: A Revolutionary Way to Influence and Persuade", author: "Robert B. Cialdini", category: "Psicología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1468786982l/29238799.jpg", status: "read", rating: 4, description: "Argues that the moment before a message arrives often matters more than the message itself: priming, framing and the careful management of attention shape decisions that look fully free. Builds on decades of social-psychology experiments and offers ethical principles for using this knowledge responsibly.", descriptionAi: true, owned: false },
    { title: "Social Engineering", author: "Christopher Hadnagy", category: "Psicología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1349034191l/9068044.jpg", status: "read", rating: 4, description: "The bible of human-centered hacking. Catalogues the techniques —pretexting, elicitation, phishing, baiting, dumpster diving, tailgating— that attackers use to bypass technical defenses by manipulating people instead. Each technique comes with red-team examples and blue-team countermeasures.", descriptionAi: true, owned: false },
    { title: "Factfulness: Ten Reasons We're Wrong About the World – and Why Things Are Better Than You Think", author: "Hans Rosling", category: "", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1544963815l/34890015.jpg", status: "read", rating: 4, description: "Lists ten cognitive instincts —the gap instinct, the negativity instinct, the straight-line instinct, the fear instinct— that distort our view of global development, and offers data-driven antidotes for thinking like a fact-based optimist. Built on a lifetime teaching the world about itself.", descriptionAi: true, owned: false },
    { title: "The Honest Truth About Dishonesty: How We Lie to Everyone - Especially Ourselves", author: "Dan Ariely", category: "Psicología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1331070373l/13426114.jpg", status: "read", rating: 4, description: "Lab-experiment-driven exploration of when, how and why ordinary people cheat. The conclusion is that most dishonesty has little to do with cost-benefit analysis and a lot to do with self-image management. Includes specific policy and design ideas to reduce everyday fraud.", descriptionAi: true, owned: false },
    { title: "Understanding Michael Porter: The Essential Guide to Competition and Strategy", author: "Joan Magretta", category: "Negocios", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1334413319l/13263934.jpg", status: "read", rating: 5, description: "Concise summary of the core ideas of competitive strategy —five forces, generic strategies, value chain, positioning, trade-offs— written by a longtime collaborator. Strips the jargon and leaves the framework that has organized strategy teaching for forty years.", descriptionAi: true, owned: false },
    { title: "Post Corona: From Crisis to Opportunity", author: "Scott Galloway", category: "Negocios", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1600733675l/55333978.jpg", status: "read", rating: 4, description: "Charts the winners and losers of the COVID-19 economy and argues for policy and business strategies to use the dislocation as an opening for reform. Covers higher education, tech monopolies, the future of work and the social contract, with characteristic blunt provocations.", descriptionAi: true, owned: false },
    { title: "Traffic: Why We Drive the Way We Do and What It Says About Us", author: "Tom Vanderbilt", category: "Psicología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1320428955l/2776527.jpg", status: "read", rating: 4, description: "Engaging investigation of road behavior. Why merging at the last moment is more efficient, why eye contact reduces aggression, why complicated streets are safer than simple ones, what traffic patterns reveal about national character. Mixes psychology, engineering and field reporting.", descriptionAi: true, owned: false },
    { title: "Sapiens: A Brief History of Humankind", author: "Yuval Noah Harari", category: "", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1703329310l/23692271.jpg", status: "read", rating: 5, description: "Sweeping account of the last 70 000 years of human history organized around three revolutions —cognitive, agricultural and scientific. Argues that the human capacity to invent and believe in shared fictions —religions, nations, money, corporations— is what allowed a small African primate to become the planet's apex shaper.", descriptionAi: true, owned: false },
    { title: "Homo Deus: A History of Tomorrow", author: "Yuval Noah Harari", category: "Historia", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1468760805l/31138556.jpg", status: "read", rating: 5, description: "Extends the project of Sapiens into the future, asking what becomes of humanism, freedom and meaning in an age of biotech, algorithms and dataism. Argues that humans may soon split into augmented elites and a «useless class», and that the new religion of data could replace the old religions of God and Man.", descriptionAi: true, owned: false },
    { title: "21 Lessons for the 21st Century", author: "Yuval Noah Harari", category: "Historia", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1564577305l/38820046.jpg", status: "read", rating: 5, description: "Twenty-one short essays that bring the same big-picture lens to the present: liberal democracy, immigration, terrorism, fake news, education, meditation, work, war. Each chapter is a self-contained meditation on a single contemporary anxiety.", descriptionAi: true, owned: false },
    { title: "This is Marketing: You Can't Be Seen Until You Learn To See", author: "Seth Godin", category: "", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1529247040l/40549476.jpg", status: "read", rating: 5, description: "Compact statement of a marketing philosophy: serve the smallest viable audience, earn their trust through generous work, let the work spread by being worth talking about. A counter-cultural manifesto inside an industry built on interruption.", descriptionAi: true, owned: false },
    { title: "The Invisible Life of Addie LaRue", author: "V.E. Schwab", category: "Fantasía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1584633432l/50623864.jpg", status: "read", rating: 3, description: "On the eve of her arranged marriage in 1714, Adeline LaRue makes a bargain with a god of the dark to live for as long as she wants —at the price of being instantly forgotten by everyone she meets. Three hundred years later, in present-day New York, she walks into a bookstore and is finally remembered. A literary fantasy about memory, art and the cost of freedom.", descriptionAi: true, owned: false },
    { title: "The Amber Spyglass", author: "Philip Pullman", category: "Fantasía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1609381000l/5949392.jpg", status: "read", rating: 5, description: "Third and final book of His Dark Materials. Lyra and Will travel through worlds, including the land of the dead, to fight a war that will determine the fate of conscious life across the multiverse. The series closes on the most ambitious theological note in modern children's literature.", descriptionAi: true, owned: false },
    { title: "Fooled by Randomness: The Hidden Role of Chance in Life and in the Markets", author: "Nassim Nicholas Taleb", category: "Economía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1328339070l/8536015.jpg", status: "read", rating: 4, description: "Original Incerto book. A polemic against the confusion between skill and luck on Wall Street, in sports, in politics and in everyday narratives. Mixes anecdotes from a career as a trader with ancient philosophy and probability to defend a strict skepticism toward apparent success.", descriptionAi: true, owned: false },
    { title: "Fruticultura tropical", author: "José María Arias Rodríguez", category: "Agricultura", description: "Manual técnico sobre los principales frutales del trópico: variedades, requerimientos climáticos y edáficos, propagación, manejo del huerto, fertilización, riego, control de plagas y enfermedades, cosecha y postcosecha. Pensado para productores, técnicos y estudiantes de agronomía de regiones tropicales.", descriptionAi: true },
    { title: "Bacterias ácido lácticas: Fundamentos y aplicaciones", author: "Drider y Rivera", category: "Biología", description: "Tratado técnico sobre la taxonomía, fisiología, metabolismo y usos industriales de las bacterias ácido lácticas. Cubre su papel en la fermentación de productos lácteos, cárnicos y vegetales, en el desarrollo de probióticos y en la conservación de alimentos. Texto de referencia para microbiólogos de la industria alimentaria y para estudiantes universitarios del área.", descriptionAi: true },
    { title: "Más allá de las apariencias", author: "Raynald Pepin", category: "Filosofía", coverId: 12329266, description: "Ensayo que invita a mirar más allá de las superficies sociales y culturales para detectar las estructuras invisibles que organizan la vida cotidiana: instituciones, hábitos, expectativas y narrativas heredadas que damos por naturales. Una invitación a la sospecha bien entendida, en clave divulgativa y con ejemplos del mundo contemporáneo.", descriptionAi: true },
    { title: "El mango", author: "Yahia", category: "Agricultura", description: "Manual agronómico del cultivo del mango: variedades comerciales, requerimientos edafoclimáticos, propagación, manejo del huerto, fertilización, riego, control de plagas y enfermedades, cosecha y postcosecha. Pensado para productores tropicales que necesitan un texto técnico y a la vez práctico.", descriptionAi: true },
    { title: "Piratería: La invasión intelectual de Gutenberg a Gates", author: "Adrian Johns", category: "Historia", coverId: 14299638, description: "Reconstrucción de la larga historia del concepto de piratería intelectual desde los albores de la imprenta hasta el copyright digital. Recorre los conflictos por el control de la copia, los gremios de impresores, los litigios shakespearianos, las patentes industriales y las leyes contemporáneas de propiedad intelectual para mostrar que copiar y proteger han sido siempre caras de la misma moneda.", descriptionAi: true },
    { title: "Botánica de laboratorio", author: "Rita Yolanda Cavero y María Luisa López", category: "Biología", coverId: 14280546, description: "Cuaderno de prácticas para identificar, describir y dibujar tejidos y órganos vegetales. Ofrece guías taxonómicas, claves dicotómicas y técnicas microscópicas básicas para cursos universitarios de botánica general y sistemática, con ejemplos centrados en flora peninsular ibérica.", descriptionAi: true },
    { title: "El frijol silvestre: Síndrome de domesticación", author: "Cecilia Beatriz Peña Valdivia, J. Rogelio Aguirre R. y V. Baruch Arroyo Peña", category: "Agricultura", description: "Estudio detallado sobre los caracteres morfológicos, fisiológicos y genéticos que distinguen al frijol silvestre del cultivado, y sobre el proceso que llevó a Phaseolus vulgaris a convertirse en alimento básico mesoamericano. Recoge resultados de campo en México y revisa la literatura sobre domesticación de leguminosas.", descriptionAi: true },
    { title: "Los tres mosqueteros", author: "Alexandre Dumas", category: "Novela clásica", coverId: 12784165, description: "Folletín ambientado en la Francia de Luis XIII. D'Artagnan, un joven gascón ambicioso, llega a París, se gana a Athos, Porthos y Aramis en tres duelos sucesivos y se enrola en la guardia del rey. Juntos defienden el honor de la reina Ana de Austria contra las intrigas del cardenal Richelieu y de la implacable Milady de Winter. Un clásico de capa y espada que no envejece.", descriptionAi: true },
    { title: "Curso básico de tarot", author: "Varios autores", category: "Espiritualidad", coverId: 14625505, description: "Manual divulgativo para iniciarse en la lectura del tarot: significado simbólico de los arcanos mayores y menores, tiradas básicas como la cruz celta, nociones de interpretación intuitiva y consejos prácticos para llevar un cuaderno de lectura. Pensado para principiantes que se acercan al tarot desde la curiosidad simbólica.", descriptionAi: true },
    { title: "Cuentos de angustias y paisajes", author: "Carlos Salazar Herrera", category: "Cuentos", coverId: 6714606, description: "Colección clásica costarricense publicada en 1947. Los cuentos breves entrelazan el paisaje rural —ríos, cafetales, cordilleras— con vidas marcadas por la pasión, la culpa, la fatalidad y el silencio. Una prosa sobria y exacta convertida en piedra angular del cuento centroamericano del XX.", descriptionAi: true },
    { title: "Escepticismo", author: "Maria Lorenza Chiesara", category: "Filosofía", coverId: 8659112, description: "Recorrido por el escepticismo griego desde Pirrón de Elis hasta Sexto Empírico, y por la herencia de ese movimiento en la filosofía moderna y contemporánea. Explica las tropoi, la suspensión del juicio y la ataraxia como tradición de pensamiento que ha vuelto a ser pertinente en un mundo saturado de certezas.", descriptionAi: true },
    { title: "Infocracia", author: "Byung-Chul Han", category: "Filosofía / Sociedad", description: "Diagnóstico del régimen contemporáneo de información digital como una nueva forma de dominación que reemplaza a la disciplina y al panóptico clásicos. Las redes sociales, los algoritmos y las pantallas no liberan al individuo: lo confinan a una racionalidad numérica en la que cada gesto se vuelve dato y la democracia se vacía por dentro.", descriptionAi: true },
    { title: "El contrato social", author: "Jean-Jacques Rousseau", category: "Filosofía / Política", coverId: 5229289, description: "Tratado político fundacional de 1762: toda autoridad legítima nace del pacto entre individuos libres, y la voluntad general —no la voluntad de todos— es el fundamento de la soberanía popular. La argumentación recorre la propiedad, el legislador, los magistrados, la religión civil y los regímenes políticos para construir una teoría exigente de la libertad republicana. Texto matriz del pensamiento democrático moderno.", descriptionAi: true },
    { title: "¿Qué es el estoicismo?", author: "Tanner Campbell y Kai Whiting", category: "Filosofía / Estoicismo", description: "Introducción contemporánea a la filosofía estoica: sus orígenes en la Stoa Poikile ateniense, sus figuras (Zenón, Epicteto, Séneca, Marco Aurelio), sus ideas clave —la dicotomía del control, la virtud como único bien, el cosmopolitismo— y su utilidad práctica frente a los desafíos actuales del trabajo, el duelo, la incertidumbre y la política.", descriptionAi: true },
    { title: "La Odisea", author: "Homero", category: "Mitología", coverId: 13180792, description: "Poema homérico que sigue el regreso de Odiseo a Ítaca tras la caída de Troya: diez años de tormentas, cíclopes, sirenas, ninfas y dioses caprichosos antes del reencuentro con Penélope y Telémaco. La obra inaugura la novela de aventuras, la épica del retorno y el motivo de la astucia como virtud política y doméstica.", descriptionAi: true },
    { title: "El viaje de Shuna", author: "Hayao Miyazaki", category: "Manga", description: "Manga ilustrado en acuarelas suaves: un joven príncipe parte de su valle estéril, en una geografía himaláyica imaginaria, en busca de un grano dorado que pueda salvar a su pueblo del hambre. Por el camino conoce a una esclava llamada Thea y atraviesa paisajes míticos. Un cuento iniciático cargado de poesía visual y de una mitología que prefigura mucho del cine posterior del estudio Ghibli.", descriptionAi: true },
    { title: "El mito de Sísifo", author: "Albert Camus", category: "Filosofía", description: "Ensayo fundacional del absurdo. ¿Por qué seguir viviendo cuando el universo carece de sentido? La respuesta filosófica recorre el suicidio, la rebelión y el arte, y culmina en la figura mitológica de Sísifo: condenado a empujar una roca por la eternidad, encuentra su libertad en la repetición consciente del esfuerzo y en el rechazo a la consolación metafísica. Una de las cumbres del existencialismo francés.", descriptionAi: true },
    { title: "El temor de un hombre sabio", author: "Patrick Rothfuss", category: "Fantasía", description: "Segunda parte de la Crónica del asesino de reyes. Kvothe continúa narrando su biografía: la corte de Vintas, la guerra contra los bandidos en el bosque de Eld, la estancia en los Adem aprendiendo el Ketan y el encuentro con Felurian en los Fata. La voz íntima y musical de la prosa convierte cada capítulo en un poema largo y la promesa del tercer volumen sigue alimentando la paciencia de sus lectores.", descriptionAi: true },
    { title: "La música del silencio", author: "Patrick Rothfuss", category: "Fantasía", description: "Novela breve que sigue a Auri, la enigmática habitante de los túneles bajo la Universidad de la Crónica del asesino de reyes, durante siete días en los que ordena su mundo subterráneo. Sin diálogos ni casi acción, el relato avanza al ritmo de los objetos y los nombres que ella inventa, con una prosa muy cercana al poema en prosa.", descriptionAi: true },
    { title: "Rubicón", author: "Tom Holland", category: "Historia", coverId: 3324864, description: "Los últimos cincuenta años de la República romana: las guerras civiles, las ambiciones desmedidas de Sila, Pompeyo y César, y el cruce simbólico del río Rubicón que cambió la historia política de Occidente. Crónica vívida y bien documentada del momento en que una república mediterránea se transformó en imperio, escrita con narratividad y ritmo de novela.", descriptionAi: true },
    { title: "Maquinaria y mecanización agrícola", author: "Armando Alvarado Chaves", category: "Agricultura", description: "Texto técnico sobre tractores, implementos y maquinaria empleados en las distintas etapas del cultivo: preparación del suelo, siembra, fertilización, control de malezas, cosecha y poscosecha. Énfasis en la selección de equipos adecuados al trópico húmedo, su operación y su mantenimiento.", descriptionAi: true },
    { title: "Química agroindustrial I", author: "Hermes Alvarado Montero y Carlos Alberto Vega Aguilar", category: "Química / Agricultura", description: "Manual universitario que aborda los fundamentos químicos de las materias primas agrícolas y de los procesos industriales que las transforman en alimentos, fibras y otros productos. Cubre carbohidratos, lípidos, proteínas, agua y minerales como bloques constructivos del análisis bromatológico, con prácticas de laboratorio asociadas.", descriptionAi: true },
    { title: "Cartografía geológica de la Península de Nicoya: Estratigrafía y tectónica", author: "Denyer, Aguilar y Montero", category: "Geología", description: "Levantamiento geológico detallado de la península costarricense de Nicoya: secuencias estratigráficas del Cretácico al Cuaternario, fallas tectónicas activas, basamento oceánico de las terrazas marinas y la historia geológica que las formó. Texto de referencia para geólogos, ingenieros y planificadores territoriales de la región.", descriptionAi: true },
    { title: "Metodología de la investigación", author: "Hernández Sampieri, Fernández Collado y Baptista Lucio", category: "Metodología de investigación", coverId: 8076589, description: "Manual de referencia obligatoria en Iberoamérica: cubre los enfoques cuantitativo, cualitativo y mixto, los pasos del proceso de investigación —del planteamiento del problema al informe final— con ejemplos para tesis y proyectos académicos. Trae instrumentos, modelos de análisis y guías de redacción, y se usa en facultades de educación, salud y administración por igual.", descriptionAi: true },
    { title: "Las aventuras de Huckleberry Finn", author: "Mark Twain", category: "Novela clásica", coverId: 13482322, description: "Huck Finn y el esclavo fugitivo Jim recorren el Misisipi en una balsa, escapando cada uno de su propia versión de la civilización. El viaje retrata la sociedad sureña anterior a la Guerra Civil estadounidense con humor, crítica racial y una de las voces narrativas más originales jamás escritas en lengua inglesa.", descriptionAi: true },
    { title: "Sentido y sensibilidad", author: "Jane Austen", category: "Novela clásica", coverId: 10450935, description: "Primera novela publicada, ambientada en la campiña inglesa a finales del XVIII. Tras la muerte del padre, las hermanas Dashwood y su madre quedan en una situación económica difícil; Elinor (la prudente) y Marianne (la apasionada) navegan amores, decepciones y reveses sociales que ponen a prueba sus temperamentos. Comedia de costumbres con un trasfondo de crítica al destino económico de las mujeres.", descriptionAi: true }
];
